92	// ServerContext 析构：释放 DBus 连接与 service/weak_mgr 资源。
93	// 调用前提：所有捕获 ctx* 的监控线程已在 start_server() 退出路径完成 join，
94	// 之后才进入本析构，避免在回收线程访问尚未析构的成员。
95	ServerContext::~ServerContext() {
96	    // 注意：所有捕获 ctx* 的监控线程必须在调用此析构函数前已完成 join。
97	    // start_server() 通过 join_all → ctx 离开作用域的顺序保证这一点。
98	
99	    if (connection) {
100	        // 共享连接（dbus_bus_get 获取）不应调用 dbus_connection_close，
101	        // 只需 unref 释放引用。close 会导致 d-bus 守护进程报错 "Application
102	        // must not close shared connections"。
103	        dbus_connection_unref(connection);
104	        connection = nullptr;
105	    }
106	    // 智能指针自动释放，无需手动 delete
107	}
108	
109	// 共享列表迁移至 ServerContext，在 server.hpp 中定义
110	
111	// 使用 DbusService 替代手写处理函数
112	
113	// 将字符串作为方法返回，通过序列化保存到文件
114	// Get 方法处理已迁移到 DbusService
115	
116	// 发送 Changed 信号，并将载荷序列化到文件
117	// 发信号也迁移到 DbusService
118	
119	// 处理进入总线的消息（方法调用等）
120	// 消息处理迁移，由 DbusService::MessageHandler 提供
121	
