124	// 比较两个列表，打印新增与删除项，并返回是否有变化
125	static bool diffInterfaces(const std::vector<std::string>& old_list,
126	                           const std::vector<std::string>& new_list,
127	                           std::vector<std::string>& added,
128	                           std::vector<std::string>& removed) {
129	    added.clear();
130	    removed.clear();
131	
132	    for (const auto& it : new_list) {
133	        if (std::find(old_list.begin(), old_list.end(), it) == old_list.end()) added.push_back(it);
134	    }
135	    for (const auto& it : old_list) {
136	        if (std::find(new_list.begin(), new_list.end(), it) == new_list.end()) removed.push_back(it);
137	    }
138	    return !added.empty() || !removed.empty();
139	}
