141	// 独立接口：初始化 DBus、注册对象路径
142	DBusConnection* init_dbus(ServerContext* ctx) {
143	    LOG_INFO(LogModule::DBUS, "init_dbus: start connecting to system bus...");
144	    dbus_threads_init_default();
145	
146	    DBusError err;
147	    dbus_error_init(&err);
148	
149	    // 服务端以 root 系统服务运行（eBPF 需要 CAP_BPF/CAP_SYS_ADMIN），
150	    // 用户会话总线的生命周期与桌面/SSH 会话绑定且不允许 root 连接，
151	    // 因此统一使用系统总线（与 bt_monitor 访问 BlueZ 的拓扑一致）。
152	    DBusConnection* conn = dbus_bus_get(DBUS_BUS_SYSTEM, &err);
153	    if (dbus_error_is_set(&err)) {
154	        LOG_ERROR(LogModule::DBUS, "连接总线失败: " << err.message);
155	        dbus_error_free(&err);
156	    }
157	    if (!conn) return nullptr;
158	    LOG_INFO(LogModule::DBUS, "connected to system bus");
159	
160	    LOG_INFO(LogModule::DBUS, "requesting bus name: " << kBusName);
161	    int ret = dbus_bus_request_name(conn, kBusName, DBUS_NAME_FLAG_REPLACE_EXISTING, &err);
162	    if (dbus_error_is_set(&err)) {
163	        LOG_ERROR(LogModule::DBUS, "请求服务名失败: " << err.message);
164	        dbus_error_free(&err);
165	    }
166	    if (ret != DBUS_REQUEST_NAME_REPLY_PRIMARY_OWNER) {
167	        LOG_ERROR(LogModule::DBUS, "未能成为主拥有者，ret=" << ret);
168	        dbus_connection_unref(conn);
169	        return nullptr;
170	    }
171	
172	    // 使用服务类进行对象注册（保存到上下文，统一管理生命周期）
173	    LOG_INFO(LogModule::DBUS, "registering object path: " << kObjectPath << " (interface=" << kInterface << ")");
174	    ctx->service = std::make_unique<DbusService>(ctx);
175	    if (!ctx->service->register_on_connection(conn)) {
176	        LOG_ERROR(LogModule::DBUS, "注册对象路径失败");
177	        ctx->service.reset();
178	        dbus_connection_unref(conn);
179	        return nullptr;
180	    }
181	    // 指针已保存至 ctx
182	
183	    ctx->connection = conn;
184	    LOG_INFO(LogModule::DBUS, "DBus 服务端已启动，接口 " << kInterface << "，方法 " << kMethodListInterfaces << "，信号 " << kSignalChanged);
185	    return conn;
186	}
