188	// 独立接口：启动网卡监控线程（使用 WeakNetMgr 与 NetInfo）
189	void start_iface_monitor_thread(ServerContext* ctx, std::thread* worker) {
190	    *worker = std::thread([ctx](){
191	        LOG_INFO(LogModule::INTERFACE, "monitor thread started");
192	        std::vector<NetInfo> current;
193	        int32_t change_counter = 0;
194	
195	        while ((ctx->running.load() && !ctx->iface_stop.load())) {
196	            LOG_INFO(LogModule::INTERFACE, "tick: collecting interfaces...");
197	            std::vector<NetInfo> latest = ctx->weak_mgr->collectCurrentInterfaces();
198	            LOG_INFO(LogModule::INTERFACE, "collected " << latest.size() << " interfaces");
199	            
200	            // 持续输出关键指标信息
201	            for (const auto& net : latest) {
202	                if (net.usingNow()) {
203	                    LOG_INFO(LogModule::INTERFACE, "ACTIVE: " << net.ifName() 
204	                        << " | RTT: " << net.rttMs() << "ms" 
205	                        << " | Jitter: " << net.jitterMs() << "ms (" << net.jitterLevel() << ")"
206	                        << " | Quality: " << static_cast<int>(net.quality())
207	                        << " | RSSI: " << net.rssiDbm() << "dBm"
208	                        << " | TCP Loss: " << net.tcpLossRate() << "% (" << net.tcpLossLevel() << ")"
209	                        << " | Traffic: " << (net.trafficTotalBps() / (1024*1024)) << "MB/s, " 
210	                        << net.trafficActiveFlows() << " flows, " << net.trafficTotalPps() << " pps");
211	                } else {
212	                    LOG_INFO(LogModule::INTERFACE, "INACTIVE: " << net.ifName() 
213	                        << " | RTT: " << net.rttMs() << "ms" 
214	                        << " | Jitter: " << net.jitterMs() << "ms (" << net.jitterLevel() << ")"
215	                        << " | Quality: " << static_cast<int>(net.quality())
216	                        << " | RSSI: " << net.rssiDbm() << "dBm"
217	                        << " | TCP Loss: " << net.tcpLossRate() << "% (" << net.tcpLossLevel() << ")");
218	                }
219	            }
220	            auto old_names = WeakNetMgr::namesOf(current);
221	            auto new_names = WeakNetMgr::namesOf(latest);
222	            std::vector<std::string> added, removed;
223	            if (diffInterfaces(old_names, new_names, added, removed)) {
224	                current = latest;
225	                // 使用线程安全的方法更新接口列表
226	                ctx->weak_mgr->updateInterfaces(current);
227	                std::string msg = "Interfaces changed (using flags in log): +";
228	                for (size_t i = 0; i < added.size(); ++i) { msg += (i == 0 ? "" : ","); msg += added[i]; }
229	                msg += " -";
230	                for (size_t i = 0; i < removed.size(); ++i) { msg += (i == 0 ? "" : ","); msg += removed[i]; }
231	                LOG_INFO(LogModule::INTERFACE, msg);
232	                // 打印 using 标志
233	                for (const auto& x : current) {
234	                    if (x.usingNow()) {
235	                        LOG_INFO(LogModule::INTERFACE, "[using] " << x.ifName() << " is current uplink");
236	                    }
237	                }
238	                // 同步发射（内部有锁），不创建 detached 子线程；事件更新经 EventManager 同步
239	                if (ctx->service) {
240	                    ctx->service->emitChanged(msg, change_counter);
241	                    getEventManager().emitInterfaceChanged(msg, "network_manager");
242	                }
243	            } else {
244	                LOG_INFO(LogModule::INTERFACE, "no changes detected");
245	            }
246	            for (int i = 0; i < 100 && (ctx->running.load() && !ctx->iface_stop.load()); ++i)
247	                std::this_thread::sleep_for(100ms);
248	        }
249	    });
250	}
251	
252	// 独立接口：启动流量分析线程
253	void start_traffic_analysis_thread(ServerContext* ctx, std::thread* worker) {
254	    *worker = std::thread([ctx](){
255	        LOG_INFO(LogModule::WEAK_MGR, "traffic analysis thread started");
256	
257	        // 动态选择接口：优先使用配置，否则取当前活动接口
258	        std::string targetIface = kDefaultTrafficInterface;
259	        if (targetIface.empty()) {
260	            // 从 WeakNetMgr 获取当前活动接口
261	            auto interfaces = ctx->weak_mgr->getCurrentInterfaces();
262	            for (const auto& iface : interfaces) {
263	                if (iface.usingNow()) {
264	                    targetIface = iface.ifName();
265	                    break;
266	                }
267	            }
268	            if (targetIface.empty()) {
269	                targetIface = "wlan0";  // 兜底默认值
270	            }
271	        }
272	
273	        LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: using interface " << targetIface);
274	        // flow_rate.bpf.o 与 ProcessProfilerPlugin 共享同一份 map，使用 process_profiler
275	        // 配置块的定标参数解算容量计划；必须在 bpf_object__load 之前传入，
276	        // 否则 current_sec/process_stats 会保留内核编译期容量（真机核验发现的缺陷）
277	        ctx->weak_mgr->startTrafficAnalysis(
278	            targetIface,
279	            ctx->cfg.traffic.interval_ms.load() / 1000,
280	            weaknet::resolveScopePlan(
281	                weaknet::MapSizingScope::ProcessProfiler,
282	                {ctx->cfg.process_profiler.map_sizing.mode.get(),
283	                 ctx->cfg.process_profiler.map_sizing.entries.load(),
284	                 ctx->cfg.process_profiler.map_sizing.ram_budget_bp.load()},
285	                weaknet::totalPhysicalRamBytes()));
286	
287	        int loop_count = 0;
288	        while ((ctx->running.load() && !ctx->traffic_stop.load())) {
289	            loop_count++;
290	            LOG_INFO(LogModule::WEAK_MGR, "traffic analysis thread running, loop=" << loop_count);
291	            try {
292	                // 直接调用线程安全的流量分析更新方法
293	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: calling updateTrafficAnalysisSafe");
294	                bool changed = ctx->weak_mgr->updateTrafficAnalysisSafe();
295	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: updateTrafficAnalysisSafe completed, changed=" << changed);
296	
297	                // 获取当前接口列表用于日志输出
298	                auto current_interfaces = ctx->weak_mgr->getCurrentInterfaces();
299	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: current interfaces count=" << current_interfaces.size());
300	
301	                if (changed && ctx->service) {
302	                    LOG_INFO(LogModule::WEAK_MGR, "Traffic analysis updated - emitting signal");
303	                    // 同步发射（内部有锁），不创建 detached 子线程
304	                    ctx->service->emitChanged("Traffic analysis updated", /*counter*/0);
305	                } else {
306	                    LOG_INFO(LogModule::WEAK_MGR, "TRAFFIC_ANALYSIS: no changes detected (interfaces: " << current_interfaces.size() << ")");
307	                }
308	            } catch (const std::exception& e) {
309	                LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis error: " << e.what());
310	            }
311	
312	            for (int i = 0; i < static_cast<int>(ctx->cfg.traffic.interval_ms.load() / 100) && (ctx->running.load() && !ctx->traffic_stop.load()); ++i)
313	                std::this_thread::sleep_for(100ms);
314	        }
315	        ctx->weak_mgr->stopTrafficAnalysis();
316	        LOG_INFO(LogModule::WEAK_MGR, "traffic analysis thread stopped");
317	    });
318	}
