320	// 独立接口：启动"当前上网网卡"监控线程（使用 UsingInterfaceManager）
321	void start_using_iface_thread(ServerContext* ctx, std::thread* worker) {
322	    *worker = std::thread([ctx](){
323	        LOG_INFO(LogModule::WEAK_MGR, "monitor thread started");
324	
325	        int loop_count = 0;
326	        while ((ctx->running.load() && !ctx->using_iface_stop.load())) {
327	            loop_count++;
328	            LOG_INFO(LogModule::WEAK_MGR, "using iface thread running, loop=" << loop_count);
329	            
330	            // 直接调用线程安全的当前使用接口更新方法
331	            LOG_INFO(LogModule::WEAK_MGR, "using iface: calling updateCurrentUsingSafe");
332	            bool changed = ctx->weak_mgr->updateCurrentUsingSafe();
333	            LOG_INFO(LogModule::WEAK_MGR, "using iface: updateCurrentUsingSafe completed, changed=" << changed);
334	            
335	            // 获取当前接口列表用于日志输出
336	            auto current_interfaces = ctx->weak_mgr->getCurrentInterfaces();
337	            LOG_INFO(LogModule::WEAK_MGR, "using iface: current interfaces count=" << current_interfaces.size());
338	            
339	            if (changed && ctx->service) {
340	                // 查找当前使用的接口
341	                std::string currentIf;
342	                for (const auto& net : current_interfaces) {
343	                    if (net.usingNow()) {
344	                        currentIf = net.ifName();
345	                        break;
346	                    }
347	                }
348	                
349	                std::string msg = std::string("Using iface updated: ") + (currentIf.empty() ? "(none)" : currentIf);
350	                // 同步发射（内部有锁），不创建 detached 子线程
351	                ctx->service->emitChanged(msg, /*counter*/0);
352	                getEventManager().emitConnectionModeChanged(msg, currentIf.empty() ? "none" : currentIf);
353	            } else {
354	                LOG_INFO(LogModule::WEAK_MGR, "unchanged (interfaces: " << current_interfaces.size() << ")");
355	            }
356	            for (int i = 0; i < 100 && (ctx->running.load() && !ctx->using_iface_stop.load()); ++i)
357	                std::this_thread::sleep_for(100ms);
358	        }
359	    });
360	}
