362	// 独立接口：启动网络质量监控线程
363	void start_network_quality_thread(ServerContext* ctx, std::thread* worker) {
364	    *worker = std::thread([ctx](){
365	        LOG_INFO(LogModule::WEAK_MGR, "network assurance engine thread started (Phase 1)");
366	
367	        weaknet::StateStabilizer stabilizer;
368	        weaknet::HealthState lastStableState = weaknet::HealthState::UNKNOWN;
369	
370	        // 拓扑元数据 30 秒 TTL 缓存：避免每 15 秒评估循环都频繁调用 getifaddrs 和 wpa 命令
371	        std::chrono::steady_clock::time_point last_topo_time{};
372	        weaknet::TopologySnapshot cached_topo;
373	        std::string last_topo_iface;
374	
375	        int loop_count = 0;
376	        while ((ctx->running.load() && !ctx->quality_stop.load())) {
377	            loop_count++;
378	            try {
379	                // 无上行网卡时**不编造**一张网卡来评估：宁可本轮跳过并给出
380	                // 显式日志，也不要把某个不相关网卡的指标当成"当前网络体验"。
381	                // 此前默认 "wlan0" 再被列表首位覆盖，会在启动早期/路由抖动期间
382	                // 产出一份与实际链路无关的权威快照。
383	                std::string active_iface;
384	                if (ctx->weak_mgr) {
385	                    auto opt = ctx->weak_mgr->getCurrentUsingInterface();
386	                    if (opt.has_value()) active_iface = opt.value();
387	                }
388	                if (active_iface.empty()) {
389	                    LOG_WARNING(LogModule::WEAK_MGR,
390	                                "no interface is currently using the network; "
