407	                if (ctx->metrics_registry) {
408	                    using namespace std::chrono_literals;
409	                    auto reach_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::REACHABILITY_SUCCESS, 120s);
410	                    auto rtt_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::RTT_MS, 120s);
411	                    auto jitter_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::JITTER_MS, 120s);
412	                    auto wifi_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::WIFI_LOSS_RATE, 120s);
413	                    auto tcp_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::TCP_LOSS_RATE, 120s);
414	                    auto rssi_samples = ctx->metrics_registry->window(active_iface, weaknet::MetricId::RSSI_DBM, 120s);
415	
416	                    bool is_wireless = (active_iface.rfind("wl", 0) == 0);
417	                    auto reach_sle = weaknet::IpReachabilityEvaluator::evaluate(reach_samples);
418	                    auto resp_sle = weaknet::ResponsivenessEvaluator::evaluate(rtt_samples, jitter_samples);
419	                    auto rel_sle = weaknet::ReliabilityEvaluator::evaluate(wifi_samples, tcp_samples, is_wireless);
420	                    auto rf_sle = weaknet::RfHealthEvaluator::evaluate(rssi_samples, is_wireless);
