432	                            << " reason=" << dns_sle.reason
433	                            << " fail=" << dns_window.knownFailure() << "/" << dns_window.evaluableTerminals()
434	                            << " inflight=" << dns_window.current_inflight
435	                            << " ok=" << dns_window.knownSuccess()
436	                            << " unmatched=" << dns_window.unmatched
437	                            << " ambiguous=" << dns_window.tracking_ambiguous
438	                            << " late=" << dns_window.late_responses);
439	                    }
440	
441	                    // TCP Connect SLE：回答"DNS 解析出地址后，能否真的建立连接"。
442	                    // 与 DNS 同源纪律：证据不足 → UNKNOWN，观测不可靠 → UNKNOWN。
443	                    weaknet::SleResult tcp_sle;
444	                    {
445	                        std::shared_lock<std::shared_mutex> mon_lock(ctx->monitor_pointers_mutex);
446	                        if (ctx->tcp_connect_monitor) {
447	                            weaknet::TcpConnectEvaluator::Input tcp_in;
448	                            for (const auto& o : ctx->tcp_connect_monitor->recentObservations()) {
449	                                tcp_in.samples.push_back({o.success, o.latency_ms});
450	                            }
