465	                    // Passive TCP RTT SLE：已建立连接在数据传输阶段的内核平滑 srtt。
466	                    // 与主动 ICMP 探测（Responsiveness）分离：反映真实业务端到端传输时延。
467	                    weaknet::SleResult tcp_rtt_sle;
468	                    {
469	                        std::shared_lock<std::shared_mutex> mon_lock(ctx->monitor_pointers_mutex);
470	                        if (ctx->tcp_rtt_monitor && ctx->tcp_rtt_monitor->isAvailable()) {
