476	                                << " reason=" << tcp_rtt_sle.reason
477	                                << " p50=" << rtt_summary.p50RttUs << "us"
478	                                << " p90=" << rtt_summary.p90RttUs << "us"
479	                                << " conns=" << rtt_summary.activeConns
480	                                << " samples=" << rtt_summary.totalSamples);
481	                        }
482	                    }
483	
484	                    // HTTP/HTTPS Access SLE：TCP 通了不代表应用层可用。
485	                    // 语义边界：4xx 是业务语义（服务端正常应答），只有 5xx 与
486	                    // 无响应/TLS 失败才算传输层故障。
487	                    weaknet::SleResult http_sle;
488	                    weaknet::SleResult portal_sle;
489	                    {
490	                        std::shared_lock<std::shared_mutex> mon_lock(ctx->monitor_pointers_mutex);
491	                        if (ctx->http_latency_monitor) {
492	                            weaknet::HttpAccessEvaluator::Input http_in;
