498	                            http_sle = weaknet::HttpAccessEvaluator::evaluate(http_in);
499	
500	                            // Captive Portal：**当前不具备可靠判定能力**。
501	                            //
502	                            // 可靠的 portal 判定需要受控探测（向已知 connectivity-check
