509	                            portal_in.has_controlled_probe = false;
510	                            portal_in.ip_reachable = (reach_sle.state == weaknet::HealthState::GOOD);
511	                            portal_in.dns_resolvable = (dns_sle.state == weaknet::HealthState::GOOD);
512	                            portal_in.tcp_connectable = (tcp_sle.state == weaknet::HealthState::GOOD);
513	                            portal_sle = weaknet::CaptivePortalEvaluator::evaluate(portal_in);
514	
515	                            LOG_INFO(LogModule::NETWORK, "HTTP SLE: state="
516	                                << weaknet::healthStateToString(http_sle.state)
517	                                << " coverage=" << weaknet::coverageToString(http_sle.coverage)
518	                                << " reason=" << http_sle.reason
519	                                << " samples=" << txns.size()
520	                                << " | Portal: " << weaknet::healthStateToString(portal_sle.state)
521	                                << " reason=" << portal_sle.reason);
522	                        }
523	                    }
524	
525	                    // 受控主动探测：host-level Internet 能力的唯一证据来源。
