539	                        acfg.underlying_healthy =
540	                            reach_sle.state != weaknet::HealthState::BAD
541	                            && rel_sle.state != weaknet::HealthState::BAD
542	                            && dns_sle.state != weaknet::HealthState::BAD;
543	                        active = weaknet::ActiveConnectivityEvaluator::evaluate(
