568	                    exp = weaknet::OverallPolicy::decide(active_iface, reach_sle, resp_sle, rel_sle,
569	                                                         rf_sle, dns_sle, tcp_sle, tcp_rtt_sle,
570	                                                         http_sle, portal_sle,
571	                                                         active.dns, active.tcp,
572	                                                         active.https, active.portal,
573	                                                         currentAssessmentProfile(*ctx));
574	                    if (!rtt_samples.empty()) newest_rev = rtt_samples.back().sequence;
575	                    else if (!reach_samples.empty()) newest_rev = reach_samples.back().sequence;
576	                } else {
