651	            // 2.4GHz 频段冲突检测（Phase 1a）
652	            // 关联 Wi-Fi RSSI 与蓝牙 RSSI，识别共享频段干扰
653	            // ================================================================
654	            try {
655	                // 使用 thread_local 确保检测器状态在循环间保持
656	                static thread_local BandConflictDetector conflictDetector;
657	
658	                // 获取当前上网接口的 Wi-Fi RSSI 与频段感知
659	                int wifiRssi = -1000;
660	                std::string activeWifiIface;
661	                {
662	                    auto interfaces = ctx->weak_mgr->getCurrentInterfaces();
663	                    for (const auto& iface : interfaces) {
664	                        if (iface.usingNow() && iface.hasRssi()) {
665	                            wifiRssi = iface.rssiDbm();
666	                            activeWifiIface = iface.ifName();
667	                            break;
668	                        }
669	                    }
670	                    // 若无 usingNow 接口，退而取第一个有 RSSI 的 Wi-Fi 接口
671	                    if (wifiRssi <= -1000) {
672	                        for (const auto& iface : interfaces) {
673	                            if (iface.hasRssi()) {
674	                                wifiRssi = iface.rssiDbm();
675	                                activeWifiIface = iface.ifName();
676	                                break;
677	                            }
678	                        }
679	                    }
680	                }
681	
682	                // 探测当前 Wi-Fi 工作频段（2.4GHz / 5GHz / 6GHz）
683	                std::string wifiBand = "2.4GHz";
684	                if (!activeWifiIface.empty()) {
685	                    auto wifiClient = WiFiRssiClient::getInstance();
686	                    if (wifiClient) {
687	                        int freq = wifiClient->getFrequency();
688	                        if (freq >= 5000 && freq <= 5900) {
689	                            wifiBand = "5GHz";
690	                        } else if (freq >= 5925 && freq <= 7125) {
691	                            wifiBand = "6GHz";
692	                        } else if (freq >= 2400 && freq <= 2500) {
693	                            wifiBand = "2.4GHz";
694	                        }
695	                    }
696	                }
697	
698	                // 获取蓝牙 RSSI（取所有已连接设备的平均 RSSI）
699	                int btRssi = -1000;
700	                {
701	                    std::shared_lock<std::shared_mutex> bt_lock(ctx->monitor_pointers_mutex);
702	                    if (auto* mon = ctx->bt_monitor; mon && mon->isInitialized()) {
703	                        auto rssiSnapshot = mon->getRssiSnapshot();
704	                        int sum = 0, count = 0;
705	                        for (const auto& [mac, rssi] : rssiSnapshot) {
706	                            if (rssi != 0 && rssi > -1000) {
707	                                sum += rssi;
708	                                ++count;
709	                            }
710	                        }
711	                        if (count > 0) {
712	                            btRssi = sum / count;
713	                        }
714	                    }
715	                }
716	
717	                // 推入样本并检测
718	                if (wifiRssi > -1000 && btRssi > -1000) {
719	                    conflictDetector.feedSample(wifiRssi, btRssi);
720	                }
721	
722	                auto conflictResult = conflictDetector.detect(wifiBand);
723	                conflictResult.wifiIface = activeWifiIface;
724	                {
725	                    std::lock_guard<std::mutex> lock(ctx->conflict_mutex);
726	                    std::ostringstream oss;
727	                    oss << "{"
728	                        << "\"detected\":" << (conflictResult.detected ? "true" : "false") << ","
729	                        << "\"confidence\":" << conflictResult.confidence << ","
730	                        << "\"correlation\":" << conflictResult.correlation << ","
731	                        << "\"wifi_rssi_drop\":" << conflictResult.wifiRssiDrop << ","
732	                        << "\"bt_rssi_drop\":" << conflictResult.btRssiDrop << ","
733	                        << "\"wifi_iface\":\"" << conflictResult.wifiIface << "\","
734	                        << "\"wifi_band\":\"" << conflictResult.wifiBand << "\","
735	                        << "\"bt_mac\":\"" << conflictResult.btMac << "\","
736	                        << "\"bt_audio_active\":" << (conflictResult.btAudioActive ? "true" : "false") << ","
737	                        << "\"suggestion\":\"" << conflictResult.suggestion << "\""
738	                        << "}";
739	                    ctx->latest_conflict_json = oss.str();
740	                }
741	
742	                if (conflictResult.detected && conflictResult.confidence > 50.0) {
743	                    LOG_INFO(LogModule::WEAK_MGR,
744	                             "2.4GHz band conflict detected: confidence="
745	                             << conflictResult.confidence
746	                             << "%, correlation=" << conflictResult.correlation
747	                             << ", wifiDrop=" << conflictResult.wifiRssiDrop
748	                             << "dBm, btDrop=" << conflictResult.btRssiDrop << "dBm");
749	
750	                    getEventManager().emitNetworkQualityChanged(
751	                        "2.4GHz band conflict detected",
752	                        conflictResult.suggestion,
753	                        "band_conflict_detector"
754	                    );
755	                }
756	            } catch (const std::exception& e) {
757	                LOG_ERROR(LogModule::WEAK_MGR,
758	                          "频段冲突检测错误: " << e.what());
759	            }
