813	// ====================================================================
814	// eBPF 监控器线程启动函数
815	// 将此前孤立的 BPF 监控器纳入 ServerContext 统一生命周期
816	// ====================================================================
817	
818	// 把 PerKeyStats 差分结果以 JSON 字段形式拼进 ostr；仅当监控器启用了
819	// 驱逐可见性（max_entries 或 entries 非零）才输出，区分"未启用"与"本轮无变化"。
820	static void appendEvictionJson(std::ostringstream& os, const weaknet::PerKeyStats& ks) {
821	    if (ks.max_entries == 0 && ks.entries == 0) return;
822	    os << ",\"eviction\":{\"new_keys\":" << ks.new_keys
823	       << ",\"disappeared_keys\":" << ks.disappeared_keys
824	       << ",\"reset_keys\":" << ks.reset_keys
825	       << ",\"entries\":" << ks.entries
826	       << ",\"max_entries\":" << ks.max_entries
827	       << ",\"watermark_pct\":" << ks.watermark_pct
828	       << ",\"eviction_limited\":" << (ks.eviction_limited ? "true" : "false")
829	       << "}";
830	}
831	
832	// 向 D-Bus 发射一条 eBPF 监控器聚合指标信号。
833	// payload 是 JSON 文本（EbpfMonitorStats 信号的契约载体），counter 走全局事件计数器。
834	static void emitEbpfStats(ServerContext* ctx, const char* monitor_name,
835	                          const std::string& stats_json, int32_t counter) {
836	    if (!ctx->service) return;
837	    std::ostringstream os;
838	    os << "{\"monitor\":\"" << weaknet_utils::escapeJsonString(monitor_name)
839	       << "\"," << stats_json << "}";
840	    ctx->service->emitSpecificSignal(kSignalEbpfMonitorStats, os.str(), counter);
841	}
