843	void start_dns_monitor_thread(ServerContext* ctx, std::thread* worker, DnsMonitor* monitor) {
844	    // 监控器由 ServerContext 持有 ownership（unique_ptr），线程仅通过 .get() 使用。
845	    // 这消除了旧方案中「线程销毁 unique_ptr 后、store(nullptr) 前」的悬垂指针窗口。
846	    *worker = std::thread([ctx, monitor]() {
847	        // The plugin owns this monitor; the worker borrows it until join.
848	        if (!monitor) return;
849	        LOG_INFO(LogModule::NETWORK, "DNS monitor thread started");
850	
851	        constexpr int kTickMs = 100;         // 循环粒度
852	        constexpr int kSweepEveryTicks = 10; // 每 1s 扫描一次超时（约等于 query_timeout 的分辨率需求）
853	        int tick_in_interval = 0;            // 位于当前 interval 内的第几个 tick
854	        int sweep_accum = 0;                 // 距上次 sweep 的 tick 数
855	        int diag_accum = 0;                  // 距上次 diag 的 tick 数
856	
857	        while ((ctx->running.load() && !ctx->dns_stop.load())) {
858	            if (ctx->dns_monitor && ctx->dns_tracker) {
859	                // perf buffer 每 tick 排空一次。原先只在 interval 边界排空一次，
860	                // 导致突发 syscall 在 10s 内填满 ring buffer 而丢事件。
861	                auto drained = ctx->dns_monitor->drainEvents(ctx->dns_tracker.get());
862	                if (drained > 0) {
863	                    LOG_INFO(LogModule::NETWORK, "DNS events drained=" << drained);
864	                }
865	
866	                if (++sweep_accum >= kSweepEveryTicks) {
867	                    sweep_accum = 0;
868	                    ctx->dns_tracker->sweepTimeouts();
869	                    // 观测质量增量随 sweep 节奏（每秒）汇入，避免每 tick 都读 BPF map。
870	                    ctx->dns_monitor->feedTransportDelta(ctx->dns_tracker.get());
871	                }
872	
873	                const int diag_every_ticks = std::max(1, static_cast<int>(ctx->cfg.dns.interval_ms.load() / kTickMs));
874	                if (++diag_accum >= diag_every_ticks) {
875	                    diag_accum = 0;
876	                    LOG_INFO(LogModule::NETWORK, "dns-capture diag: "
877	                        << ctx->dns_monitor->getCaptureDiagnostics());
878	                }
879	            }
880	
881	            // interval 边界：输出聚合 tick 日志（保持原有观测节奏）
882	            if (++tick_in_interval * kTickMs >= static_cast<int>(ctx->cfg.dns.interval_ms.load())) {
883	                tick_in_interval = 0;
884	                auto stats = monitor->getStats();
885	                if (stats.totalQueries > 0) {
886	                    LOG_INFO(LogModule::NETWORK, "DNS tick: queries=" << stats.totalQueries
887	                        << " avgLatency=" << stats.avgLatencyMs << "ms"
888	                        << " timeoutRate=" << stats.timeoutRate() << "%");
889	
890	                    // 细粒度信号：订阅方可以拿到聚合指标 + 驱逐差分，替代轮询 GetDnsStats。
891	                    std::ostringstream os;
892	                    os << "\"total_queries\":" << stats.totalQueries
893	                       << ",\"total_responses\":" << stats.totalResponses
894	                       << ",\"total_timeouts\":" << stats.totalTimeouts
895	                       << ",\"total_errors\":" << stats.totalErrors
896	                       << ",\"avg_latency_ms\":" << stats.avgLatencyMs
897	                       << ",\"max_latency_ms\":" << stats.maxLatencyMs
898	                       << ",\"timeout_rate_pct\":" << stats.timeoutRate();
899	                    appendEvictionJson(os, monitor->keyStatsSnapshot());
900	                    emitEbpfStats(ctx, "dns", os.str(), 0);
901	                }
902	            }
903	
904	            std::this_thread::sleep_for(std::chrono::milliseconds(kTickMs));
905	        }
906	        monitor->stop();
907	        LOG_INFO(LogModule::NETWORK, "DNS monitor thread stopped");
908	    });
909	}
