911	void start_wifi_loss_monitor_thread(ServerContext* ctx, std::thread* worker, WifiPacketLossMonitor* monitor) {
912	    *worker = std::thread([ctx, monitor]() {
913	        // The plugin owns this monitor; the worker borrows it until join.
914	        if (!monitor) return;
915	        LOG_INFO(LogModule::NETWORK, "Wi-Fi loss monitor thread started");
916	        // 每接口独立的累计计数器归一化器：把驱动层 since-boot 计数器转成
917	        // 采样周期增量丢包率。处理首轮基线、计数器倒退（probe 重载/网卡重置）
918	        // 与零活动（无发包周期不产出伪 rate）。
919	        std::map<uint32_t, weaknet::CounterNormalizer> normalizers;
920	        while ((ctx->running.load() && !ctx->wifi_loss_stop.load())) {
921	            auto stats = monitor->getStats();
922	            for (auto& [ifindex, s] : stats) {
923	                // 驱动计数分母 = 成功发包 + 丢包（txDrops 不含在 txPkts 内）
924	                auto rate = normalizers[ifindex].update(
925	                    s.txPkts + s.txDrops, s.txDrops);
926	                if (!rate.has_value()) continue;  // 首轮基线 / 计数器回退 / 无活动
927	                double txLoss = rate->rate_percent;
928	                if (txLoss > 0.1) {
929	                    LOG_INFO(LogModule::NETWORK, "Wi-Fi loss tick: ifindex=" << ifindex
930	                        << " txLoss=" << txLoss << "%"
931	                        << " Δdrops=" << rate->delta_drops << "/" << rate->delta_packets);
932	                }
933	
934	                char ifname[IF_NAMESIZE] = {0};
935	                if (if_indextoname(ifindex, ifname) != nullptr && ifname[0] != '\0') {
936	                    if (ctx->metrics_registry) {
937	                        ctx->metrics_registry->publish(
938	                            ifname,
939	                            weaknet::MetricId::WIFI_LOSS_RATE,
940	                            weaknet::MetricSample::valid(txLoss)
941	                        );
942	                    }
943	                }
944	            }
945	            for (int i = 0; i < static_cast<int>(ctx->cfg.wifi_loss.interval_ms.load() / 100) && (ctx->running.load() && !ctx->wifi_loss_stop.load()); ++i)
946	                std::this_thread::sleep_for(100ms);
947	        }
948	        monitor->stop();
949	        LOG_INFO(LogModule::NETWORK, "Wi-Fi loss monitor thread stopped");
950	    });
951	}
