1162	void start_history_persistence_thread(ServerContext* ctx) {
1163	    ctx->history_thread = std::thread([ctx](){
1164	        LOG_INFO(LogModule::SYSTEM, "History persistence thread started");
1165	
1166	        while (ctx->running.load()) {
1167	            // 每 5 秒持久化一轮（每秒检查 running 标志以便快速退出）
1168	            for (int i = 0; i < 5 && ctx->running.load(); ++i) {
1169	                std::this_thread::sleep_for(1s);
1170	            }
1171	            if (!ctx->running.load()) break;
1172	
1173	            if (!ctx->db_mgr || !ctx->db_mgr->isOpen()) continue;
1174	
1175	            // 获取当前接口快照并计算质量评分 (CR-3, HR-9)
1176	            auto snapshot = ctx->weak_mgr->getCurrentInterfaces();
1177	            // 无上行时不编造网卡名：写进行里的 iface 必须是真的在用的那张。
1178	            // 真正决定写入哪一行的是下面 isCurrent() + usingNow() 判定，
1179	            // 这里的 active_iface 只服务于"无有效快照"时的占位说明。
1180	            std::string active_iface;
1181	            auto opt = ctx->weak_mgr->getCurrentUsingInterface();
1182	            if (opt.has_value()) active_iface = opt.value();
1183	
1184	            // W2 单一事实源：history persistence **只读权威快照**，绝不重新 evaluate。
1185	            // 此前本线程现场只拉 5 个 Core SLE 调 OverallPolicy（无 DNS/TCP/HTTP/Active），
1186	            // 与 quality 线程、HealthCheck 构成三条结论可能不一致的评估路径 ——
1187	            // DB 中写入的是"只有 5 个 SLE 的旧结论"（既有 bug，本处修复）。
1188	            // 原始 metrics 与 assessment **同代冻结**：同一 snapshot 的 experience
1189	            // 提供结论，registry 的 latest 值仅作快照内的指标补充且由 snapshot 时刻界定。
1190	            weaknet::NetworkExperience exp;
1191	            auto snap = ctx->assessment_store.latest();
1192	            const bool snap_valid = snap && weaknet::AssessmentSnapshotStore::isCurrent(*snap,
1193	                    ctx->cfg.config_generation.load(),
1194	                    ctx->dns_tracker ? ctx->dns_tracker->currentBindingEpoch()
1195	                                     : ctx->dns_binding_epoch.load());
1196	            if (snap_valid) {
1197	                exp = snap->experience;
1198	            } else {
1199	                exp.iface = active_iface;
1200	                exp.overall = weaknet::HealthState::UNKNOWN;
1201	                exp.display_score = 50;
1202	                exp.primary_issue = snap ? "stale_assessment" : "no_assessment_yet";
1203	                // 无有效快照时 exp 是默认构造的，其 assessment_profile 会回落
1204	                // 到结构体默认值 INTERNET_ACCESS —— 那是一个编造的 profile。
1205	                // 审计元数据必须如实反映设备实际配置，故这里显式取权威值。
1206	                exp.assessment_profile = currentAssessmentProfile(*ctx);
1207	            }
1208	
1209	            double cur_jitter = 0.0;
1210	            if (ctx->metrics_registry) {
1211	                auto j_s = ctx->metrics_registry->latest(active_iface, weaknet::MetricId::JITTER_MS);
1212	                if (j_s.has_value() && j_s->state == weaknet::MetricState::VALID) cur_jitter = j_s->value;
1213	            }
1214	
1215	            NetworkQualityResult qualityResult = weaknet::LegacyAdapter::toQualityResult(exp, -1, 0.0, -1000, cur_jitter);
1216	
1217	            int written = 0;
1218	            for (const auto& iface : snapshot) {
1219	                if (iface.usingNow()) {
1220	                    if (ctx->db_mgr->insertSnapshot(iface.ifName(), iface, qualityResult,
1221	                                                               iface.generation(), iface.lastUpdatedMs(),
1222	                                                               iface.rttSampleTsMs(), iface.rssiSampleTsMs(),
1223	                                                               iface.jitterSampleTsMs(), iface.tcpLossSampleTsMs(),
1224	                                                               iface.trafficSampleTsMs(),
1225	                                                               weaknet::assessmentProfileToString(
1226	                                                                   exp.assessment_profile))) {
1227	                        written++;
1228	                    }
1229	                }
1230	            }
1231	            if (written > 0) {
1232	                LOG_INFO(LogModule::SYSTEM, "History persistence: wrote " << written << " records");
1233	            }
1234	
1235	            // 持久化蓝牙设备与音频质量快照
1236	            {
1237	                std::shared_lock<std::shared_mutex> bt_lock(ctx->monitor_pointers_mutex);
1238	                if (ctx->bt_monitor && ctx->bt_monitor->isInitialized()) {
1239	                    auto adapter = ctx->bt_monitor->getAdapterState();
1240	                    auto devices = ctx->bt_monitor->getDevices();
1241	                    int bt_written = 0;
1242	                    for (const auto& dev : devices) {
1243	                        // 仅记录已连接设备，或信号较强/活跃设备，避免周围瞬态广播垃圾数据占满 DB
1244	                        if (dev.connected || dev.rssiDbm > -75) {
1245	                            BtAudioFusionResult fusion;
1246	                            bool hasAudio = ctx->bt_monitor->getAudioFusionResult(dev.macAddress, &fusion);
1247	                            if (ctx->db_mgr->insertBtSnapshot(
1248	                                    adapter.macAddress,
1249	                                    dev.macAddress,
1250	                                    dev.name.empty() ? dev.alias : dev.name,
1251	                                    dev.connected,
1252	                                    dev.rssiDbm,
1253	                                    dev.estimatedDistance,
1254	                                    hasAudio && fusion.isActive,
1255	                                    hasAudio ? fusion.qualityScore : 0.0,
1256	                                    hasAudio && fusion.suspectedStall,
1257	                                    hasAudio ? fusion.bytesPerSec : 0,
1258	                                    hasAudio ? fusion.maxGapMs : 0)) {
1259	                                bt_written++;
1260	                            }
1261	                        }
1262	                    }
1263	                    if (bt_written > 0) {
1264	                        LOG_INFO(LogModule::SYSTEM, "History persistence: wrote " << bt_written << " Bluetooth records");
1265	                    }
1266	                }
1267	            }
1268	
1269	            // 每天清理一次过期日志文件
1270	            auto now = std::chrono::steady_clock::now();
1271	            static auto last_log_cleanup = std::chrono::steady_clock::now();
1272	            if (now - last_log_cleanup > std::chrono::hours(24)) {
1273	                int log_deleted = Logger::cleanOldLogs("./logs/server", 7);
1274	                last_log_cleanup = now;
1275	                if (log_deleted > 0) {
1276	                    LOG_INFO(LogModule::SYSTEM, "History persistence: cleaned " << log_deleted << " old log files");
1277	                }
1278	            }
1279	        }
1280	
1281	        LOG_INFO(LogModule::SYSTEM, "History persistence thread stopped");
1282	    });
1283	}
1284	
1285	// 启动服务
1286	int start_server(int argc, char** argv) {
1287	    // 解析命令行参数：--config <path>（默认 /etc/weaknet/config.yaml）
1288	    std::string config_path = "/etc/weaknet/config.yaml";
1289	    for (int i = 1; i + 1 < argc; ++i) {
1290	        if (std::string(argv[i]) == "--config") {
1291	            config_path = argv[i + 1];
1292	            ++i;
1293	        }
1294	    }
1295	    // 配置失败 → 直接退出，不写日志（init 还没起）
1296	    // 注意：此函数内已有 ctx 之前不能 LOG_*
1297	    std::cerr << "Loading config from: " << config_path << std::endl;
1298	
1299	    // 解析日志级别（用于 Logger::init）
1300	    LogLevel log_level = LogLevel::INFO;
1301	    if (!parseLogLevel("info", &log_level)) log_level = LogLevel::INFO;
1302	
1303	    // 初始化日志系统
1304	    if (!Logger::init("server", "./logs/server", log_level, true)) {
1305	        std::cerr << "Failed to initialize logger" << std::endl;
1306	        return 1;
1307	    }
1308	
1309	    // 启动带时间戳的文件日志
1310	    Logger::startFileLog("./server/log");
1311	
1312	    // 全局网络与通信库初始化（单线程早期调用）
1313	    weaknet::EdgeTelemetryExporter::initGlobal();
1314	
1315	    // 启动时清理 7 天前的日志文件
1316	    int cleaned = Logger::cleanOldLogs("./logs/server", 7);
1317	    if (cleaned > 0) {
1318	        LOG_INFO(LogModule::SYSTEM, "Cleaned " << cleaned << " old log files on startup");
1319	    }
1320	
1321	    // 注册信号处理函数（SIGINT/SIGTERM）
1322	    std::signal(SIGINT, Logger::signalHandler);
1323	    std::signal(SIGTERM, Logger::signalHandler);
1324	
1325	    ServerContext ctx;
1326	
1327	    // 加载配置文件（文件不存在 → 默认值；存在但语法错 → exit 1）
1328	    {
1329	        std::string cfg_err;
1330	        if (!loadWeakNetConfig(config_path, &ctx.cfg, &cfg_err)) {
1331	            std::cerr << "Configuration error in " << config_path << ": " << cfg_err << std::endl;
1332	            LOG_ERROR(LogModule::SYSTEM, "Configuration error in " << config_path << ": " << cfg_err);
1333	            return 2;
1334	        }
1335	        LOG_INFO(LogModule::SYSTEM, "Config loaded from: " << config_path
1336	            << " (dbus name: " << kBusName << ")");
1337	
1338	        // 应用日志级别（配置文件覆盖默认）
1339	        LogLevel new_level;
1340	        if (parseLogLevel(ctx.cfg.log_level.get(), &new_level)) {
1341	            Logger::setLogLevel(new_level);
1342	            LOG_INFO(LogModule::SYSTEM, "Log level from config: " << ctx.cfg.log_level.get());
1343	        } else if (!ctx.cfg.log_level.get().empty()) {
1344	            LOG_WARNING(LogModule::SYSTEM,
1345	                "Unknown log_level '" << ctx.cfg.log_level.get() << "', keeping default INFO");
1346	        }
1347	
1348	        // IR-3: assessment profile 合法性校验（权威值始终是 cfg.dns.assessment_profile，
1349	        // 不再拷贝到独立成员——拷贝会让运行时 SetMonitorParam 静默失效）。
1350	        // 非法值仅告警并按 INTERNET_ACCESS 回落，由 parseAssessmentProfile 统一实现。
1351	        {
1352	            const std::string p = ctx.cfg.dns.assessment_profile.get();
1353	            if (p == "NETWORK_ONLY" || p == "INTERNET_ACCESS") {
1354	                LOG_INFO(LogModule::SYSTEM, "Assessment profile from config: " << p);
1355	            } else {
1356	                LOG_WARNING(LogModule::SYSTEM, "Unknown assessment_profile '" << p
1357	                            << "', falling back to INTERNET_ACCESS");
1358	            }
1359	        }
1360	    }
1361	
1362	    if (!init_dbus(&ctx)) return 1;
1363	
1364	    // 启动事件监控
1365	    getEventManager().startEventMonitoring(&ctx);
1366	
1367	    // 初始化 MetricsRegistry 与 WeakNetMgr (MR-1, MR-2, HR-4)
1368	    ctx.metrics_registry = std::make_unique<weaknet::MetricsRegistry>();
1369	    ctx.dns_tracker = std::make_unique<weaknet::DnsTransactionTracker>();
1370	    ctx.weak_mgr = std::make_unique<WeakNetMgr>(ctx.metrics_registry.get());
1371	
1372	    // 网络代次跨重启推进（W-edge 上行去重的正确性前提）。
1373	    uint64_t persistent_epoch = 1;
1374	    {
1375	        weaknet::NetworkEpochStore epoch_store(resolveNetworkEpochPath(ctx.cfg.data_dir.get()));
1376	        persistent_epoch = epoch_store.open();
1377	        ctx.dns_binding_epoch.store(persistent_epoch);
1378	        // dns_tracker 的 binding epoch 初值为 1，运行中由路由/解析器变化推进。
1379	        // 持久化值只在更大时才生效（advanceBindingEpoch 内部拒绝回退），
1380	        // 因此这里把两者对齐到同一个下界。
1381	        ctx.dns_tracker->advanceBindingEpoch(persistent_epoch);
1382	    }
1383	
1384	    // 初始化端侧确定性诊断引擎与证据生成服务
1385	    {
1386	        std::string dev_id = ctx.cfg.edge.device_id.get();
1387	        if (dev_id.empty()) {
1388	            dev_id = "radxa-cubie-a7a";
1389	        }
1390	        ctx.action_registry = std::make_shared<weaknet::ActionRegistry>();
1391	        ctx.diagnosis_engine = std::make_unique<weaknet::DiagnosisEngine>(
1392	            weaknet::RuleLoader::loadDefaultRules(), ctx.action_registry);
1393	        ctx.evidence_id_generator = std::make_unique<weaknet::EvidenceIdGenerator>(
1394	            dev_id, persistent_epoch, true);
1395	        LOG_INFO(LogModule::SYSTEM, "DiagnosisEngine & ActionRegistry initialized for device: " << dev_id);
1396	    }
1397	
1398	    // 启动 UsingInterfaceManager（一次性启动，不重复调用 start()）
1399	    UsingInterfaceManager::getInstance()->start();
1400	
1401	    // 初始化历史数据持久化管理器（智能指针）
1402	    const std::string db_path = resolveDatabasePath(ctx.cfg.data_dir.get());
1403	    LOG_INFO(LogModule::SYSTEM, "initializing database manager (path=" << db_path << ")");
1404	    ctx.db_mgr = std::make_unique<DatabaseManager>(db_path);
1405	    if (ctx.db_mgr->isOpen()) {
1406	        LOG_INFO(LogModule::SYSTEM, "database manager opened, records=" << ctx.db_mgr->getRecordCount());
1407	    } else {
1408	        LOG_WARNING(LogModule::SYSTEM, "database manager failed to open, history persistence disabled");
1409	    }
1410	
1411	    // ================================================================
1412	    // 受控主动连通性探测：宿主 Internet 能力证据的唯一来源
1413	    // 默认关闭；targets 为空时不启用（不内置任何第三方默认目标，
1414	    // 避免第三方服务异常被误读为 Internet 故障）。
1415	    // ================================================================
1416	    {
1417	        ctx.active_probe = std::make_unique<ActiveConnectivityMonitor>();
1418	        applyActiveProbeConfig(&ctx);
1419	        start_active_probe_thread(&ctx, &ctx.active_probe_thread);
1420	    }
1421	
1422	    // 初始化接口列表到WeakNetMgr中
1423	    LOG_INFO(LogModule::WEAK_MGR, "initializing interface list...");
1424	    auto initial_interfaces = ctx.weak_mgr->collectCurrentInterfaces();
1425	    ctx.weak_mgr->updateInterfaces(initial_interfaces);
1426	    LOG_INFO(LogModule::WEAK_MGR, "interface list initialized with " << initial_interfaces.size() << " interfaces");
1427	
1428	    // ================================================================
1429	    // 监控器插件化启动：注册内置插件 → 实例化（按 order 排序）→ init → start
1430	    // ================================================================
1431	    registerBuiltinPlugins();
1432	    registerEbpfPlugins();
1433	    ctx.monitor_manager = std::make_unique<MonitorManager>(
1434	        &ctx, instantiateAllPlugins());
1435	    const std::string db_path_for_overrides = resolveDatabasePath(ctx.cfg.data_dir.get());
1436	    const std::string base_dir_for_overrides =
1437	        db_path_for_overrides.substr(0, db_path_for_overrides.size() - std::string("history.db").size());
1438	    ctx.monitor_manager->setOverridePath(base_dir_for_overrides + "runtime-overrides.bin");
1439	    // 生命周期状态变化 → D-Bus MonitorStateChanged 信号（携带 "name:state"）。
1440	    ctx.monitor_manager->setStateChangeCallback(
1441	        [&ctx](const std::string& name, const std::string& state) {
1442	            if (ctx.service) {
1443	                ctx.service->emitSpecificSignal(kSignalMonitorStateChanged, name + ":" + state, 0);
1444	            }
1445	        });
1446	    if (!ctx.monitor_manager->loadOverrides(nullptr)) {
1447	        LOG_WARNING(LogModule::SYSTEM, "runtime monitor overrides could not be loaded");
1448	    }
1449	    if (!ctx.monitor_manager->startConfigured()) {
1450	        LOG_WARNING(LogModule::NETWORK,
1451	                    "one or more monitor plugins failed to initialize or start");
1452	    }
1453	
1454	    // 启动历史数据持久化线程（非监控器，server.cpp 单独管理）
1455	    if (ctx.db_mgr && ctx.db_mgr->isOpen()) {
1456	        LOG_INFO(LogModule::SYSTEM, "starting history persistence thread (interval=5s)");
1457	        start_history_persistence_thread(&ctx);
1458	    }
1459	
1460	    // 启动边缘遥测上报（可选，W-edge）。
1461	    // 配置不完整/能力缺失时 start() 返回 false 并保持关闭，绝不半启用。
1462	    //
1463	    // 先构造配置事务（STABLE/TRIAL/ROLLBACK 状态机），再把它交给 exporter。
1464	    // state_path 落在与 history.db 同一目录，崩溃后可由 hasCrashRecoveryFile
1465	    // 检测到并触发 forceRollback。
1466	    const std::string txn_state_path =
1467	        resolveDatabasePath(ctx.cfg.data_dir.get())
1468	            .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
1469	                            std::string("history.db").size()) +
1470	        "config_txn_state";
1471	    ctx.config_txn = std::make_shared<weaknet_dbus::ConfigTransaction>(txn_state_path);
1472	
1473	    ctx.edge_exporter = std::make_unique<weaknet::EdgeTelemetryExporter>(
1474	        ctx.cfg, /*hostname=*/"edge-node", ctx.config_txn);
1475	
1476	    // 启动时若发现残留的 prior_values（上次 TRIAL 中崩溃），立即回滚还原。
1477	    if (ctx.config_txn->hasCrashRecoveryFile()) {
1478	        LOG_WARNING(LogModule::SYSTEM,
1479	                    "检测到上次 TRIAL 中的崩溃残留，立即执行回滚还原: " << txn_state_path);
1480	        ctx.config_txn->forceRollback(&ctx.cfg, "crash_recovery");
1481	    }
1482	
1483	    if (ctx.edge_exporter->start()) {
1484	        LOG_INFO(LogModule::SYSTEM, "edge telemetry exporter started");
1485	
1486	        // T3: 启动端侧 AI 异步初筛调度器（容量=1，并发=1，300s 冷却，15s SIGKILL 硬超时）
1487	        ctx.edge_ai_scheduler = std::make_unique<weaknet::EdgeAiScheduler>(
1488	            ctx.cfg.edge.device_id.get(),
1489	            [&ctx](weaknet::EdgeAiHypothesisRecord hyp) {
1490	                if (ctx.edge_exporter) {
1491	                    ctx.edge_exporter->enqueueHypothesis(std::move(hyp));
1492	                }
1493	            });
1494	        ctx.edge_ai_scheduler->start();
1495	        LOG_INFO(LogModule::SYSTEM, "edge AI scheduler started (cooldown=300s, hard_timeout=15s)");
1496	    }
1497	
1498	    // 启动无线事实上行（Phase 4a，可选）。
1499	    //
1500	    // 与遥测上报**并列独立**：幂等域不同（event_id/incident_id vs
1501	    // network_epoch+sequence_id），失败重发语义也不同，故各自线程与游标。
1502	    // 数据源是 SQLite（跨重启延续的事实），因此必须等 db_mgr 已就绪。
1503	    {
1504	        const std::string uplink_state_path =
1505	            resolveDatabasePath(ctx.cfg.data_dir.get())
1506	                .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
1507	                                std::string("history.db").size()) +
1508	            "wireless-uplink-state";
1509	        if (ctx.db_mgr) {
1510	            // 传 sampler 并在读侧持有共享锁：插件可被运行期 disable/restart，
1511	            // 必须在读锁保护下安全采样，避免访问正被析构的监控器。
1512	            ctx.wireless_uplink = std::make_unique<weaknet::EdgeWirelessUplinkExporter>(
1513	                ctx.cfg, *ctx.db_mgr, uplink_state_path,
1514	                [&ctx](std::vector<weaknet_dbus::ProcessNetInfo>* out) {
1515	                    if (!out) return;
1516	                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
1517	                    if (ctx.process_net_profiler && ctx.process_net_profiler->isAvailable()) {
1518	                        *out = ctx.process_net_profiler->getTopBandwidth(5);
1519	                    }
1520	                },
1521	                [&ctx](weaknet_dbus::DropStatsSummary* out) {
1522	                    if (!out) return;
1523	                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
1524	                    if (ctx.skb_drop_monitor && ctx.skb_drop_monitor->isAvailable()) {
1525	                        *out = ctx.skb_drop_monitor->getDropStats();
1526	                    }
1527	                },
1528	                [&ctx](weaknet_dbus::TcpRttSummary* out) {
1529	                    if (!out) return;
1530	                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
1531	                    if (ctx.tcp_rtt_monitor && ctx.tcp_rtt_monitor->isAvailable()) {
1532	                        *out = ctx.tcp_rtt_monitor->getStats();
1533	                    }
1534	                });
1535	            if (ctx.wireless_uplink->start()) {
1536	                LOG_INFO(LogModule::SYSTEM, "edge wireless uplink started");
1537	            }
1538	        } else {
1539	            LOG_WARNING(LogModule::SYSTEM,
1540	                        "无线事实上行未启动：数据库不可用（无持久化事实可上行）");
1541	        }
1542	    }
1543	
1544	    // 主线程进入阻塞式 looper
1545	    auto* lp = Looper::current();
1546	    lp->attach(ctx.connection);
1547	    lp->run(&ctx);
1548	    // Looper::run() 退出后，按顺序收尾：
1549	    // 1) 先置 running=false 让所有监控线程退出循环
1550	    // 2) MonitorManager 逐插件请求停止并 join worker，确保不再访问 ctx
1551	    // 3) 之后仅 join 服务级历史持久化线程，再释放共享资源
1552	    LOG_INFO(LogModule::NETWORK, "server shutting down, stopping monitor threads...");
1553	    ctx.running = false;
1554	
1555	    // 先由每个插件请求停止并 join 自己的 worker；MonitorManager 是唯一插件停止入口。
1556	    // stop() 内部设置 per-monitor flag，避免全局 running=false 影响其他插件。
1557	    if (ctx.monitor_manager) {
1558	        ctx.monitor_manager->stopAll();
1559	    }
1560	
1561	    // 服务级历史线程与受控主动探测线程由 ServerContext 统一 join；插件线程已由各自 stop() 完成。
1562	    if (ctx.active_probe_thread.joinable())             ctx.active_probe_thread.join();
1563	
1564	    // 历史持久化线程：只读 weak_mgr 快照 + 写 DB，不依赖其他线程资源，最后 join 最安全。
1565	    // 此前缺失该 join，导致 ~ServerContext 析构时该线程可能仍持 ctx* 访问 → 悬垂/terminate。
1566	    if (ctx.history_thread.joinable())                  ctx.history_thread.join();
1567	
1568	    // 停止端侧 AI 调度器：先于 edge_exporter 停止，避免回调访问已析构的 exporter
1569	    if (ctx.edge_ai_scheduler) {
1570	        ctx.edge_ai_scheduler->stop();
1571	        ctx.edge_ai_scheduler.reset();
1572	    }
1573	
1574	    // 停止边缘遥测上报：先于 ~ServerContext，保证不再访问 ctx.cfg。
1575	    if (ctx.edge_exporter) {
1576	        ctx.edge_exporter->stop();
1577	        ctx.edge_exporter.reset();
1578	    }
1579	
1580	    // 停止无线事实上行：同样必须早于 ~ServerContext 释放 db_mgr，
1581	    // 否则工作线程可能在数据库析构后读取事实。
1582	    if (ctx.wireless_uplink) {
1583	        ctx.wireless_uplink->stop();
1584	        ctx.wireless_uplink.reset();
1585	    }
1586	
1587	    // 停止文件日志（在 glog 关闭之前）
1588	    Logger::stopFileLog();
1589	
1590	    // 清理glog。资源（DBus 连接 / service / weak_mgr）由 ~ServerContext 统一释放。
1591	    google::ShutdownGoogleLogging();
1592	
1593	    // 清理全局网络通信库（libcurl 全局资源释放）
1594	    weaknet::EdgeTelemetryExporter::cleanupGlobal();
1595	
1596	    return 0;
1597	}
1598	
1599	}  // namespace weaknet_dbus
