                std::this_thread::sleep_for(100ms);
        }
        monitor->stop();
        LOG_INFO(LogModule::TCP_LOSS, "TCP conn monitor thread stopped");
    });
}

// 启动历史数据持久化线程
void start_tcp_connect_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnectMonitor* monitor) {
    *worker = std::thread([ctx, monitor]() {
        if (!monitor) return;
        LOG_INFO(LogModule::NETWORK, "TCP connect monitor thread started");
        // 与 DNS 捕获同构：高频排空 perf buffer，避免突发建连丢事件
        while ((ctx->running.load() && !ctx->tcp_connect_stop.load())) {
            monitor->drain();
            std::this_thread::sleep_for(200ms);
        }
        monitor->stop();
        LOG_INFO(LogModule::NETWORK, "TCP connect monitor thread stopped");
    });
}

void start_tcp_rtt_monitor_thread(ServerContext* ctx, std::thread* worker, TcpRttMonitor* monitor) {
    *worker = std::thread([ctx, monitor]() {
        if (!monitor) return;
        LOG_INFO(LogModule::TCP_LOSS, "TCP passive RTT monitor thread started");
        while (ctx->running.load() && !ctx->tcp_rtt_stop.load()) {
            const auto stats = monitor->getStats();
            if (stats.activeConns > 0) {
                LOG_INFO(LogModule::TCP_LOSS, "TCP passive RTT tick: active_conns=" << stats.activeConns
                    << " avg_rtt=" << stats.avgRttUs << "us"
                    << " p50=" << stats.p50RttUs << "us"
                    << " p90=" << stats.p90RttUs << "us"
                    << " p99=" << stats.p99RttUs << "us"
                    << " total_samples=" << stats.totalSamples);
            }
            const uint32_t interval = ctx->cfg.tcp_rtt.interval_ms.load();
            for (int i = 0; i < static_cast<int>(interval / 100) && (ctx->running.load() && !ctx->tcp_rtt_stop.load()); ++i) {
                std::this_thread::sleep_for(100ms);
            }
        }
        monitor->stop();
        LOG_INFO(LogModule::TCP_LOSS, "TCP passive RTT monitor thread stopped");
    });
}

/**
 * @brief 受控主动连通性探测线程
 *
 * 只在 INTERNET_ACCESS Profile 且配置启用时运行。
 * 与被动观测不同：**不能因为最近被动流量充足就跳过**，否则
 * host-level capability 证据会消失。
 */
void start_active_probe_thread(ServerContext* ctx, std::thread* worker) {
    *worker = std::thread([ctx]() {
        LOG_INFO(LogModule::NETWORK, "Active connectivity probe thread started");
        while (ctx->running.load() && !ctx->active_probe_stop.load()) {
            if (ctx->active_probe && ctx->active_probe->isUsable()) {
                ctx->active_probe->runProbeRound();
            }
            // 直接按毫秒计算。此前误把毫秒值当作秒（interval * 10 次 100ms），
            // 导致探测实际约 2.8 小时才跑一轮，结论长期停留在首轮快照。
            const uint32_t interval_ms = std::max(5000u, ctx->cfg.active_probe.interval_ms.load());
            const int ticks = static_cast<int>(interval_ms / 100);
            for (int i = 0; i < ticks &&
                            ctx->running.load() && !ctx->active_probe_stop.load(); ++i) {
                std::this_thread::sleep_for(100ms);
            }
        }
        LOG_INFO(LogModule::NETWORK, "Active connectivity probe thread stopped");
    });
}

void start_history_persistence_thread(ServerContext* ctx) {
    ctx->history_thread = std::thread([ctx](){
        LOG_INFO(LogModule::SYSTEM, "History persistence thread started");

        while (ctx->running.load()) {
            // 每 5 秒持久化一轮（每秒检查 running 标志以便快速退出）
            for (int i = 0; i < 5 && ctx->running.load(); ++i) {
                std::this_thread::sleep_for(1s);
            }
            if (!ctx->running.load()) break;

            if (!ctx->db_mgr || !ctx->db_mgr->isOpen()) continue;

            // 获取当前接口快照并计算质量评分 (CR-3, HR-9)
            auto snapshot = ctx->weak_mgr->getCurrentInterfaces();
            // 无上行时不编造网卡名：写进行里的 iface 必须是真的在用的那张。
            // 真正决定写入哪一行的是下面 isCurrent() + usingNow() 判定，
            // 这里的 active_iface 只服务于"无有效快照"时的占位说明。
            std::string active_iface;
            auto opt = ctx->weak_mgr->getCurrentUsingInterface();
            if (opt.has_value()) active_iface = opt.value();

            // W2 单一事实源：history persistence **只读权威快照**，绝不重新 evaluate。
            // 此前本线程现场只拉 5 个 Core SLE 调 OverallPolicy（无 DNS/TCP/HTTP/Active），
            // 与 quality 线程、HealthCheck 构成三条结论可能不一致的评估路径 ——
            // DB 中写入的是"只有 5 个 SLE 的旧结论"（既有 bug，本处修复）。
            // 原始 metrics 与 assessment **同代冻结**：同一 snapshot 的 experience
            // 提供结论，registry 的 latest 值仅作快照内的指标补充且由 snapshot 时刻界定。
            weaknet::NetworkExperience exp;
            auto snap = ctx->assessment_store.latest();
            const bool snap_valid = snap && weaknet::AssessmentSnapshotStore::isCurrent(*snap,
                    ctx->cfg.config_generation.load(),
                    ctx->dns_tracker ? ctx->dns_tracker->currentBindingEpoch()
                                     : ctx->dns_binding_epoch.load());
            if (snap_valid) {
                exp = snap->experience;
            } else {
                exp.iface = active_iface;
                exp.overall = weaknet::HealthState::UNKNOWN;
                exp.display_score = 50;
                exp.primary_issue = snap ? "stale_assessment" : "no_assessment_yet";
                // 无有效快照时 exp 是默认构造的，其 assessment_profile 会回落
                // 到结构体默认值 INTERNET_ACCESS —— 那是一个编造的 profile。
                // 审计元数据必须如实反映设备实际配置，故这里显式取权威值。
                exp.assessment_profile = currentAssessmentProfile(*ctx);
            }

            double cur_jitter = 0.0;
            if (ctx->metrics_registry) {
                auto j_s = ctx->metrics_registry->latest(active_iface, weaknet::MetricId::JITTER_MS);
                if (j_s.has_value() && j_s->state == weaknet::MetricState::VALID) cur_jitter = j_s->value;
            }

            NetworkQualityResult qualityResult = weaknet::LegacyAdapter::toQualityResult(exp, -1, 0.0, -1000, cur_jitter);

            int written = 0;
            for (const auto& iface : snapshot) {
                if (iface.usingNow()) {
                    if (ctx->db_mgr->insertSnapshot(iface.ifName(), iface, qualityResult,
                                                               iface.generation(), iface.lastUpdatedMs(),
                                                               iface.rttSampleTsMs(), iface.rssiSampleTsMs(),
                                                               iface.jitterSampleTsMs(), iface.tcpLossSampleTsMs(),
                                                               iface.trafficSampleTsMs(),
                                                               weaknet::assessmentProfileToString(
                                                                   exp.assessment_profile))) {
                        written++;
                    }
                }
            }
            if (written > 0) {
                LOG_INFO(LogModule::SYSTEM, "History persistence: wrote " << written << " records");
            }

            // 持久化蓝牙设备与音频质量快照
            {
                std::shared_lock<std::shared_mutex> bt_lock(ctx->monitor_pointers_mutex);
                if (ctx->bt_monitor && ctx->bt_monitor->isInitialized()) {
                    auto adapter = ctx->bt_monitor->getAdapterState();
                    auto devices = ctx->bt_monitor->getDevices();
                    int bt_written = 0;
                    for (const auto& dev : devices) {
                        // 仅记录已连接设备，或信号较强/活跃设备，避免周围瞬态广播垃圾数据占满 DB
                        if (dev.connected || dev.rssiDbm > -75) {
                            BtAudioFusionResult fusion;
                            bool hasAudio = ctx->bt_monitor->getAudioFusionResult(dev.macAddress, &fusion);
                            if (ctx->db_mgr->insertBtSnapshot(
                                    adapter.macAddress,
                                    dev.macAddress,
                                    dev.name.empty() ? dev.alias : dev.name,
                                    dev.connected,
                                    dev.rssiDbm,
                                    dev.estimatedDistance,
                                    hasAudio && fusion.isActive,
                                    hasAudio ? fusion.qualityScore : 0.0,
                                    hasAudio && fusion.suspectedStall,
                                    hasAudio ? fusion.bytesPerSec : 0,
                                    hasAudio ? fusion.maxGapMs : 0)) {
                                bt_written++;
                            }
                        }
                    }
                    if (bt_written > 0) {
                        LOG_INFO(LogModule::SYSTEM, "History persistence: wrote " << bt_written << " Bluetooth records");
                    }
                }
            }

            // 每天清理一次过期日志文件
            auto now = std::chrono::steady_clock::now();
            static auto last_log_cleanup = std::chrono::steady_clock::now();
            if (now - last_log_cleanup > std::chrono::hours(24)) {
                int log_deleted = Logger::cleanOldLogs("./logs/server", 7);
                last_log_cleanup = now;
                if (log_deleted > 0) {
                    LOG_INFO(LogModule::SYSTEM, "History persistence: cleaned " << log_deleted << " old log files");
                }
            }
        }

        LOG_INFO(LogModule::SYSTEM, "History persistence thread stopped");
    });
}

// 启动服务
int start_server(int argc, char** argv) {
    // 解析命令行参数：--config <path>（默认 /etc/weaknet/config.yaml）
    std::string config_path = "/etc/weaknet/config.yaml";
    for (int i = 1; i + 1 < argc; ++i) {
        if (std::string(argv[i]) == "--config") {
            config_path = argv[i + 1];
            ++i;
        }
    }
    // 配置失败 → 直接退出，不写日志（init 还没起）
    // 注意：此函数内已有 ctx 之前不能 LOG_*
    std::cerr << "Loading config from: " << config_path << std::endl;

    // 解析日志级别（用于 Logger::init）
    LogLevel log_level = LogLevel::INFO;
    if (!parseLogLevel("info", &log_level)) log_level = LogLevel::INFO;

    // 初始化日志系统
    if (!Logger::init("server", "./logs/server", log_level, true)) {
        std::cerr << "Failed to initialize logger" << std::endl;
        return 1;
    }

    // 启动带时间戳的文件日志
    Logger::startFileLog("./server/log");

    // 全局网络与通信库初始化（单线程早期调用）
    weaknet::EdgeTelemetryExporter::initGlobal();

    // 启动时清理 7 天前的日志文件
    int cleaned = Logger::cleanOldLogs("./logs/server", 7);
    if (cleaned > 0) {
        LOG_INFO(LogModule::SYSTEM, "Cleaned " << cleaned << " old log files on startup");
    }

    // 注册信号处理函数（SIGINT/SIGTERM）
    std::signal(SIGINT, Logger::signalHandler);
    std::signal(SIGTERM, Logger::signalHandler);

    ServerContext ctx;

    // 加载配置文件（文件不存在 → 默认值；存在但语法错 → exit 1）
    {
        std::string cfg_err;
        if (!loadWeakNetConfig(config_path, &ctx.cfg, &cfg_err)) {
            std::cerr << "Configuration error in " << config_path << ": " << cfg_err << std::endl;
            LOG_ERROR(LogModule::SYSTEM, "Configuration error in " << config_path << ": " << cfg_err);
            return 2;
        }
        LOG_INFO(LogModule::SYSTEM, "Config loaded from: " << config_path
            << " (dbus name: " << kBusName << ")");

        // 应用日志级别（配置文件覆盖默认）
        LogLevel new_level;
        if (parseLogLevel(ctx.cfg.log_level.get(), &new_level)) {
            Logger::setLogLevel(new_level);
            LOG_INFO(LogModule::SYSTEM, "Log level from config: " << ctx.cfg.log_level.get());
        } else if (!ctx.cfg.log_level.get().empty()) {
            LOG_WARNING(LogModule::SYSTEM,
                "Unknown log_level '" << ctx.cfg.log_level.get() << "', keeping default INFO");
        }

        // IR-3: assessment profile 合法性校验（权威值始终是 cfg.dns.assessment_profile，
        // 不再拷贝到独立成员——拷贝会让运行时 SetMonitorParam 静默失效）。
        // 非法值仅告警并按 INTERNET_ACCESS 回落，由 parseAssessmentProfile 统一实现。
        {
            const std::string p = ctx.cfg.dns.assessment_profile.get();
            if (p == "NETWORK_ONLY" || p == "INTERNET_ACCESS") {
                LOG_INFO(LogModule::SYSTEM, "Assessment profile from config: " << p);
            } else {
                LOG_WARNING(LogModule::SYSTEM, "Unknown assessment_profile '" << p
                            << "', falling back to INTERNET_ACCESS");
            }
        }
    }

    if (!init_dbus(&ctx)) return 1;

    // 启动事件监控
    getEventManager().startEventMonitoring(&ctx);

    // 初始化 MetricsRegistry 与 WeakNetMgr (MR-1, MR-2, HR-4)
    ctx.metrics_registry = std::make_unique<weaknet::MetricsRegistry>();
    ctx.dns_tracker = std::make_unique<weaknet::DnsTransactionTracker>();
    ctx.weak_mgr = std::make_unique<WeakNetMgr>(ctx.metrics_registry.get());

    // 网络代次跨重启推进（W-edge 上行去重的正确性前提）。
    uint64_t persistent_epoch = 1;
    {
        weaknet::NetworkEpochStore epoch_store(resolveNetworkEpochPath(ctx.cfg.data_dir.get()));
        persistent_epoch = epoch_store.open();
        ctx.dns_binding_epoch.store(persistent_epoch);
        // dns_tracker 的 binding epoch 初值为 1，运行中由路由/解析器变化推进。
        // 持久化值只在更大时才生效（advanceBindingEpoch 内部拒绝回退），
        // 因此这里把两者对齐到同一个下界。
        ctx.dns_tracker->advanceBindingEpoch(persistent_epoch);
    }

    // 初始化端侧确定性诊断引擎与证据生成服务
    {
        std::string dev_id = ctx.cfg.edge.device_id.get();
        if (dev_id.empty()) {
            dev_id = "radxa-cubie-a7a";
        }
        ctx.action_registry = std::make_shared<weaknet::ActionRegistry>();
        ctx.diagnosis_engine = std::make_unique<weaknet::DiagnosisEngine>(
            weaknet::RuleLoader::loadDefaultRules(), ctx.action_registry);
        ctx.evidence_id_generator = std::make_unique<weaknet::EvidenceIdGenerator>(
            dev_id, persistent_epoch, true);
        LOG_INFO(LogModule::SYSTEM, "DiagnosisEngine & ActionRegistry initialized for device: " << dev_id);
    }

    // 启动 UsingInterfaceManager（一次性启动，不重复调用 start()）
    UsingInterfaceManager::getInstance()->start();

    // 初始化历史数据持久化管理器（智能指针）
    const std::string db_path = resolveDatabasePath(ctx.cfg.data_dir.get());
    LOG_INFO(LogModule::SYSTEM, "initializing database manager (path=" << db_path << ")");
    ctx.db_mgr = std::make_unique<DatabaseManager>(db_path);
    if (ctx.db_mgr->isOpen()) {
        LOG_INFO(LogModule::SYSTEM, "database manager opened, records=" << ctx.db_mgr->getRecordCount());
    } else {
        LOG_WARNING(LogModule::SYSTEM, "database manager failed to open, history persistence disabled");
    }

    // ================================================================
    // 受控主动连通性探测：宿主 Internet 能力证据的唯一来源
    // 默认关闭；targets 为空时不启用（不内置任何第三方默认目标，
    // 避免第三方服务异常被误读为 Internet 故障）。
    // ================================================================
    {
        ctx.active_probe = std::make_unique<ActiveConnectivityMonitor>();
        applyActiveProbeConfig(&ctx);
        start_active_probe_thread(&ctx, &ctx.active_probe_thread);
    }

    // 初始化接口列表到WeakNetMgr中
    LOG_INFO(LogModule::WEAK_MGR, "initializing interface list...");
    auto initial_interfaces = ctx.weak_mgr->collectCurrentInterfaces();
    ctx.weak_mgr->updateInterfaces(initial_interfaces);
    LOG_INFO(LogModule::WEAK_MGR, "interface list initialized with " << initial_interfaces.size() << " interfaces");

    // ================================================================
    // 监控器插件化启动：注册内置插件 → 实例化（按 order 排序）→ init → start
    // ================================================================
    registerBuiltinPlugins();
    registerEbpfPlugins();
    ctx.monitor_manager = std::make_unique<MonitorManager>(
        &ctx, instantiateAllPlugins());
    const std::string db_path_for_overrides = resolveDatabasePath(ctx.cfg.data_dir.get());
    const std::string base_dir_for_overrides =
        db_path_for_overrides.substr(0, db_path_for_overrides.size() - std::string("history.db").size());
    ctx.monitor_manager->setOverridePath(base_dir_for_overrides + "runtime-overrides.bin");
    // 生命周期状态变化 → D-Bus MonitorStateChanged 信号（携带 "name:state"）。
    ctx.monitor_manager->setStateChangeCallback(
        [&ctx](const std::string& name, const std::string& state) {
            if (ctx.service) {
                ctx.service->emitSpecificSignal(kSignalMonitorStateChanged, name + ":" + state, 0);
            }
        });
    if (!ctx.monitor_manager->loadOverrides(nullptr)) {
        LOG_WARNING(LogModule::SYSTEM, "runtime monitor overrides could not be loaded");
    }
    if (!ctx.monitor_manager->startConfigured()) {
        LOG_WARNING(LogModule::NETWORK,
                    "one or more monitor plugins failed to initialize or start");
    }

    // 启动历史数据持久化线程（非监控器，server.cpp 单独管理）
    if (ctx.db_mgr && ctx.db_mgr->isOpen()) {
        LOG_INFO(LogModule::SYSTEM, "starting history persistence thread (interval=5s)");
        start_history_persistence_thread(&ctx);
    }

    // 启动边缘遥测上报（可选，W-edge）。
    // 配置不完整/能力缺失时 start() 返回 false 并保持关闭，绝不半启用。
    //
    // 先构造配置事务（STABLE/TRIAL/ROLLBACK 状态机），再把它交给 exporter。
    // state_path 落在与 history.db 同一目录，崩溃后可由 hasCrashRecoveryFile
    // 检测到并触发 forceRollback。
    const std::string txn_state_path =
        resolveDatabasePath(ctx.cfg.data_dir.get())
            .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
                            std::string("history.db").size()) +
        "config_txn_state";
    ctx.config_txn = std::make_shared<weaknet_dbus::ConfigTransaction>(txn_state_path);

    ctx.edge_exporter = std::make_unique<weaknet::EdgeTelemetryExporter>(
        ctx.cfg, /*hostname=*/"edge-node", ctx.config_txn);

    // 启动时若发现残留的 prior_values（上次 TRIAL 中崩溃），立即回滚还原。
    if (ctx.config_txn->hasCrashRecoveryFile()) {
        LOG_WARNING(LogModule::SYSTEM,
                    "检测到上次 TRIAL 中的崩溃残留，立即执行回滚还原: " << txn_state_path);
        ctx.config_txn->forceRollback(&ctx.cfg, "crash_recovery");
    }

    if (ctx.edge_exporter->start()) {
        LOG_INFO(LogModule::SYSTEM, "edge telemetry exporter started");

        // T3: 启动端侧 AI 异步初筛调度器（容量=1，并发=1，300s 冷却，15s SIGKILL 硬超时）
        ctx.edge_ai_scheduler = std::make_unique<weaknet::EdgeAiScheduler>(
            ctx.cfg.edge.device_id.get(),
            [&ctx](weaknet::EdgeAiHypothesisRecord hyp) {
                if (ctx.edge_exporter) {
                    ctx.edge_exporter->enqueueHypothesis(std::move(hyp));
                }
            });
        ctx.edge_ai_scheduler->start();
        LOG_INFO(LogModule::SYSTEM, "edge AI scheduler started (cooldown=300s, hard_timeout=15s)");
    }

    // 启动无线事实上行（Phase 4a，可选）。
    //
    // 与遥测上报**并列独立**：幂等域不同（event_id/incident_id vs
    // network_epoch+sequence_id），失败重发语义也不同，故各自线程与游标。
    // 数据源是 SQLite（跨重启延续的事实），因此必须等 db_mgr 已就绪。
    {
        const std::string uplink_state_path =
            resolveDatabasePath(ctx.cfg.data_dir.get())
                .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
                                std::string("history.db").size()) +
            "wireless-uplink-state";
        if (ctx.db_mgr) {
            // 传 sampler 并在读侧持有共享锁：插件可被运行期 disable/restart，
            // 必须在读锁保护下安全采样，避免访问正被析构的监控器。
            ctx.wireless_uplink = std::make_unique<weaknet::EdgeWirelessUplinkExporter>(
                ctx.cfg, *ctx.db_mgr, uplink_state_path,
                [&ctx](std::vector<weaknet_dbus::ProcessNetInfo>* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.process_net_profiler && ctx.process_net_profiler->isAvailable()) {
                        *out = ctx.process_net_profiler->getTopBandwidth(5);
                    }
                },
                [&ctx](weaknet_dbus::DropStatsSummary* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.skb_drop_monitor && ctx.skb_drop_monitor->isAvailable()) {
                        *out = ctx.skb_drop_monitor->getDropStats();
                    }
                },
                [&ctx](weaknet_dbus::TcpRttSummary* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.tcp_rtt_monitor && ctx.tcp_rtt_monitor->isAvailable()) {
                        *out = ctx.tcp_rtt_monitor->getStats();
                    }
                });
            if (ctx.wireless_uplink->start()) {
                LOG_INFO(LogModule::SYSTEM, "edge wireless uplink started");
            }
        } else {
            LOG_WARNING(LogModule::SYSTEM,
                        "无线事实上行未启动：数据库不可用（无持久化事实可上行）");
        }
    }

    // 主线程进入阻塞式 looper
    auto* lp = Looper::current();
    lp->attach(ctx.connection);
    lp->run(&ctx);
    // Looper::run() 退出后，按顺序收尾：
    // 1) 先置 running=false 让所有监控线程退出循环
    // 2) MonitorManager 逐插件请求停止并 join worker，确保不再访问 ctx
    // 3) 之后仅 join 服务级历史持久化线程，再释放共享资源
    LOG_INFO(LogModule::NETWORK, "server shutting down, stopping monitor threads...");
    ctx.running = false;

    // 先由每个插件请求停止并 join 自己的 worker；MonitorManager 是唯一插件停止入口。
    // stop() 内部设置 per-monitor flag，避免全局 running=false 影响其他插件。
    if (ctx.monitor_manager) {
        ctx.monitor_manager->stopAll();
    }

    // 服务级历史线程与受控主动探测线程由 ServerContext 统一 join；插件线程已由各自 stop() 完成。
    if (ctx.active_probe_thread.joinable())             ctx.active_probe_thread.join();

    // 历史持久化线程：只读 weak_mgr 快照 + 写 DB，不依赖其他线程资源，最后 join 最安全。
    // 此前缺失该 join，导致 ~ServerContext 析构时该线程可能仍持 ctx* 访问 → 悬垂/terminate。
    if (ctx.history_thread.joinable())                  ctx.history_thread.join();

    // 停止端侧 AI 调度器：先于 edge_exporter 停止，避免回调访问已析构的 exporter
    if (ctx.edge_ai_scheduler) {
        ctx.edge_ai_scheduler->stop();
        ctx.edge_ai_scheduler.reset();
    }

    // 停止边缘遥测上报：先于 ~ServerContext，保证不再访问 ctx.cfg。
    if (ctx.edge_exporter) {
        ctx.edge_exporter->stop();
        ctx.edge_exporter.reset();
    }

    // 停止无线事实上行：同样必须早于 ~ServerContext 释放 db_mgr，
    // 否则工作线程可能在数据库析构后读取事实。
    if (ctx.wireless_uplink) {
        ctx.wireless_uplink->stop();
        ctx.wireless_uplink.reset();
    }

    // 停止文件日志（在 glog 关闭之前）
    Logger::stopFileLog();

    // 清理glog。资源（DBus 连接 / service / weak_mgr）由 ~ServerContext 统一释放。
    google::ShutdownGoogleLogging();

    // 清理全局网络通信库（libcurl 全局资源释放）
    weaknet::EdgeTelemetryExporter::cleanupGlobal();

    return 0;
}

}  // namespace weaknet_dbus

/**
 * @file server.hpp
 * @brief WeakNet 服务端生命周期中枢与启动入口
 *
 * 本文件定义 ServerContext（全局生命周期结构体）以及服务启动相关的自由函数。
 * ServerContext 聚合了 D-Bus 连接、所有监控线程、eBPF 监控器实例和共享数据，
 * 确保所有资源在同一对象内集中管理，退出时按依赖逆序释放。
 *
 * 设计约束：
 *   - 所有捕获 ServerContext 的线程必须可 join（禁止 std::thread::detach）
 *   - eBPF 监控器由 unique_ptr 持有 ownership，线程仅通过裸指针访问
 */

#pragma once

#include <vector>
#include <string>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <atomic>
#include <memory>

#include "weaknet_config.hpp"
#include "monitor_manager.hpp"
#include "metrics/metrics_registry.hpp"
#include "assurance/dns_transaction_tracker.hpp"
#include "assessment_snapshot.hpp"
#include "assurance/dns_service_evaluator.hpp"
#include "assurance/diagnosis_engine.hpp"
#include "assurance/evidence_id_generator.hpp"
#include "assurance/action_registry.hpp"
#include "edge_telemetry_exporter.hpp"
#include "edge_wireless_uplink_exporter.hpp"
#include "assurance/edge_ai_scheduler.hpp"

// 前置声明，避免强依赖 dbus 头
struct DBusConnection;

namespace weaknet_dbus {

class DbusService;          // 前置声明：D-Bus 方法处理与信号发送
class WeakNetMgr;           // 前置声明：弱网管理器（接口列表 + 质量指标聚合）
class NetInfo;              // 前置声明：单个网卡的状态与指标模型
class BtMonitor;            // 前置声明：蓝牙监测器
class DnsMonitor;           // 前置声明：DNS 监控（eBPF）
class WifiPacketLossMonitor;// 前置声明：Wi-Fi 丢包归因（eBPF）
class HttpLatencyMonitor;   // 前置声明：HTTP 请求延迟（eBPF）
class ProcessNetProfiler;   // 前置声明：进程网络画像（eBPF）
class TcpRetransMonitor;    // 前置声明：TCP 重传监控（eBPF）
class TcpConnMonitor;       // 前置声明：TCP 连接生命周期监控（eBPF）
class TcpConnectMonitor;    // 前置声明：TCP 建连可观测性（eBPF）
class ActiveConnectivityMonitor; // 前置声明：受控主动连通性探测
class SkbDropMonitor;       // 前置声明：Socket 丢包归因监控（eBPF）
class TcpRttMonitor;        // 前置声明：被动 TCP RTT 监控（eBPF）
class BtDataPathAnalyzer;   // 前置声明：蓝牙 HCI ACL 数据通道分析器（eBPF）
class DatabaseManager;      // 前置声明：SQLite 历史数据持久化
class WirelessEventStore;   // 前置声明：规范化无线设备事件存储（Phase 1）
class BtLinkQualityTracker; // 前置声明：蓝牙链路质量跟踪器（Phase 2）
class SiteIncidentCorrelator; // 前置声明：区域级异常关联器（Phase 3a）
class ConfigTransaction;    // 前置声明：配置事务状态机（weaknet_config.hpp 中定义）

/**
 * @brief 服务端全局生命周期中枢
 *
 * 持有所有监控线程、eBPF 监控器、D-Bus 服务对象和共享数据。
 * 析构函数中按依赖逆序释放资源：先停止线程（join），再释放 eBPF 监控器和 DBusService。
 *
 * 线程安全约束：
 *   - running_: 原子变量，所有线程轮询检查退出信号
 *   - service/weak_mgr/bt_monitor/dns_monitor 等 unique_ptr: 启动后只读访问，无需额外锁
 */
struct ServerContext {
    ::DBusConnection* connection = nullptr;   ///< D-Bus 会话总线连接（由 DBus 库管理生命周期，析构时需显式 disconnection）

    std::atomic<bool> running{true};          ///< 全局运行标志。设为 false 后所有监控线程在下一个周期退出

    // ---------- 服务级线程 ----------
    // MonitorManager/各插件分别持有监控 worker；这里只保留历史持久化线程。
    std::thread history_thread;                 ///< 每 5 秒将 iface_list 快照写入 DB
    std::thread active_probe_thread;            ///< 受控主动连通性探测

    // ---------- 监控器插件生命周期 ----------
    std::unique_ptr<MonitorManager> monitor_manager; ///< 静态插件实例与生命周期协调器

    // ---------- 服务对象（unique_ptr 管理生命周期）----------
    std::unique_ptr<DbusService> service;                ///< D-Bus 服务：导出方法 + 发射信号
    std::unique_ptr<WeakNetMgr> weak_mgr;                ///< 弱网管理器：聚合所有监控器的数据更新
    std::unique_ptr<weaknet::MetricsRegistry> metrics_registry; ///< 权威度量注册表 (HR-4)
    std::unique_ptr<weaknet::DnsTransactionTracker> dns_tracker; ///< DNS userspace lifecycle authority (SR-11)
    std::atomic<uint64_t> dns_binding_epoch{1};
    // 评估 Profile **不在此处缓存副本**：权威值始终是 cfg.dns.assessment_profile。
    // 曾经这里存一份启动时拷贝，导致运行时 SetMonitorParam("dns.assessment_profile")
    // 写进 cfg 却永远不生效（D-Bus 回 ok、GetMonitorParam 显示新值，OverallPolicy
    // 仍用旧值）。ConfigString 由 mutex 保护，评估线程每轮直读即可，无需副本。
    // 读取统一走 currentAssessmentProfile()。

    // 监控器对象由对应插件拥有；这些裸指针仅为现有查询/聚合调用提供
    // non-owning 兼容视图。
    //
    // 线程安全约束（UAF 防护）：
    //   插件生命周期（start/stop/restart）对这些指针与底层 unique_ptr 进行
    //   写操作时持有独占写锁（std::unique_lock<std::shared_mutex>）；
    //   历史持久化、网络评估、边缘上行和 D-Bus 派发线程在解引用这些指针时
    //   持有共享读锁（std::shared_lock<std::shared_mutex>），杜绝插件销毁时的
    //   use-after-free 竞态窗口。
    mutable std::shared_mutex monitor_pointers_mutex;
    BtMonitor* bt_monitor = nullptr;
    DnsMonitor* dns_monitor = nullptr;
    WifiPacketLossMonitor* wifi_loss_monitor = nullptr;
    HttpLatencyMonitor* http_latency_monitor = nullptr;
    ProcessNetProfiler* process_net_profiler = nullptr;
    TcpRetransMonitor* tcp_retrans_monitor = nullptr;
    TcpConnMonitor* tcp_conn_monitor = nullptr;
    SkbDropMonitor* skb_drop_monitor = nullptr;
    TcpConnectMonitor* tcp_connect_monitor = nullptr;
    TcpRttMonitor* tcp_rtt_monitor = nullptr;
    BtDataPathAnalyzer* bt_hci_analyzer = nullptr;
    class BtDataPathAnomalyDetector* bt_anomaly_detector = nullptr;

    /// 受控主动连通性探测（宿主能力证据的唯一来源）
    std::unique_ptr<ActiveConnectivityMonitor> active_probe;

    // ---------- 权威评估快照（W2 单一事实源）----------
    // quality 线程是唯一 evaluator 执行点；每轮评估后发布不可变快照。
    // HealthCheck / GetNetworkExperience / history persistence 全部只读，
    // 绝不重新拉 metrics、重新 evaluate、重新调 OverallPolicy。
    weaknet::AssessmentSnapshotStore assessment_store;
    // 配置代已移至 WeakNetConfig::config_generation（由 setMonitorParam 统一推进）。
    // ServerContext 不再持有副本——副本无人推进，会让"配置变更即失效"整条
    // 生命周期静默失效（旧快照永不判过期）。读取用 ctx.cfg.config_generation。
    std::atomic<uint64_t> assessment_sequence{0}; ///< 快照发布序号

    /// 云端下发配置的事务协调器（STABLE / TRIAL / ROLLBACK）。
    /// 必须在 EdgeTelemetryExporter 之前构造，因为 exporter 持有它的裸指针。
    std::shared_ptr<ConfigTransaction> config_txn;

    // ---------- 历史数据持久化 ----------
    std::unique_ptr<DatabaseManager> db_mgr;   ///< SQLite 管理器，持有数据库连接

    // ---------- 无线设备事件（Phase 1: Canonical Device Event）----------
    // 事件由 bt_events 插件的 eBPF ringbuf 采集，经 BtEventNormalizer 归一化后
    // 写入 WirelessEventStore。store 依赖 db_mgr，因此**必须在 db_mgr 之后构造**。
    // 裸指针供查询/其它消费者使用；store 由 key_bt_events 插件拥有。
    WirelessEventStore* wireless_event_store = nullptr;

    // ---------- 蓝牙链路质量跟踪器（Phase 2: 基线与劣化检测）----------
    // 由 bt_events 插件拥有，提供给 BtMonitor 喂入 fresh RSSI，
    // 以及供 BtEventMonitor 在 Normalizer 之后做因果断连 RSSI 回填。
    BtLinkQualityTracker* bt_link_quality_tracker = nullptr;

    // ---------- 区域级异常关联器（Phase 3a: SiteIncident）----------
    // 由 bt_events 插件拥有，是 D-Bus / CLI / 离线工具三条查询出口的取数点。
    // 它同时是 WirelessEventStore 的下游消费者（事件流由 store 转发），
    // 因此销毁顺序必须是 store 先解绑、关联器后析构。
    SiteIncidentCorrelator* site_incident_correlator = nullptr;

    // ---------- 边缘遥测上报 ----------
    std::unique_ptr<weaknet::EdgeTelemetryExporter> edge_exporter;
    /// Phase 4a：无线事实（事件/事故/基线）独立上行器。与遥测并列，
    /// 幂等域与失败重发语义不同，故不合并（见集成设计决策 D1）。
    std::unique_ptr<weaknet::EdgeWirelessUplinkExporter> wireless_uplink;
    /// T3：端侧 AI 异步初筛调度器（容量=1，并发=1，300s 冷却，15s SIGKILL 硬超时）
    std::unique_ptr<weaknet::EdgeAiScheduler> edge_ai_scheduler;

    // ---------- 端侧确定性诊断引擎与证据生成服务 ----------
    std::shared_ptr<weaknet::ActionRegistry> action_registry;
    std::unique_ptr<weaknet::DiagnosisEngine> diagnosis_engine;
    std::unique_ptr<weaknet::EvidenceIdGenerator> evidence_id_generator;

    // ---------- per-monitor stop requests (阶段二) ----------
    // These flags are separate from running: they stop one worker without
    // affecting the service or any other monitor.
    std::atomic<bool> iface_stop{false};
    std::atomic<bool> using_iface_stop{false};
    std::atomic<bool> rtt_stop{false};
    // jitter_stop 已废弃：jitter 作为 rtt 的衍生指标合并进 rtt_monitor
    std::atomic<bool> rssi_stop{false};
    std::atomic<bool> tcp_loss_stop{false};
    std::atomic<bool> traffic_stop{false};
    std::atomic<bool> quality_stop{false};
    std::atomic<bool> bluetooth_stop{false};
    std::atomic<bool> dns_stop{false};
    std::atomic<bool> wifi_loss_stop{false};
    std::atomic<bool> http_latency_stop{false};
    std::atomic<bool> process_profiler_stop{false};
    std::atomic<bool> tcp_retrans_stop{false};
    std::atomic<bool> tcp_conn_stop{false};
    std::atomic<bool> tcp_connect_stop{false};
    std::atomic<bool> tcp_rtt_stop{false};
    std::atomic<bool> bt_events_stop{false};
    std::atomic<bool> active_probe_stop{false};

    // ---------- 频段冲突检测快照 ----------
    std::mutex conflict_mutex;
    std::string latest_conflict_json = "{\"detected\":false,\"confidence\":0.0,\"reason\":\"No 2.4GHz coexistence conflict detected\"}";

    // ---------- 运行时配置 ----------
    WeakNetConfig cfg;                          ///< 线程安全配置（启动时构建一次，此后通过 D-Bus 运行时调参）

    /**
     * @brief 析构：释放所有资源
     *
     * 执行顺序：
     *   1. running_ = false（通知所有监控线程退出）
     *   2. join 所有监控线程
     *   3. unique_ptr 析构 DbusService → WeakNetMgr → eBPF 监控器（释放 BPF link 和 map）
     *   4. 关闭 DBus 连接
     *
     * 注意：析构时 running_ 必须已设为 false，否则监控线程可能访问已释放的指针。
     */
    ~ServerContext();
};

/**
 * @brief 读取当前评估 Profile（权威来源：cfg.dns.assessment_profile）。
 *
 * 每次调用都现读配置，因此运行时 SetMonitorParam("dns.assessment_profile")
 * 会立刻对下一轮评估生效。未知值回落 INTERNET_ACCESS（与 parseAssessmentProfile
 * 及启动期告警行为一致）。
 */
inline weaknet::AssessmentProfile currentAssessmentProfile(const ServerContext& ctx) {
    return weaknet::parseAssessmentProfile(ctx.cfg.dns.assessment_profile.get());
}

/**
 * @brief 初始化 D-Bus 会话总线连接
 *
 * 执行步骤：
 *   1. dbus_threads_init_default() 启用线程安全
 *   2. dbus_bus_get(DBUS_BUS_SYSTEM) 获取系统总线连接
 *   3. dbus_bus_request_name() 注册 com.example.WeakNet 服务名
 *   4. 将连接存入 ctx->connection
 *
 * @param ctx 全局上下文，初始化后 connection 字段会被填充
 * @return DBus 连接指针，失败时返回 nullptr
 */
::DBusConnection* init_dbus(ServerContext* ctx);

// ---- 传统监控线程启动函数（供插件 start() 调用；生命周期由插件管理）----

void start_iface_monitor_thread(ServerContext* ctx, std::thread* worker);       ///< 网卡列表监控（netlink 事件驱动）
void start_using_iface_thread(ServerContext* ctx, std::thread* worker);         ///< 当前上网网卡监控
void start_traffic_analysis_thread(ServerContext* ctx, std::thread* worker);    ///< 流量分析（flow_rate 持有者）
void start_network_quality_thread(ServerContext* ctx, std::thread* worker);     ///< 网络质量综合评估

// ---- eBPF 监控线程启动函数（供插件 start() 调用）----

void start_dns_monitor_thread(ServerContext* ctx, std::thread* worker, DnsMonitor* monitor);             ///< DNS 解析延迟/超时（dns_monitor.bpf.o）
void start_wifi_loss_monitor_thread(ServerContext* ctx, std::thread* worker, WifiPacketLossMonitor* monitor);       ///< Wi-Fi 收发丢包归因（wifi_packet_loss.bpf.o）
void start_http_latency_monitor_thread(ServerContext* ctx, std::thread* worker, HttpLatencyMonitor* monitor);    ///< HTTP TTFB 延迟（http_latency.bpf.o）
void start_process_net_profiler_thread(ServerContext* ctx, std::thread* worker, ProcessNetProfiler* monitor);    ///< 每进程带宽/重传（flow_rate.bpf.o 共享）
void start_tcp_retrans_monitor_thread(ServerContext* ctx, std::thread* worker, TcpRetransMonitor* monitor);     ///< TCP 连接级重传（tcp_retransmit.bpf.o）
void start_tcp_conn_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnMonitor* monitor);        ///< TCP 连接生命周期（tcp_conn_stats.bpf.o）
void start_tcp_connect_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnectMonitor* monitor);   ///< TCP 建连（tcp_connect.bpf.o）
void start_tcp_rtt_monitor_thread(ServerContext* ctx, std::thread* worker, TcpRttMonitor* monitor);           ///< 被动 TCP RTT（tcp_rtt.bpf.o）
void start_active_probe_thread(ServerContext* ctx, std::thread* worker);   ///< 受控主动连通性探测
void applyActiveProbeConfig(ServerContext* ctx);                           ///< 根据当前配置更新并下发主动探测参数

void start_history_persistence_thread(ServerContext* ctx);     ///< 历史数据持久化（非监控器，server.cpp 单独启动）

/**
 * @brief 启动 WeakNet D-Bus 服务端主入口
 *
 * 完整启动流程：
 *   1. 解析 --config <path> 命令行参数（默认 /etc/weaknet/config.yaml）
 *   2. 加载配置文件，回落 WeakNetConfig 默认值（行为零变化）
 *   3. 应用日志级别配置
 *   4. 初始化日志系统
 *   5. 解析数据库路径（优先级：cfg.data_dir > WEAKNET_DATA_DIR > 默认）
 *   6. 启动 D-Bus 连接、监控线程、eBPF 监控器、历史持久化线程
 *   7. 主线程进入 Looper::run() 阻塞
 *
 * 该函数会阻塞，直到进程被外部信号（SIGINT/SIGTERM）终止或 ServerContext::running_ 被置 false。
 *
 * @return 0 正常退出；非零为配置错误等可恢复错误
 */
int start_server(int argc, char** argv);

}  // namespace weaknet_dbus

