224	void NetworkEventManager::startEventMonitoring(struct ServerContext* ctx) {
225	    server_ctx_ = ctx;
226	
227	    LOG_INFO(LogModule::EVENT_MGR, "event monitoring started");
228	
229	    // 注册默认日志回调，保证事件至少被记录到日志，便于问题排查
230	    registerCallback(EventType::InterfaceChanged, [](const NetworkEvent& event) {
231	        LOG_INFO(LogModule::EVENT_MGR, "Interface change event: " << event.message);
232	    });
233	
234	    registerCallback(EventType::ConnectionModeChanged, [](const NetworkEvent& event) {
235	        LOG_INFO(LogModule::EVENT_MGR, "Connection mode change event: " << event.message);
236	    });
237	
238	    registerCallback(EventType::BluetoothDeviceChanged, [](const NetworkEvent& event) {
239	        LOG_INFO(LogModule::EVENT_MGR, "Bluetooth device event: " << event.message);
240	    });
