243	/**
244	 * @brief 内部方法：按事件类型分发回调
245	 * @param type  事件类型，决定遍历哪个回调 vector
246	 * @param event 传递给每个回调的事件对象
247	 * @note  先在 cb_mutex_ 保护下把该类型的回调**拷贝一份**，释放锁后再逐个调用。
248	 *       回调执行期间不持锁，因此回调内可以安全地 registerCallback /
249	 *       unregisterCallback，也可以嵌套触发新事件，不会重入死锁。
250	 *       （此前实现是持锁遍历调用，与头文件描述相反，回调内再注册即死锁。）
251	 */
252	void NetworkEventManager::invokeCallbacks(EventType type, const NetworkEvent& event) {
253	    std::vector<EventCallback> snapshot;
254	    {
255	        std::lock_guard<std::mutex> lock(cb_mutex_);
256	        const std::vector<EventCallback>* src = nullptr;
257	        switch (type) {
258	            case EventType::InterfaceChanged:        src = &interface_callbacks_; break;
259	            case EventType::ConnectionModeChanged:   src = &connection_mode_callbacks_; break;
260	            case EventType::NetworkQualityChanged:   src = &network_quality_callbacks_; break;
261	            case EventType::TcpLossRateChanged:      src = &tcp_loss_callbacks_; break;
262	            case EventType::RttChanged:              src = &rtt_callbacks_; break;
263	            case EventType::RssiChanged:             src = &rssi_callbacks_; break;
264	            case EventType::BluetoothDeviceChanged:  src = &bluetooth_callbacks_; break;
265	        }
266	        if (!src) return;
267	        snapshot = *src;
268	    }
269	
270	    // 锁外调用：拷贝保持了注册顺序，且本轮的增删不会影响已开始的这一轮分发。
271	    for (const auto& callback : snapshot) {
272	        if (callback) callback(event);
273	    }
274	}
