120	bool MonitorManager::loadOverrides(std::string* error) {
121	    std::lock_guard<std::mutex> lock(mutex_);
122	    if (override_path_.empty()) return true;
123	    std::ifstream in(override_path_, std::ios::binary);
124	    if (!in) return true;  // 文件不存在不是错误，回落既有配置
125	    std::vector<uint8_t> bytes((std::istreambuf_iterator<char>(in)),
126	                               std::istreambuf_iterator<char>());
127	    if (bytes.size() < 8 || bytes[0] != 'W' || bytes[1] != 'N' ||
128	        bytes[2] != 'R' || bytes[3] != 'O') {
129	        if (error) *error = "invalid runtime override header";
130	        return false;
131	    }
132	    size_t offset = 4;
133	    int32_t version = 0;
134	    if (!deserializeInt32(bytes, offset, version) || version != 1) {
135	        if (error) *error = "unsupported runtime override version";
136	        return false;
137	    }
138	    while (offset < bytes.size()) {
139	        std::string name;
140	        int32_t enabled = 0;
141	        if (!deserializeString(bytes, offset, name) ||
142	            !deserializeInt32(bytes, offset, enabled)) {
143	            if (error) *error = "truncated runtime override";
144	            return false;
145	        }
146	        if (!setMonitorEnabled(ctx_ ? &ctx_->cfg : nullptr, name, enabled != 0)) {
147	            // 记录失败原因后仍然保留 override 意图：下次启动会再次尝试应用，
148	            // 而不是把「读到的持久化意图」当作不存在而静默丢弃。
149	            LOG_WARNING(LogModule::SYSTEM,
150	                        "loadOverrides: 无法将持久化 override 应用到配置: " << name << "=" << enabled);
151	        }
152	        desired_overrides_[name] = enabled != 0;
153	    }
154	    return true;
155	}
