253	bool MonitorManager::stopAll() {
254	    std::lock_guard<std::mutex> lock(mutex_);
255	    if (stopped_) return true;
256	    for (auto it = entries_.rbegin(); it != entries_.rend(); ++it) {
257	        if (it->status.state == MonitorState::Running ||
258	            it->status.state == MonitorState::Starting ||
259	            it->status.state == MonitorState::Failed) {
260	            it->status.state = MonitorState::Stopping;
261	            it->plugin->stop();
262	            it->status.state = MonitorState::Stopped;
263	            it->status.changed_at = nowUtc();
264	        }
265	    }
266	    stopped_ = true;
267	    return true;
268	}
