43	// DNS 监控（order 10）
44	// ---------------------------------------------------------------------------
45	class DnsPlugin : public IMonitorPlugin {
46	    ServerContext* ctx_ = nullptr;
47	    std::thread worker_;
48	    std::unique_ptr<DnsMonitor> monitor_;
49	public:
50	    const char* name() const override { return "dns"; }
51	    int order() const override { return 10; }
52	    bool init(ServerContext* ctx) override { ctx_ = ctx; return true; }
53	    bool start(ServerContext* ctx) override {
54	        if (!ctx->cfg.dns.enabled.load()) {
55	            LOG_INFO(LogModule::NETWORK, "DNS monitor disabled by config");
56	            return true;
57	        }
58	        monitor_ = std::make_unique<DnsMonitor>();
59	        if (!monitor_->init(ctx->cfg.dns.bpf_obj.get().c_str(), ctx->cfg.dns.capture_pages.load(),
60	                             weaknet::resolveScopePlan(weaknet::MapSizingScope::Dns,
61	                                 {ctx->cfg.dns.map_sizing.mode.get(), ctx->cfg.dns.map_sizing.entries.load(),
62	                                  ctx->cfg.dns.map_sizing.ram_budget_bp.load()}, weaknet::totalPhysicalRamBytes()))) {
63	            monitor_.reset();
64	            return false;
65	        }
66	        {
67	            std::unique_lock<std::shared_mutex> lock(ctx->monitor_pointers_mutex);
68	            ctx->dns_monitor = monitor_.get();
69	        }
70	        ctx->dns_stop.store(false);
71	        start_dns_monitor_thread(ctx, &worker_, monitor_.get());
72	        return true;
73	    }
74	    void stop() override {
75	        if (!ctx_) return;
76	        ctx_->dns_stop.store(true);
77	        if (worker_.joinable()) worker_.join();
78	        {
79	            std::unique_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
80	            if (ctx_->dns_monitor == monitor_.get()) ctx_->dns_monitor = nullptr;
81	            monitor_.reset();
82	        }
83	    }
84	};
