372	        if (!ctx->cfg.tcp_connect.enabled.load()) {
373	            LOG_INFO(LogModule::NETWORK, "TCP connect monitor disabled by config");
374	            return true;
375	        }
376	        monitor_ = std::make_unique<TcpConnectMonitor>();
377	        if (!monitor_->init(ctx->cfg.tcp_connect.bpf_obj.get().c_str(),
378	                            ctx->cfg.tcp_connect.capture_pages.load())) {
379	            LOG_WARNING(LogModule::NETWORK, "TcpConnectPlugin: init failed for "
380	                        << ctx->cfg.tcp_connect.bpf_obj.get());
381	            monitor_.reset();
382	            return false;
383	        }
384	        {
385	            std::unique_lock<std::shared_mutex> lock(ctx->monitor_pointers_mutex);
386	            ctx->tcp_connect_monitor = monitor_.get();
387	        }
388	        ctx->tcp_connect_stop.store(false);
389	        start_tcp_connect_monitor_thread(ctx, &worker_, monitor_.get());
390	        return true;
391	    }
392	    void stop() override {
393	        if (!ctx_) return;
394	        ctx_->tcp_connect_stop.store(true);
395	        if (worker_.joinable()) worker_.join();
396	        {
397	            std::unique_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
398	            if (ctx_->tcp_connect_monitor == monitor_.get()) ctx_->tcp_connect_monitor = nullptr;
399	            monitor_.reset();
400	        }
401	    }
402	};
