/**
 * @file server.hpp
 * @brief WeakNet 服务端生命周期中枢与启动入口
 *
 * 本文件定义 ServerContext（全局生命周期结构体）以及服务启动相关的自由函数。
 * ServerContext 聚合了 D-Bus 连接、所有监控线程、eBPF 监控器实例和共享数据，
 * 确保所有资源在同一对象内集中管理，退出时按依赖逆序释放。
 *
 * 设计约束：
 *   - 所有捕获 ServerContext 的线程必须可 join（禁止 std::thread::detach）
 *   - eBPF 监控器由 unique_ptr 持有 ownership，线程仅通过裸指针访问
 */

#pragma once

#include <vector>
#include <string>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <atomic>
#include <memory>

#include "weaknet_config.hpp"
#include "monitor_manager.hpp"
#include "metrics/metrics_registry.hpp"
#include "assurance/dns_transaction_tracker.hpp"
#include "assessment_snapshot.hpp"
#include "assurance/dns_service_evaluator.hpp"
#include "assurance/diagnosis_engine.hpp"
#include "assurance/evidence_id_generator.hpp"
#include "assurance/action_registry.hpp"
#include "edge_telemetry_exporter.hpp"
#include "edge_wireless_uplink_exporter.hpp"
#include "assurance/edge_ai_scheduler.hpp"

// 前置声明，避免强依赖 dbus 头
struct DBusConnection;

namespace weaknet_dbus {

class DbusService;          // 前置声明：D-Bus 方法处理与信号发送
class WeakNetMgr;           // 前置声明：弱网管理器（接口列表 + 质量指标聚合）
class NetInfo;              // 前置声明：单个网卡的状态与指标模型
class BtMonitor;            // 前置声明：蓝牙监测器
class DnsMonitor;           // 前置声明：DNS 监控（eBPF）
class WifiPacketLossMonitor;// 前置声明：Wi-Fi 丢包归因（eBPF）
class HttpLatencyMonitor;   // 前置声明：HTTP 请求延迟（eBPF）
class ProcessNetProfiler;   // 前置声明：进程网络画像（eBPF）
class TcpRetransMonitor;    // 前置声明：TCP 重传监控（eBPF）
class TcpConnMonitor;       // 前置声明：TCP 连接生命周期监控（eBPF）
class TcpConnectMonitor;    // 前置声明：TCP 建连可观测性（eBPF）
class ActiveConnectivityMonitor; // 前置声明：受控主动连通性探测
class SkbDropMonitor;       // 前置声明：Socket 丢包归因监控（eBPF）
class TcpRttMonitor;        // 前置声明：被动 TCP RTT 监控（eBPF）
class BtDataPathAnalyzer;   // 前置声明：蓝牙 HCI ACL 数据通道分析器（eBPF）
class DatabaseManager;      // 前置声明：SQLite 历史数据持久化
class WirelessEventStore;   // 前置声明：规范化无线设备事件存储（Phase 1）
class BtLinkQualityTracker; // 前置声明：蓝牙链路质量跟踪器（Phase 2）
class SiteIncidentCorrelator; // 前置声明：区域级异常关联器（Phase 3a）
class ConfigTransaction;    // 前置声明：配置事务状态机（weaknet_config.hpp 中定义）

/**
 * @brief 服务端全局生命周期中枢
 *
 * 持有所有监控线程、eBPF 监控器、D-Bus 服务对象和共享数据。
 * 析构函数中按依赖逆序释放资源：先停止线程（join），再释放 eBPF 监控器和 DBusService。
 *
 * 线程安全约束：
 *   - running_: 原子变量，所有线程轮询检查退出信号
 *   - service/weak_mgr/bt_monitor/dns_monitor 等 unique_ptr: 启动后只读访问，无需额外锁
 */
struct ServerContext {
    ::DBusConnection* connection = nullptr;   ///< D-Bus 会话总线连接（由 DBus 库管理生命周期，析构时需显式 disconnection）

    std::atomic<bool> running{true};          ///< 全局运行标志。设为 false 后所有监控线程在下一个周期退出

    // ---------- 服务级线程 ----------
    // MonitorManager/各插件分别持有监控 worker；这里只保留历史持久化线程。
    std::thread history_thread;                 ///< 每 5 秒将 iface_list 快照写入 DB
    std::thread active_probe_thread;            ///< 受控主动连通性探测

    // ---------- 监控器插件生命周期 ----------
    std::unique_ptr<MonitorManager> monitor_manager; ///< 静态插件实例与生命周期协调器

    // ---------- 服务对象（unique_ptr 管理生命周期）----------
    std::unique_ptr<DbusService> service;                ///< D-Bus 服务：导出方法 + 发射信号
    std::unique_ptr<WeakNetMgr> weak_mgr;                ///< 弱网管理器：聚合所有监控器的数据更新
    std::unique_ptr<weaknet::MetricsRegistry> metrics_registry; ///< 权威度量注册表 (HR-4)
    std::unique_ptr<weaknet::DnsTransactionTracker> dns_tracker; ///< DNS userspace lifecycle authority (SR-11)
    std::atomic<uint64_t> dns_binding_epoch{1};
    // 评估 Profile **不在此处缓存副本**：权威值始终是 cfg.dns.assessment_profile。
    // 曾经这里存一份启动时拷贝，导致运行时 SetMonitorParam("dns.assessment_profile")
    // 写进 cfg 却永远不生效（D-Bus 回 ok、GetMonitorParam 显示新值，OverallPolicy
    // 仍用旧值）。ConfigString 由 mutex 保护，评估线程每轮直读即可，无需副本。
    // 读取统一走 currentAssessmentProfile()。

    // 监控器对象由对应插件拥有；这些裸指针仅为现有查询/聚合调用提供
    // non-owning 兼容视图。
    //
    // 线程安全约束（UAF 防护）：
    //   插件生命周期（start/stop/restart）对这些指针与底层 unique_ptr 进行
    //   写操作时持有独占写锁（std::unique_lock<std::shared_mutex>）；
    //   历史持久化、网络评估、边缘上行和 D-Bus 派发线程在解引用这些指针时
    //   持有共享读锁（std::shared_lock<std::shared_mutex>），杜绝插件销毁时的
    //   use-after-free 竞态窗口。
    mutable std::shared_mutex monitor_pointers_mutex;
    BtMonitor* bt_monitor = nullptr;
    DnsMonitor* dns_monitor = nullptr;
    WifiPacketLossMonitor* wifi_loss_monitor = nullptr;
    HttpLatencyMonitor* http_latency_monitor = nullptr;
    ProcessNetProfiler* process_net_profiler = nullptr;
    TcpRetransMonitor* tcp_retrans_monitor = nullptr;
    TcpConnMonitor* tcp_conn_monitor = nullptr;
    SkbDropMonitor* skb_drop_monitor = nullptr;
    TcpConnectMonitor* tcp_connect_monitor = nullptr;
    TcpRttMonitor* tcp_rtt_monitor = nullptr;
    BtDataPathAnalyzer* bt_hci_analyzer = nullptr;
    class BtDataPathAnomalyDetector* bt_anomaly_detector = nullptr;

    /// 受控主动连通性探测（宿主能力证据的唯一来源）
    std::unique_ptr<ActiveConnectivityMonitor> active_probe;

    // ---------- 权威评估快照（W2 单一事实源）----------
    // quality 线程是唯一 evaluator 执行点；每轮评估后发布不可变快照。
    // HealthCheck / GetNetworkExperience / history persistence 全部只读，
    // 绝不重新拉 metrics、重新 evaluate、重新调 OverallPolicy。
    weaknet::AssessmentSnapshotStore assessment_store;
    // 配置代已移至 WeakNetConfig::config_generation（由 setMonitorParam 统一推进）。
    // ServerContext 不再持有副本——副本无人推进，会让"配置变更即失效"整条
    // 生命周期静默失效（旧快照永不判过期）。读取用 ctx.cfg.config_generation。
    std::atomic<uint64_t> assessment_sequence{0}; ///< 快照发布序号

    /// 云端下发配置的事务协调器（STABLE / TRIAL / ROLLBACK）。
    /// 必须在 EdgeTelemetryExporter 之前构造，因为 exporter 持有它的裸指针。
    std::shared_ptr<ConfigTransaction> config_txn;

    // ---------- 历史数据持久化 ----------
    std::unique_ptr<DatabaseManager> db_mgr;   ///< SQLite 管理器，持有数据库连接

    // ---------- 无线设备事件（Phase 1: Canonical Device Event）----------
    // 事件由 bt_events 插件的 eBPF ringbuf 采集，经 BtEventNormalizer 归一化后
    // 写入 WirelessEventStore。store 依赖 db_mgr，因此**必须在 db_mgr 之后构造**。
    // 裸指针供查询/其它消费者使用；store 由 key_bt_events 插件拥有。
    WirelessEventStore* wireless_event_store = nullptr;

    // ---------- 蓝牙链路质量跟踪器（Phase 2: 基线与劣化检测）----------
    // 由 bt_events 插件拥有，提供给 BtMonitor 喂入 fresh RSSI，
    // 以及供 BtEventMonitor 在 Normalizer 之后做因果断连 RSSI 回填。
    BtLinkQualityTracker* bt_link_quality_tracker = nullptr;

    // ---------- 区域级异常关联器（Phase 3a: SiteIncident）----------
    // 由 bt_events 插件拥有，是 D-Bus / CLI / 离线工具三条查询出口的取数点。
    // 它同时是 WirelessEventStore 的下游消费者（事件流由 store 转发），
    // 因此销毁顺序必须是 store 先解绑、关联器后析构。
    SiteIncidentCorrelator* site_incident_correlator = nullptr;

    // ---------- 边缘遥测上报 ----------
    std::unique_ptr<weaknet::EdgeTelemetryExporter> edge_exporter;
    /// Phase 4a：无线事实（事件/事故/基线）独立上行器。与遥测并列，
    /// 幂等域与失败重发语义不同，故不合并（见集成设计决策 D1）。
    std::unique_ptr<weaknet::EdgeWirelessUplinkExporter> wireless_uplink;
    /// T3：端侧 AI 异步初筛调度器（容量=1，并发=1，300s 冷却，15s SIGKILL 硬超时）
    std::unique_ptr<weaknet::EdgeAiScheduler> edge_ai_scheduler;

    // ---------- 端侧确定性诊断引擎与证据生成服务 ----------
    std::shared_ptr<weaknet::ActionRegistry> action_registry;
    std::unique_ptr<weaknet::DiagnosisEngine> diagnosis_engine;
    std::unique_ptr<weaknet::EvidenceIdGenerator> evidence_id_generator;

    // ---------- per-monitor stop requests (阶段二) ----------
    // These flags are separate from running: they stop one worker without
    // affecting the service or any other monitor.
    std::atomic<bool> iface_stop{false};
    std::atomic<bool> using_iface_stop{false};
    std::atomic<bool> rtt_stop{false};
    // jitter_stop 已废弃：jitter 作为 rtt 的衍生指标合并进 rtt_monitor
    std::atomic<bool> rssi_stop{false};
    std::atomic<bool> tcp_loss_stop{false};
    std::atomic<bool> traffic_stop{false};
    std::atomic<bool> quality_stop{false};
    std::atomic<bool> bluetooth_stop{false};
    std::atomic<bool> dns_stop{false};
    std::atomic<bool> wifi_loss_stop{false};
    std::atomic<bool> http_latency_stop{false};
    std::atomic<bool> process_profiler_stop{false};
    std::atomic<bool> tcp_retrans_stop{false};
    std::atomic<bool> tcp_conn_stop{false};
    std::atomic<bool> tcp_connect_stop{false};
    std::atomic<bool> tcp_rtt_stop{false};
    std::atomic<bool> bt_events_stop{false};
    std::atomic<bool> active_probe_stop{false};

    // ---------- 频段冲突检测快照 ----------
    std::mutex conflict_mutex;
    std::string latest_conflict_json = "{\"detected\":false,\"confidence\":0.0,\"reason\":\"No 2.4GHz coexistence conflict detected\"}";

    // ---------- 运行时配置 ----------
    WeakNetConfig cfg;                          ///< 线程安全配置（启动时构建一次，此后通过 D-Bus 运行时调参）

    /**
     * @brief 析构：释放所有资源
     *
     * 执行顺序：
     *   1. running_ = false（通知所有监控线程退出）
     *   2. join 所有监控线程
     *   3. unique_ptr 析构 DbusService → WeakNetMgr → eBPF 监控器（释放 BPF link 和 map）
     *   4. 关闭 DBus 连接
     *
     * 注意：析构时 running_ 必须已设为 false，否则监控线程可能访问已释放的指针。
     */
    ~ServerContext();
};

/**
 * @brief 读取当前评估 Profile（权威来源：cfg.dns.assessment_profile）。
 *
 * 每次调用都现读配置，因此运行时 SetMonitorParam("dns.assessment_profile")
 * 会立刻对下一轮评估生效。未知值回落 INTERNET_ACCESS（与 parseAssessmentProfile
 * 及启动期告警行为一致）。
 */
inline weaknet::AssessmentProfile currentAssessmentProfile(const ServerContext& ctx) {
    return weaknet::parseAssessmentProfile(ctx.cfg.dns.assessment_profile.get());
}

/**
 * @brief 初始化 D-Bus 会话总线连接
 *
 * 执行步骤：
 *   1. dbus_threads_init_default() 启用线程安全
 *   2. dbus_bus_get(DBUS_BUS_SYSTEM) 获取系统总线连接
 *   3. dbus_bus_request_name() 注册 com.example.WeakNet 服务名
 *   4. 将连接存入 ctx->connection
 *
 * @param ctx 全局上下文，初始化后 connection 字段会被填充
 * @return DBus 连接指针，失败时返回 nullptr
 */
::DBusConnection* init_dbus(ServerContext* ctx);

// ---- 传统监控线程启动函数（供插件 start() 调用；生命周期由插件管理）----

void start_iface_monitor_thread(ServerContext* ctx, std::thread* worker);       ///< 网卡列表监控（netlink 事件驱动）
void start_using_iface_thread(ServerContext* ctx, std::thread* worker);         ///< 当前上网网卡监控
void start_traffic_analysis_thread(ServerContext* ctx, std::thread* worker);    ///< 流量分析（flow_rate 持有者）
void start_network_quality_thread(ServerContext* ctx, std::thread* worker);     ///< 网络质量综合评估

// ---- eBPF 监控线程启动函数（供插件 start() 调用）----

void start_dns_monitor_thread(ServerContext* ctx, std::thread* worker, DnsMonitor* monitor);             ///< DNS 解析延迟/超时（dns_monitor.bpf.o）
void start_wifi_loss_monitor_thread(ServerContext* ctx, std::thread* worker, WifiPacketLossMonitor* monitor);       ///< Wi-Fi 收发丢包归因（wifi_packet_loss.bpf.o）
void start_http_latency_monitor_thread(ServerContext* ctx, std::thread* worker, HttpLatencyMonitor* monitor);    ///< HTTP TTFB 延迟（http_latency.bpf.o）
void start_process_net_profiler_thread(ServerContext* ctx, std::thread* worker, ProcessNetProfiler* monitor);    ///< 每进程带宽/重传（flow_rate.bpf.o 共享）
void start_tcp_retrans_monitor_thread(ServerContext* ctx, std::thread* worker, TcpRetransMonitor* monitor);     ///< TCP 连接级重传（tcp_retransmit.bpf.o）
void start_tcp_conn_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnMonitor* monitor);        ///< TCP 连接生命周期（tcp_conn_stats.bpf.o）
void start_tcp_connect_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnectMonitor* monitor);   ///< TCP 建连（tcp_connect.bpf.o）
void start_tcp_rtt_monitor_thread(ServerContext* ctx, std::thread* worker, TcpRttMonitor* monitor);           ///< 被动 TCP RTT（tcp_rtt.bpf.o）
void start_active_probe_thread(ServerContext* ctx, std::thread* worker);   ///< 受控主动连通性探测
void applyActiveProbeConfig(ServerContext* ctx);                           ///< 根据当前配置更新并下发主动探测参数

void start_history_persistence_thread(ServerContext* ctx);     ///< 历史数据持久化（非监控器，server.cpp 单独启动）

/**
 * @brief 启动 WeakNet D-Bus 服务端主入口
 *
 * 完整启动流程：
 *   1. 解析 --config <path> 命令行参数（默认 /etc/weaknet/config.yaml）
 *   2. 加载配置文件，回落 WeakNetConfig 默认值（行为零变化）
 *   3. 应用日志级别配置
 *   4. 初始化日志系统
 *   5. 解析数据库路径（优先级：cfg.data_dir > WEAKNET_DATA_DIR > 默认）
 *   6. 启动 D-Bus 连接、监控线程、eBPF 监控器、历史持久化线程
 *   7. 主线程进入 Looper::run() 阻塞
 *
 * 该函数会阻塞，直到进程被外部信号（SIGINT/SIGTERM）终止或 ServerContext::running_ 被置 false。
 *
 * @return 0 正常退出；非零为配置错误等可恢复错误
 */
int start_server(int argc, char** argv);

}  // namespace weaknet_dbus

