        if (!ctx_) return;
        ctx_->bluetooth_stop.store(true);
        if (worker_.joinable()) worker_.join();
        {
            std::unique_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
            if (ctx_->bt_monitor == monitor_.get()) ctx_->bt_monitor = nullptr;
            monitor_.reset();
        }
    }
};

