222	 *
223	 * libdbus 采用 vtable 模式：一个对象路径对应一个 vtable，其中 message_function
224	 * 就是上面的静态转发函数。这样每条方法调用都会被路由到 MessageHandlerStatic。
225	 */
226	bool DbusService::register_on_connection(DBusConnection* conn) {
227	    static DBusObjectPathVTable vtable{};
228	    vtable.message_function = &MessageHandlerStatic;
229	    return dbus_connection_register_object_path(conn, kObjectPath, &vtable, this);
230	}
