658	/**
659	 * @brief 发送网络质量变更信号（三参数版：message + details + counter）
660	 * @param message 简短质量描述
661	 * @param details 详细质量评估（JSON 或长文本）
662	 * @param counter 事件计数器
663	 * @return true 发送成功
664	 */
665	bool DbusService::emitNetworkQualitySignal(const std::string& message, const std::string& details, int32_t counter) {
666	    std::lock_guard<std::mutex> lock(send_mutex_);
667	
668	    // 构造参数列表
669	    const char* quality = message.c_str();
670	    const char* details_str = details.c_str();
671	    std::vector<std::pair<int, const void*>> args = {
672	        {DBUS_TYPE_STRING, &quality},
673	        {DBUS_TYPE_STRING, &details_str},
674	        {DBUS_TYPE_INT32, &counter}
675	    };
676	
677	    return sendSignalInternal(kSignalNetworkQualityChanged, args, counter);
678	}
