1533	// ============================================================================
1534	// 无线设备事件查询（Phase 1b，只读）
1535	//
1536	// 返回 Canonical Device Event 的 JSON 数组。语义与 GetHistory 一致：
1537	// 全部参数可选、按位置解析、缺省即不限制。事件是诊断数据的系统出口——
1538	// 此前只能直连 SQLite，任何组件/运维都绕不开数据库文件。
1539	// ============================================================================
1540	
1541	bool DbusService::handleQueryDeviceEvents(DBusConnection* conn, DBusMessage* msg) {
1542	    LOG_INFO(LogModule::DBUS, "handleQueryDeviceEvents called");
1543	
1544	    // 可选参数：STRING device_address, STRING event_type,
1545	    //          INT64 start_ms, INT64 end_ms, INT32 limit
1546	    std::string device_address, event_type;
1547	    int64_t start_ms = 0, end_ms = 0;
1548	    int32_t limit = 100;
1549	
1550	    DBusMessageIter args;
1551	    if (dbus_message_iter_init(msg, &args) == TRUE) {
