1755	bool DbusService::handleSetMonitorParam(DBusConnection* conn, DBusMessage* msg) {
1756	    LOG_INFO(LogModule::DBUS, "handleSetMonitorParam called");
1757	
1758	    // 运行时调参能改变设备行为（例如 active_probe.targets 决定它主动连接谁），
1759	    // 因此与 ExecuteAction 同级：仅 root 可写。
1760	    if (!requireRootCaller(conn, msg, "SetMonitorParam")) return false;
1761	
1762	    DBusError err;
1763	    dbus_error_init(&err);
1764	    const char* key = nullptr;
1765	    const char* value = nullptr;
1766	
1767	    if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &key,
1768	                               DBUS_TYPE_STRING, &value, DBUS_TYPE_INVALID)) {
1769	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam arg error: " << err.message);
1770	        dbus_error_free(&err);
1771	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Invalid arguments (expect: string key, string value)");
1772	        dbus_connection_send(conn, reply, nullptr);
1773	        dbus_message_unref(reply);
1774	        return false;
1775	    }
1776	    if (!key || !value) {
1777	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Null key or value");
1778	        dbus_connection_send(conn, reply, nullptr);
1779	        dbus_message_unref(reply);
1780	        return false;
1781	    }
1782	
1783	    LOG_INFO(LogModule::DBUS, "SetMonitorParam: " << key << " = " << value);
1784	    std::string cfg_err;
1785	
1786	    // TRIAL 中本地调参会让回滚基线失真（trial 期间改过的 key，回滚时
1787	    // prior_values 已含云端的 trial 前值；本地再写一遍，等回滚来时被
1788	    // 覆盖成 trial 前 —— 等于把运维在 trial 期间的合法改动吞掉）。
1789	    // 因此 TRIAL 中显式拒绝本地写，等 confirm/rollback 后再放开。
1790	    if (ctx_->config_txn &&
1791	        ctx_->config_txn->state() == weaknet_dbus::ConfigState::TRIAL) {
1792	        cfg_err = "trial_in_progress";
1793	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
1794	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
1795	        dbus_connection_send(conn, reply, nullptr);
1796	        dbus_message_unref(reply);
1797	        return false;
1798	    }
1799	
1800	    // ctx_->cfg 是线程安全配置，setMonitorParam 内部对目标字段做校验+原子写入
1801	    if (!setMonitorParam(&ctx_->cfg, key, value, &cfg_err)) {
1802	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
1803	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
1804	        dbus_connection_send(conn, reply, nullptr);
1805	        dbus_message_unref(reply);
1806	        return false;
1807	    }
1808	
1809	    // 若修改的是 active_probe 参数，立即重载配置并下发至运行中的探测实例，使改动实时生效
1810	    if (std::string(key).rfind("active_probe.", 0) == 0) {
1811	        applyActiveProbeConfig(ctx_);
1812	    }
1813	
1814	    LOG_INFO(LogModule::DBUS, "SetMonitorParam applied: " << key << " = " << value);
1815	
1816	    // 本地调参同样是一条 L1 事实，且是唯一一条"未经云端队列"的写入路径：
1817	    // 云端没有 network_pending_actions 记录可关联，只能由回执自带
1818	    // key/value/generation，才能落成一行 execution_origin=LOCAL_OPERATION 的
1819	    // outcome，与云端下发动作同表可查（否则本地改动在云端只表现为
1820	    // config_generation 跳变，无从判断改了什么）。
1821	    // 放在成功分支之后——上面失败处均已 return，能走到这里状态确实已变更。
1822	    if (ctx_ && ctx_->edge_exporter) {
1823	        ctx_->edge_exporter->emitLocalConfigChange(
1824	            key, value, "local_dbus_set", ctx_->cfg.config_generation.load());
1825	    }
1826	
1827	    // 返回成功
1828	    DBusMessage* reply = dbus_message_new_method_return(msg);
1829	    if (!reply) return false;
1830	
1831	    const char* status = "ok";
1832	    DBusMessageIter reply_args;
1833	    dbus_message_iter_init_append(reply, &reply_args);
1834	    dbus_message_iter_append_basic(&reply_args, DBUS_TYPE_STRING, &status);
1835	    dbus_connection_send(conn, reply, nullptr);
1836	    dbus_connection_flush(conn);
1837	    dbus_message_unref(reply);
1838	    return true;
1839	}
