1973	// The lifecycle handlers share the same argument validation and reply contract.
1974	bool DbusService::handleMonitorOperation(DBusConnection* conn, DBusMessage* msg,
1975	                                         const char* operation) {
1976	    // enable/disable/restart 会改变评估管线的运行态（例如停掉 quality 即静默
1977	    // 关闭整套评估），与运行时调参同级：仅 root 可写。
1978	    if (!requireRootCaller(conn, msg, operation)) return false;
1979	
1980	    DBusError err;
1981	    dbus_error_init(&err);
1982	    const char* name = nullptr;
1983	    if (!monitorNameArg(msg, &name, &err)) {
1984	        const char* text = dbus_error_is_set(&err) ? err.message : "missing monitor name";
1985	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", text);
1986	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
1987	        dbus_error_free(&err);
1988	        return false;
1989	    }
1990	    if (!ctx_ || !ctx_->monitor_manager) {
1991	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "monitor manager unavailable");
1992	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
1993	        return false;
1994	    }
1995	    std::string error;
1996	    bool ok = false;
1997	    if (std::string(operation) == "enable") ok = ctx_->monitor_manager->enable(name, &error);
1998	    else if (std::string(operation) == "disable") ok = ctx_->monitor_manager->disable(name, &error);
1999	    else ok = ctx_->monitor_manager->restart(name, &error);
2000	    if (!ok) {
2001	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", error.c_str());
2002	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
2003	        return false;
2004	    }
2005	    MonitorStatus status;
