/**
 * @brief 启动蓝牙监测后台线程：初始化 → Phase 2 eBPF → 主循环（3s 轮询） → 事件转发 → 被动重试
 * @param ctx ServerContext 生命周期句柄，线程通过非 owning 指针使用 monitor；ownership 由 BluetoothPlugin 持有
 * @param outMonitor 输出参数（预留）
 */
void start_bt_monitor_thread(ServerContext* ctx, std::thread* worker, BtMonitor** /*outMonitor*/) {
    // BtMonitor 由 BluetoothPlugin 持有 ownership，线程只借用 ServerContext 的查询视图。
    *worker = std::thread([ctx]() {
        LOG_INFO(LogModule::BLUETOOTH, "BT monitor thread started");

        auto* monitor = ctx->bt_monitor;
        if (!monitor) {
            LOG_ERROR(LogModule::BLUETOOTH, "BT monitor: ctx->bt_monitor is null");
            return;
        }

        // 注入 Phase 2 链路跟踪器与事件存储
        monitor->setQualityTracker(ctx->bt_link_quality_tracker, ctx->wireless_event_store);

        if (!monitor->initialize()) {
            LOG_INFO(LogModule::BLUETOOTH, "BT monitor: no Bluetooth adapter available, "
                     "thread will run in passive mode (periodic retry)");
        } else {
            LOG_INFO(LogModule::BLUETOOTH, "BT monitor: initialized successfully");

            // ================================================================
            // Phase 2: 初始化 eBPF 融合层（legacy A2DP，默认停用）
            // 工业蓝牙 HCI ACL 新探针（bt_hci_traffic）验收通过后，旧 A2DP 探针
            // 默认不挂载，避免两套采集链同时挂在内核上重复统计/增加开销。
            // 保留 bluetooth.a2dp_fusion_enabled 开关与接口兼容，需要时可显式开回。
            // ================================================================
            if (ctx->cfg.bluetooth.a2dp_fusion_enabled.load()) {
                try {
                    // 按 bluetooth 配置块解算 a2dp 两张 map 的容量计划；必须在
                    // bpf_object__load 之前传入，否则 active_sessions/bt_traffic
                    // 会保留内核编译期容量，使 bluetooth.map_sizing 三键永不生效
                    bool ebpfOk = monitor->initPhase2(
                        ctx->cfg.bluetooth.bpf_obj.get().c_str(),
                        weaknet::resolveScopePlan(
                            weaknet::MapSizingScope::Bluetooth,
                            {ctx->cfg.bluetooth.map_sizing.mode.get(),
                             ctx->cfg.bluetooth.map_sizing.entries.load(),
                             ctx->cfg.bluetooth.map_sizing.ram_budget_bp.load()},
                            weaknet::totalPhysicalRamBytes()));
                    if (ebpfOk) {
                        LOG_INFO(LogModule::BLUETOOTH, "BT monitor: Phase 2 eBPF fusion enabled ("
                                 << (monitor->isPhase2Available() ? "active" : "fallback") << ")");
                    } else {
                        LOG_INFO(LogModule::BLUETOOTH, "BT monitor: Phase 2 eBPF unavailable"
                                 " — falling back to D-Bus-only audio quality monitoring");
                    }
                } catch (const std::exception& e) {
                    LOG_ERROR(LogModule::BLUETOOTH, "BT monitor: Phase 2 init failed: " << e.what());
                }
            } else {
                LOG_INFO(LogModule::BLUETOOTH,
                         "BT monitor: legacy A2DP eBPF probe retired by default "
                         "(bluetooth.a2dp_fusion_enabled=false; superseded by bt_hci_traffic)");
            }
        }

        int loopCount = 0;
        int retryCount = 0;
        static constexpr int RETRY_INTERVAL = 30;  // 每 30 秒重试初始化

        while (ctx->running.load() && !ctx->bluetooth_stop.load()) {
            loopCount++;

            if (!monitor->isInitialized()) {
                // 被动模式：定期重试初始化 (适用于蓝牙适配器热插拔)
                retryCount++;
                if (retryCount >= RETRY_INTERVAL / 3) {  // ~每 30s 重试
                    retryCount = 0;
                    LOG_INFO(LogModule::BLUETOOTH, "BT monitor: retrying initialization...");
                    if (monitor->initialize()) {
                        LOG_INFO(LogModule::BLUETOOTH, "BT monitor: initialized after retry");
                    } else {
                        // 清理失败的连接
                        monitor->cleanup();
                    }
                }
                uint32_t retry_interval = ctx->cfg.bluetooth.interval_ms.load(std::memory_order_relaxed);
                if (retry_interval < 500) retry_interval = 500;
                std::this_thread::sleep_for(std::chrono::milliseconds(retry_interval));
                continue;
            }

            // 刷新适配器状态
            monitor->refreshAdapterState();

            if (monitor->hasAdapter()) {
                // 处理并分发 D-Bus 信号队列（PropertiesChanged / InterfacesAdded/Removed）
                monitor->processPendingSignals();

                // 周期刷新设备状态与 A2DP 音频状态
                monitor->refreshDeviceStates();

                // 获取事件并转发到 EventManager
                auto events = monitor->fetchEvents();
                for (const auto& ev : events) {
                    switch (ev.type) {
                        case BtEvent::Type::DeviceConnected:
                        case BtEvent::Type::DeviceDisconnected:
                        case BtEvent::Type::DeviceFound:
                        case BtEvent::Type::DeviceLost:
                        case BtEvent::Type::DeviceRssiChanged:
                        case BtEvent::Type::DiscoveryStarted:
                        case BtEvent::Type::DiscoveryStopped:
                            // 所有蓝牙事件统一走 EventManager，发射正确的信号
                            getEventManager().emitBluetoothDeviceChanged(
                                ev.message,
                                ev.deviceName.empty() ? ev.deviceMac : ev.deviceName);
                            break;

                        case BtEvent::Type::AdapterAdded:
                        case BtEvent::Type::AdapterRemoved:
                        case BtEvent::Type::AdapterPowered:
                            // 适配器事件直接发射 D-Bus 信号
                            if (ctx->service) {
                                ctx->service->emitSpecificSignal(
                                    kSignalBluetoothDeviceChanged, ev.message, 0);
                            }
                            break;
                    }
                }

                // 每 6 轮 (~18s) 打印蓝牙状态摘要并周期持久化基线画像
                if (loopCount % 6 == 0) {
                    if (ctx->bt_link_quality_tracker && ctx->wireless_event_store) {
                        auto profiles = ctx->bt_link_quality_tracker->getAllProfiles();
                        for (const auto& p : profiles) {
                            ctx->wireless_event_store->saveDeviceBaseline(p);
                        }
                    }

                    auto nearby = monitor->getNearbyDevices(30);
                    auto connected = monitor->getConnectedDevices();

                    LOG_INFO(LogModule::BLUETOOTH, "BT_SUMMARY: "
                        << monitor->deviceCount() << " known, "
                        << connected.size() << " connected, "
                        << nearby.size() << " nearby");

                    for (const auto& dev : connected) {
                        LOG_INFO(LogModule::BLUETOOTH, "BT_CONNECTED: "
                            << dev.name << " (" << dev.macAddress << ") | "
                            << "RSSI:" << dev.rssiDbm << "dBm"
                            << (dev.rssiDbm != 0 ? " (" + dev.rssiLevel() + ")" : ""));
                    }

                    for (size_t i = 0; i < std::min(nearby.size(), size_t(5)); ++i) {
                        const auto& dev = nearby[i];
                        if (!dev.connected) {
                            LOG_INFO(LogModule::BLUETOOTH, "BT_NEARBY: "
                                << (i+1) << ". " << dev.name
                                << " | RSSI:" << dev.rssiDbm << "dBm"
                                << " | " << dev.rssiLevel());
                        }
                    }
                }
            }

            // 动态按配置间隔睡眠（兜底不少于 500ms）
            uint32_t interval_ms = ctx->cfg.bluetooth.interval_ms.load(std::memory_order_relaxed);
            if (interval_ms < 500) interval_ms = 500;

