1	/**
2	 * @file weak_netmgr.cpp
3	 * @brief WeakNetMgr：网络接口列表构建与各项指标（RTT/RSSI/TCP丢包/抖动/流量）的线程安全刷新
4	 *
5	 * 模块职责：
6	 *   - 从 NetInterfaceManager 获取系统 Internet 接口列表
7	 *   - 使用 UsingInterfaceManager 标记"当前上网接口"（唯一事实源）
8	 *   - 为每个接口填充 RTT（通过 NetPing 主动探测）、Wi-Fi RSSI（通过 wpa_supplicant ctrl socket）、
9	 *     TCP 丢包率（netlink SOCK_DIAG 采样 tcp_info；eBPF 的 tcp_retrans 监控器是独立的
10	 *     连接级消费者，其输出不经本路径）、抖动（rtt_monitor 衍生）、流量统计（TrafficAnalyzer）
11	 *   - 线程安全：所有对 current_interfaces_ 的读写通过 std::mutex 保护（*Safe 系列方法）
12	 *
13	 * 依赖的外部接口：
14	 *   - **NetInterfaceManager (net_iface.h)**       获取系统网络接口列表
15	 *   - **UsingInterfaceManager (using_iface.h)**   判断当前哪个接口在上网（读取路由表）
16	 *   - **NetPing (net_ping.h)**                    ICMP RTT 主动探测
17	 *   - **WiFiRssiClient (net_wifiriss.h)**         通过 wpa_supplicant ctrl socket 获取 Wi-Fi RSSI
18	 *   - **TrafficAnalyzer (traffic_analyzer.hpp)** 流量分析器（bps/pps/flows/top flows/异常检测）
19	 *
20	 * 数据流向：
21	 *   collectCurrentInterfaces() → 构建初始 NetInfo 列表（含 usingNow 标记）
22	 *       ↓
23	 *   updateRttAndStateForIfaceSafe() ── rtt_monitor 锁外 ping 后的样本 → RTT
24	 *   updateWifiRssiSafe()     ── wpa ctrl socket → RSSI（仅 WiFi 接口）
25	 *   updateTcpLossRateSafe()  ── 外部 monitor 推送 → TCP 丢包率
26	 *   updateJitterSafe()       ── 外部 monitor 推送 → 抖动
27	 *   updateTrafficAnalysisSafe() ── TrafficAnalyzer → bps/pps/flows
28	 *       ↓
29	 *   NetworkQualityAssessor::assessQuality() → 综合评分
30	 */
31	
32	#include "weak_netmgr.hpp"
33	#include "net_iface.h"
34	#include "using_iface.h"
35	#include "net_ping.h"
36	#include "net_wifiriss.h"
37	#include "traffic_analyzer.hpp"
38	#include "iface_type.hpp"
39	#include "logger.hpp"
40	#include <algorithm>
41	#include <chrono>
42	#include <sys/stat.h>
43	
44	namespace weaknet_dbus {
45	
46	static int64_t metricTimestampMs() {
47	    return std::chrono::duration_cast<std::chrono::milliseconds>(
48	        std::chrono::system_clock::now().time_since_epoch()).count();
49	}
50	
51	std::vector<NetInfo> WeakNetMgr::collectCurrentInterfaces() {
52	    LOG_INFO(LogModule::WEAK_MGR, "collectCurrentInterfaces begin");
53	    std::vector<NetInfo> result;
54	    auto mgr = NetInterfaceManager::getInstance();
55	    auto names = mgr->getInternetInterfaces();
56	    result.reserve(names.size());
57	    for (const auto& n : names) {
58	        NetInfo info(n);
59	        // 根据 sysfs wireless 标志识别 Wi-Fi，接口名前缀作为有线接口后备
60	        if (isWirelessInterface(n)) {
61	            info.setType(NetType::WiFi);
62	        } else if (n.rfind("eth", 0) == 0 || n.rfind("enp", 0) == 0) {
63	            info.setType(NetType::Ethernet);
64	        } else {
65	            info.setType(NetType::Unknown);
66	        }
67	        info.setDefaultRoute(false);
68	        info.setState(NetState::Up);
69	        info.setRttMs(-1);
70	        result.push_back(info);
71	    }
72	    // 标记当前上网网卡（using 标志）
73	    // 唯一事实源 = UsingInterfaceManager（启动后不重复调 start()）
74	    auto usingMgr = UsingInterfaceManager::getInstance();
75	    std::string usingIf = usingMgr->getCurrentInterface();
76	    for (auto& x : result) x.setUsingNow(!usingIf.empty() && x.ifName() == usingIf);
77	    LOG_INFO(LogModule::WEAK_MGR, "collectCurrentInterfaces end: " << result.size() << " ifaces, using=" << (usingIf.empty() ? "(none)" : usingIf));
78	    return result;
79	}
80	static LinkQuality classifyQualityFromRtt(int rttMs, int /*prevMs*/) {
81	    if (rttMs < 0) return LinkQuality::Bad;
82	    // 简单阈值，可按需调整
83	    if (rttMs <= 50) return LinkQuality::Good;
84	    if (rttMs <= 100) return LinkQuality::Fair;
85	    if (rttMs <= 200) return LinkQuality::Poor;
86	    return LinkQuality::Bad;
87	}
88	
89	// 说明：这里原有两个函数 —— updateRttAndStateSafe() 与它独占的
90	// updateRttAndState() —— 已随 RTT 采集路径改造一并删除：
91	//   - updateRttAndStateSafe() 持 iface_mutex_ 期间对**每个**接口做 ICMP ping
92	//     （多接口 × timeout 可达数秒），期间 getCurrentInterfaces() 的所有读者
93	//     ——含 D-Bus 的 ListInterfaces / HealthCheck——全部被阻塞；
94	//   - RTT 更新现已改走 updateRttAndStateForIfaceSafe()：由 rtt_monitor 在
95	//     **锁外**完成 ping，再持锁写回单个接口（见 rtt_monitor.cpp）。
96	// 两者在改造后均无任何调用者，属于"锁内做 I/O"缺陷的遗留并行路径，
97	// 删除以免保留第二个 RTT 写入入口。
98	
99	bool WeakNetMgr::updateWifiRssi(std::vector<NetInfo>& list, const std::string& ctrlDir) {
100	    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: starting, ctrlDir=" << ctrlDir << " size=" << list.size());
101	    auto client = WiFiRssiClient::getInstance();
102	    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: got client instance");
103	    bool anyChanged = false;
104	    for (auto& x : list) {
105	        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: processing interface " << x.ifName() << " type=" << static_cast<int>(x.type()));
106	        if (x.type() != NetType::WiFi) {
107	            LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: skipping non-WiFi interface " << x.ifName());
108	            continue;
109	        }
110	        // 若尚未连接，尝试连接 ctrl 套接字
111	        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: attempting to connect to " << x.ifName());
112	        if (!client->connect(x.ifName(), ctrlDir)) {
113	            LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: failed to connect to " << x.ifName());
114	            continue;
115	        }
116	        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: connected to " << x.ifName() << ", getting RSSI");
117	        RssiSample sample = readNl80211Rssi(x.ifName());
118	        if (!sample.valid) {
119	            int rssi = client->getRssi();
120	            if (rssi != -1000) {
121	                sample = {rssi, true, false, "wpa_supplicant"};
122	            } else {
123	                rssi = readProcWirelessRssi(x.ifName());
124	                if (rssi != -1000) sample = {rssi, true, true, "proc_net_wireless_quality"};
125	            }
126	        }
127	        const int rssi = sample.valid ? sample.dbm : -1000;
128	        if (sample.valid) {
129	            x.setRssiEstimated(sample.estimated);
130	            x.setRssiSource(sample.source);
131	            x.setRssiSampleTsMs(metricTimestampMs());
132	        }
133	        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: got RSSI " << rssi << " for " << x.ifName());
134	        // 无效值仅表示本轮未测量，不覆盖已有有效 RSSI，避免瞬时控制通道/驱动异常污染快照。
135	        if (rssi == -1000) {
136	            LOG_WARNING(LogModule::RSSI, "RSSI unavailable for " << x.ifName() << "; retaining previous value");
137	            x.setRssiSampleTsMs(0);
138	            continue;
139	        }
140	        if (x.rssiDbm() != rssi || x.rssiSource() != sample.source || x.rssiEstimated() != sample.estimated) {
141	            x.setRssiDbm(rssi);
142	            x.setRssiSampleTsMs(metricTimestampMs());
143	            anyChanged = true;
144	            if (x.usingNow()) {
145	                LOG_INFO(LogModule::RSSI, "using iface " << x.ifName() << " RSSI=" << rssi << " dBm");
146	            }
147	            LOG_INFO(LogModule::WEAK_MGR, "iface=" << x.ifName() << " rssi=" << rssi);
148	        }
149	    }
150	    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: completed, anyChanged=" << anyChanged);
151	    return anyChanged;
152	}
153	
154	bool WeakNetMgr::updateCurrentUsing(std::vector<NetInfo>& list, bool printLog, std::string* outIfName, uint32_t* outFlags) {
155	    auto usingMgr = UsingInterfaceManager::getInstance();
156	    std::string usingIf = usingMgr->getCurrentInterface();
157	    uint32_t flags = usingMgr->getMethodFlags();
158	
159	    bool changed = false;
160	    LOG_INFO(LogModule::WEAK_MGR, "updateCurrentUsing: current=" << (usingIf.empty() ? "(none)" : usingIf) << " flags=" << flags);
161	    for (auto& x : list) {
162	        bool should = (!usingIf.empty() && x.ifName() == usingIf);
163	        if (x.usingNow() != should) { x.setUsingNow(should); changed = true; }
164	    }
165	    if (outIfName) *outIfName = usingIf;
166	    if (outFlags) *outFlags = flags;
167	    if (printLog) {
168	        if (!usingIf.empty()) {
169	            LOG_INFO(LogModule::INTERFACE, "current=" << usingIf << " flags=" << 
170	                ((flags & UsingMethodFlag::IPv4Default) ? "IPv4" : "") << 
171	                (((flags & UsingMethodFlag::IPv4Default) && (flags & UsingMethodFlag::IPv6Default)) ? "+" : 
172	                 ((flags & UsingMethodFlag::IPv6Default) ? "IPv6" : "")));
173	        } else {
174	            LOG_INFO(LogModule::INTERFACE, "current=(none)");
175	        }
176	    }
177	    return changed;
178	}
