187	bool WeakNetMgr::updateTcpLossRate(std::vector<NetInfo>& list, 
188	                                  const std::string& iface_name, 
189	                                  double loss_rate, 
190	                                  const std::string& loss_level) {
191	    bool changed = false;
192	    LOG_INFO(LogModule::WEAK_MGR, "updateTcpLossRate: iface=" << iface_name << " rate=" << loss_rate << " level=" << loss_level);
193	    
194	    for (auto& x : list) {
195	        if (x.ifName() == iface_name) {
196	            const bool rateChanged = x.tcpLossRate() != loss_rate;
197	            const bool levelChanged = x.tcpLossLevel() != loss_level;
198	            x.setTcpLossRate(loss_rate);
199	            x.setTcpLossLevel(loss_level);
200	            // 时间戳表示最近一次成功采样，即使数值未变化也必须刷新。
201	            x.setTcpLossSampleTsMs(metricTimestampMs());
202	            if (rateChanged || levelChanged) {
203	                changed = true;
204	                if (x.usingNow()) {
205	                    LOG_INFO(LogModule::TCP_LOSS, "using iface " << iface_name << " TCP loss rate updated: " << loss_rate << "% (" << loss_level << ")");
206	                }
207	                LOG_INFO(LogModule::WEAK_MGR, "iface=" << x.ifName() << " tcp_loss_rate=" << x.tcpLossRate() << " tcp_loss_level=" << x.tcpLossLevel());
208	            }
209	            break;
210	        }
211	    }
212	    return changed;
213	}
