261	bool WeakNetMgr::updateTrafficAnalysis(std::vector<NetInfo>& list) {
262	    if (!traffic_analyzer_ || !traffic_analyzer_->isRunning()) {
263	        return false;
264	    }
265	    
266	    bool changed = false;
267	    
268	    try {
269	        // 获取当前流量统计
270	        auto stats = traffic_analyzer_->getCurrentStats();
271	        
272	        // 获取Top流量连接
273	        auto topFlows = traffic_analyzer_->getTopFlows(5, 10);
274	        
275	        // 检测异常流量
276	        auto anomalies = traffic_analyzer_->detectAnomalies(5);
277	        
278	        // 更新当前上网网卡的流量信息
279	        for (auto& net : list) {
280	            if (net.usingNow()) {
281	                // 更新流量统计信息
282	                net.setTrafficStats(stats.totalBps, stats.totalPps, stats.activeFlows);
283	                net.setTrafficSampleTsMs(metricTimestampMs());
284	                
285	                // 如果有异常流量，记录日志
286	                if (!anomalies.empty()) {
287	                    LOG_INFO(LogModule::WEAK_MGR, "Traffic anomalies detected on " << net.ifName() 
288	                        << ": " << anomalies.size() << " anomalies");
289	                    for (const auto& anomaly : anomalies) {
290	                        LOG_INFO(LogModule::WEAK_MGR, "Anomaly: " << anomaly.anomalyType 
291	                            << " severity: " << (anomaly.severity * 100) << "%");
292	                    }
293	                }
294	                
295	                LOG_INFO(LogModule::WEAK_MGR, "Updated traffic stats for " << net.ifName() 
296	                    << ": " << (stats.totalBps / (1024*1024)) << " MB/s, " 
297	                    << stats.activeFlows << " flows, " << stats.totalPps << " pps");
298	                
299	                changed = true;
300	                break;
301	            }
302	        }
303	        
304	    } catch (const std::exception& e) {
305	        LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis update error: " << e.what());
306	    }
307	
308	    return changed;
309	}
