317	void WeakNetMgr::updateInterfaces(const std::vector<NetInfo>& new_interfaces) {
318	    std::lock_guard<std::mutex> lock(iface_mutex_);
319	    current_interfaces_ = new_interfaces;
320	    ++snapshot_generation_;
321	    const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
322	        std::chrono::system_clock::now().time_since_epoch()).count();
323	    for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
324	    LOG_INFO(LogModule::WEAK_MGR, "Updated interfaces list: " << current_interfaces_.size() << " interfaces");
325	}
