327	bool WeakNetMgr::markMetricUnavailable(const std::string& metric) {
328	    std::lock_guard<std::mutex> lock(iface_mutex_);
329	    for (auto& iface : current_interfaces_) {
330	        if (metric == "rtt") iface.setRttMs(-1);
331	        else if (metric == "jitter") iface.setJitterMs(-1.0);
332	        else if (metric == "rssi") { iface.setRssiDbm(-1000); iface.setRssiEstimated(false); }
333	        else if (metric == "tcp_loss") iface.setTcpLossRate(-1.0);
334	        else if (metric == "traffic") iface.setTrafficStats(0, 0, 0);
335	        else return false;
336	    }
337	    ++snapshot_generation_;
338	    const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
339	        std::chrono::system_clock::now().time_since_epoch()).count();
340	    for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
341	    return true;
342	}
