344	std::optional<std::string> WeakNetMgr::getCurrentUsingInterface() const {
345	    std::lock_guard<std::mutex> lock(iface_mutex_);
346	    for (const auto& iface : current_interfaces_) {
347	        if (iface.usingNow()) {
348	            return iface.ifName();
349	        }
350	    }
351	    // 无上行时如实返回 nullopt，**不再回退到 current_interfaces_[0]**。
352	    // 回退会凭空造出一个"正在上网"的网卡：启动早期或路由抖动期间，
353	    // 所有 SLE 结论、D-Bus 快照的 interface 字段与历史行都会被归到那张
354	    // 列表首位的网卡上，而设备和它毫无关系。调用方必须显式处理"无上行"。
355	    return std::nullopt;
356	}
