358	bool WeakNetMgr::updateRttAndStateForIfaceSafe(const std::string& iface_name, int rtt_ms) {
359	    LOG_DEBUG(LogModule::WEAK_MGR, "updateRttAndStateForIfaceSafe: acquiring lock, iface=" << iface_name << " rtt=" << rtt_ms);
360	    bool result = false;
361	    int rtt_for_publish = rtt_ms;
362	    {
363	        std::lock_guard<std::mutex> lock(iface_mutex_);
364	        for (auto& x : current_interfaces_) {
365	            if (x.ifName() != iface_name) continue;
366	            int prev = x.rttMs();
367	            const bool rttChanged = x.rttMs() != rtt_ms;
368	            x.setPrevRttMs(prev);
369	            x.setRttMs(rtt_ms);
370	            if (rttChanged) { result = true; }
371	            x.setRttSampleTsMs(metricTimestampMs());
372	            LinkQuality q = classifyQualityFromRtt(rtt_ms, prev);
373	            if (x.quality() != q) { x.setQuality(q); result = true; }
374	            NetState ns = (rtt_ms >= 0) ? NetState::Up : NetState::Down;
375	            if (x.state() != ns) { x.setState(ns); result = true; }
376	            if (result) {
377	                ++snapshot_generation_;
378	                const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
379	                    std::chrono::system_clock::now().time_since_epoch()).count();
380	                x.markMetricUpdated(snapshot_generation_, now);
381	            }
382	            break;
383	        }
384	    }
385	
386	    // MR-2 铁律：必须在释放 iface_mutex_ 后再向 MetricsRegistry 发布
387	    if (metrics_registry_) {
388	        if (rtt_for_publish >= 0) {
389	            metrics_registry_->publish(iface_name, weaknet::MetricId::RTT_MS, weaknet::MetricSample::valid(rtt_for_publish));
390	            metrics_registry_->publish(iface_name, weaknet::MetricId::REACHABILITY_SUCCESS, weaknet::MetricSample::valid(1.0));
391	        } else {
392	            metrics_registry_->publish(iface_name, weaknet::MetricId::REACHABILITY_SUCCESS, weaknet::MetricSample::valid(0.0));
393	        }
394	    }
395	    return result;
396	}
