398	bool WeakNetMgr::updateWifiRssiSafe(const std::string& ctrlDir) {
399	    LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: acquiring lock");
400	    std::vector<std::pair<std::string, int>> rssi_snapshots;
401	    bool result = false;
402	    {
403	        std::lock_guard<std::mutex> lock(iface_mutex_);
404	        LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: lock acquired, calling updateWifiRssi");
405	        result = updateWifiRssi(current_interfaces_, ctrlDir);
406	        if (result) ++snapshot_generation_;
407	        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
408	        if (result) {
409	            for (auto& iface : current_interfaces_) {
410	                iface.markMetricUpdated(snapshot_generation_, now);
411	                rssi_snapshots.emplace_back(iface.ifName(), iface.rssiDbm());
412	            }
413	        }
414	        LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: updateWifiRssi completed, releasing lock");
415	    }
416	
417	    // MR-2: 锁外发布
418	    if (metrics_registry_ && result) {
419	        for (const auto& item : rssi_snapshots) {
420	            if (item.second > -1000) {
421	                metrics_registry_->publish(item.first, weaknet::MetricId::RSSI_DBM, weaknet::MetricSample::valid(item.second));
422	            }
423	        }
424	    }
425	    return result;
426	}
