468	bool WeakNetMgr::updateTrafficAnalysisSafe() {
469	    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: acquiring lock");
470	
471	    // 先在锁外获取流量统计（避免长时间阻塞）
472	    NetTrafficAnalyzer::RealTimeStats stats;
473	    std::vector<FlowRate> topFlows;
474	    std::vector<TrafficAnomaly> anomalies;
475	    bool hasStats = false;
476	
477	    if (traffic_analyzer_ && traffic_analyzer_->isRunning()) {
478	        try {
479	            stats = traffic_analyzer_->getCurrentStats();
480	            hasStats = true;
481	            // 注意：getTopFlows 和 detectAnomalies 会阻塞，但在锁外执行
482	            topFlows = traffic_analyzer_->getTopFlows(5, 10);
483	            anomalies = traffic_analyzer_->detectAnomalies(5);
484	        } catch (const std::exception& e) {
485	            LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis data fetch error: " << e.what());
486	        }
487	    }
488	
489	    // 然后在锁内更新接口列表（快速操作）
490	    std::lock_guard<std::mutex> lock(iface_mutex_);
491	    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: lock acquired, updating interfaces");
492	
493	    bool changed = false;
494	    if (hasStats) {
495	        // 归因必须用分析器**实际绑定**的网卡，而不是"当前恰好是上行"的网卡。
496	        // 分析器在启动时绑定一次（TrafficAnalyzer::start 的 running_ 守卫使重绑定
497	        // 需要拆建 BPF，不在本函数职责内），此后一直采样那一张网卡。若按
498	        // usingNow() 归因，上行从 wlan0 切到 eth0 后，wlan0 的采样值会被写到
499	        // eth0 上——history.db 里 eth0 出现凭空捏造的流量，而 wlan0 的真实流量
500	        // 消失，且没有任何日志能暴露这个错位。
501	        const std::string bound_iface = traffic_analyzer_->boundInterface();
502	        for (auto& net : current_interfaces_) {
503	            if (net.ifName() != bound_iface) continue;
504	
505	            net.setTrafficStats(stats.totalBps, stats.totalPps, stats.activeFlows);
506	            net.setTrafficSampleTsMs(metricTimestampMs());
507	
508	            if (!anomalies.empty()) {
509	                LOG_INFO(LogModule::WEAK_MGR, "Traffic anomalies detected on " << net.ifName()
510	                    << ": " << anomalies.size() << " anomalies");
511	                for (const auto& anomaly : anomalies) {
512	                    LOG_INFO(LogModule::WEAK_MGR, "Anomaly: " << anomaly.anomalyType
513	                        << " severity: " << (anomaly.severity * 100) << "%");
514	                }
515	            }
516	
517	            LOG_INFO(LogModule::WEAK_MGR, "Updated traffic stats for " << net.ifName()
518	                << ": " << (stats.totalBps / (1024*1024)) << " MB/s, "
519	                << stats.activeFlows << " flows, " << stats.totalPps << " pps");
520	
521	            changed = true;
522	            break;
523	        }
524	    }
525	
526	    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: completed, releasing lock");
527	    return changed;
528	}
529	
530	bool WeakNetMgr::updateCurrentUsingSafe() {
531	    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: acquiring lock");
532	    std::lock_guard<std::mutex> lock(iface_mutex_);
533	    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: lock acquired, calling updateCurrentUsing");
534	    bool result = updateCurrentUsing(current_interfaces_, true);
535	    // 上行网卡切换同样是"快照内容变了"，必须推进代次并刷新各接口的
536	    // markMetricUpdated。此前这里漏了，导致切换前后 history.db 里两条
537	    // 记录可能携带相同的 generation/last_updated_ms，而它们描述的却是
538	    // 不同的活动网卡，削弱了采样一致性元数据的可信度。
539	    if (result) {
540	        ++snapshot_generation_;
541	        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
542	            std::chrono::system_clock::now().time_since_epoch()).count();
543	        for (auto& iface : current_interfaces_) {
544	            iface.markMetricUpdated(snapshot_generation_, now);
545	        }
546	    }
547	    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: updateCurrentUsing completed, releasing lock");
548	    return result;
549	}
550	
551	}  // namespace weaknet_dbus
