/**
 * @file weak_netmgr.cpp
 * @brief WeakNetMgr：网络接口列表构建与各项指标（RTT/RSSI/TCP丢包/抖动/流量）的线程安全刷新
 *
 * 模块职责：
 *   - 从 NetInterfaceManager 获取系统 Internet 接口列表
 *   - 使用 UsingInterfaceManager 标记"当前上网接口"（唯一事实源）
 *   - 为每个接口填充 RTT（通过 NetPing 主动探测）、Wi-Fi RSSI（通过 wpa_supplicant ctrl socket）、
 *     TCP 丢包率（netlink SOCK_DIAG 采样 tcp_info；eBPF 的 tcp_retrans 监控器是独立的
 *     连接级消费者，其输出不经本路径）、抖动（rtt_monitor 衍生）、流量统计（TrafficAnalyzer）
 *   - 线程安全：所有对 current_interfaces_ 的读写通过 std::mutex 保护（*Safe 系列方法）
 *
 * 依赖的外部接口：
 *   - **NetInterfaceManager (net_iface.h)**       获取系统网络接口列表
 *   - **UsingInterfaceManager (using_iface.h)**   判断当前哪个接口在上网（读取路由表）
 *   - **NetPing (net_ping.h)**                    ICMP RTT 主动探测
 *   - **WiFiRssiClient (net_wifiriss.h)**         通过 wpa_supplicant ctrl socket 获取 Wi-Fi RSSI
 *   - **TrafficAnalyzer (traffic_analyzer.hpp)** 流量分析器（bps/pps/flows/top flows/异常检测）
 *
 * 数据流向：
 *   collectCurrentInterfaces() → 构建初始 NetInfo 列表（含 usingNow 标记）
 *       ↓
 *   updateRttAndStateForIfaceSafe() ── rtt_monitor 锁外 ping 后的样本 → RTT
 *   updateWifiRssiSafe()     ── wpa ctrl socket → RSSI（仅 WiFi 接口）
 *   updateTcpLossRateSafe()  ── 外部 monitor 推送 → TCP 丢包率
 *   updateJitterSafe()       ── 外部 monitor 推送 → 抖动
 *   updateTrafficAnalysisSafe() ── TrafficAnalyzer → bps/pps/flows
 *       ↓
 *   NetworkQualityAssessor::assessQuality() → 综合评分
 */

#include "weak_netmgr.hpp"
#include "net_iface.h"
#include "using_iface.h"
#include "net_ping.h"
#include "net_wifiriss.h"
#include "traffic_analyzer.hpp"
#include "iface_type.hpp"
#include "logger.hpp"
#include <algorithm>
#include <chrono>
#include <sys/stat.h>

namespace weaknet_dbus {

static int64_t metricTimestampMs() {
    return std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
}

std::vector<NetInfo> WeakNetMgr::collectCurrentInterfaces() {
    LOG_INFO(LogModule::WEAK_MGR, "collectCurrentInterfaces begin");
    std::vector<NetInfo> result;
    auto mgr = NetInterfaceManager::getInstance();
    auto names = mgr->getInternetInterfaces();
    result.reserve(names.size());
    for (const auto& n : names) {
        NetInfo info(n);
        // 根据 sysfs wireless 标志识别 Wi-Fi，接口名前缀作为有线接口后备
        if (isWirelessInterface(n)) {
            info.setType(NetType::WiFi);
        } else if (n.rfind("eth", 0) == 0 || n.rfind("enp", 0) == 0) {
            info.setType(NetType::Ethernet);
        } else {
            info.setType(NetType::Unknown);
        }
        info.setDefaultRoute(false);
        info.setState(NetState::Up);
        info.setRttMs(-1);
        result.push_back(info);
    }
    // 标记当前上网网卡（using 标志）
    // 唯一事实源 = UsingInterfaceManager（启动后不重复调 start()）
    auto usingMgr = UsingInterfaceManager::getInstance();
    std::string usingIf = usingMgr->getCurrentInterface();
    for (auto& x : result) x.setUsingNow(!usingIf.empty() && x.ifName() == usingIf);
    LOG_INFO(LogModule::WEAK_MGR, "collectCurrentInterfaces end: " << result.size() << " ifaces, using=" << (usingIf.empty() ? "(none)" : usingIf));
    return result;
}
static LinkQuality classifyQualityFromRtt(int rttMs, int /*prevMs*/) {
    if (rttMs < 0) return LinkQuality::Bad;
    // 简单阈值，可按需调整
    if (rttMs <= 50) return LinkQuality::Good;
    if (rttMs <= 100) return LinkQuality::Fair;
    if (rttMs <= 200) return LinkQuality::Poor;
    return LinkQuality::Bad;
}

// 说明：这里原有两个函数 —— updateRttAndStateSafe() 与它独占的
// updateRttAndState() —— 已随 RTT 采集路径改造一并删除：
//   - updateRttAndStateSafe() 持 iface_mutex_ 期间对**每个**接口做 ICMP ping
//     （多接口 × timeout 可达数秒），期间 getCurrentInterfaces() 的所有读者
//     ——含 D-Bus 的 ListInterfaces / HealthCheck——全部被阻塞；
//   - RTT 更新现已改走 updateRttAndStateForIfaceSafe()：由 rtt_monitor 在
//     **锁外**完成 ping，再持锁写回单个接口（见 rtt_monitor.cpp）。
// 两者在改造后均无任何调用者，属于"锁内做 I/O"缺陷的遗留并行路径，
// 删除以免保留第二个 RTT 写入入口。

bool WeakNetMgr::updateWifiRssi(std::vector<NetInfo>& list, const std::string& ctrlDir) {
    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: starting, ctrlDir=" << ctrlDir << " size=" << list.size());
    auto client = WiFiRssiClient::getInstance();
    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: got client instance");
    bool anyChanged = false;
    for (auto& x : list) {
        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: processing interface " << x.ifName() << " type=" << static_cast<int>(x.type()));
        if (x.type() != NetType::WiFi) {
            LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: skipping non-WiFi interface " << x.ifName());
            continue;
        }
        // 若尚未连接，尝试连接 ctrl 套接字
        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: attempting to connect to " << x.ifName());
        if (!client->connect(x.ifName(), ctrlDir)) {
            LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: failed to connect to " << x.ifName());
            continue;
        }
        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: connected to " << x.ifName() << ", getting RSSI");
        RssiSample sample = readNl80211Rssi(x.ifName());
        if (!sample.valid) {
            int rssi = client->getRssi();
            if (rssi != -1000) {
                sample = {rssi, true, false, "wpa_supplicant"};
            } else {
                rssi = readProcWirelessRssi(x.ifName());
                if (rssi != -1000) sample = {rssi, true, true, "proc_net_wireless_quality"};
            }
        }
        const int rssi = sample.valid ? sample.dbm : -1000;
        if (sample.valid) {
            x.setRssiEstimated(sample.estimated);
            x.setRssiSource(sample.source);
            x.setRssiSampleTsMs(metricTimestampMs());
        }
        LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: got RSSI " << rssi << " for " << x.ifName());
        // 无效值仅表示本轮未测量，不覆盖已有有效 RSSI，避免瞬时控制通道/驱动异常污染快照。
        if (rssi == -1000) {
            LOG_WARNING(LogModule::RSSI, "RSSI unavailable for " << x.ifName() << "; retaining previous value");
            x.setRssiSampleTsMs(0);
            continue;
        }
        if (x.rssiDbm() != rssi || x.rssiSource() != sample.source || x.rssiEstimated() != sample.estimated) {
            x.setRssiDbm(rssi);
            x.setRssiSampleTsMs(metricTimestampMs());
            anyChanged = true;
            if (x.usingNow()) {
                LOG_INFO(LogModule::RSSI, "using iface " << x.ifName() << " RSSI=" << rssi << " dBm");
            }
            LOG_INFO(LogModule::WEAK_MGR, "iface=" << x.ifName() << " rssi=" << rssi);
        }
    }
    LOG_INFO(LogModule::WEAK_MGR, "updateWifiRssi: completed, anyChanged=" << anyChanged);
    return anyChanged;
}

bool WeakNetMgr::updateCurrentUsing(std::vector<NetInfo>& list, bool printLog, std::string* outIfName, uint32_t* outFlags) {
    auto usingMgr = UsingInterfaceManager::getInstance();
    std::string usingIf = usingMgr->getCurrentInterface();
    uint32_t flags = usingMgr->getMethodFlags();

    bool changed = false;
    LOG_INFO(LogModule::WEAK_MGR, "updateCurrentUsing: current=" << (usingIf.empty() ? "(none)" : usingIf) << " flags=" << flags);
    for (auto& x : list) {
        bool should = (!usingIf.empty() && x.ifName() == usingIf);
        if (x.usingNow() != should) { x.setUsingNow(should); changed = true; }
    }
    if (outIfName) *outIfName = usingIf;
    if (outFlags) *outFlags = flags;
    if (printLog) {
        if (!usingIf.empty()) {
            LOG_INFO(LogModule::INTERFACE, "current=" << usingIf << " flags=" << 
                ((flags & UsingMethodFlag::IPv4Default) ? "IPv4" : "") << 
                (((flags & UsingMethodFlag::IPv4Default) && (flags & UsingMethodFlag::IPv6Default)) ? "+" : 
                 ((flags & UsingMethodFlag::IPv6Default) ? "IPv6" : "")));
        } else {
            LOG_INFO(LogModule::INTERFACE, "current=(none)");
        }
    }
    return changed;
}

std::vector<std::string> WeakNetMgr::namesOf(const std::vector<NetInfo>& list) {
    std::vector<std::string> names;
    names.reserve(list.size());
    for (const auto& x : list) names.push_back(x.ifName());
    return names;
}

bool WeakNetMgr::updateTcpLossRate(std::vector<NetInfo>& list, 
                                  const std::string& iface_name, 
                                  double loss_rate, 
                                  const std::string& loss_level) {
    bool changed = false;
    LOG_INFO(LogModule::WEAK_MGR, "updateTcpLossRate: iface=" << iface_name << " rate=" << loss_rate << " level=" << loss_level);

    for (auto& x : list) {
        if (x.ifName() == iface_name) {
            const bool rateChanged = x.tcpLossRate() != loss_rate;
            const bool levelChanged = x.tcpLossLevel() != loss_level;
            x.setTcpLossRate(loss_rate);
            x.setTcpLossLevel(loss_level);
            // 时间戳表示最近一次成功采样，即使数值未变化也必须刷新。
            x.setTcpLossSampleTsMs(metricTimestampMs());
            if (rateChanged || levelChanged) {
                changed = true;
                if (x.usingNow()) {
                    LOG_INFO(LogModule::TCP_LOSS, "using iface " << iface_name << " TCP loss rate updated: " << loss_rate << "% (" << loss_level << ")");
                }
                LOG_INFO(LogModule::WEAK_MGR, "iface=" << x.ifName() << " tcp_loss_rate=" << x.tcpLossRate() << " tcp_loss_level=" << x.tcpLossLevel());
            }
            break;
        }
    }
    return changed;
}

bool WeakNetMgr::updateJitter(std::vector<NetInfo>& list,
                              const std::string& iface_name,
                              double jitter_ms,
                              const std::string& jitter_level) {
    bool changed = false;
    for (auto& x : list) {
        if (x.ifName() == iface_name) {
            const bool valueChanged = x.jitterMs() != jitter_ms;
            const bool levelChanged = x.jitterLevel() != jitter_level;
            x.setJitterMs(jitter_ms);
            x.setJitterLevel(jitter_level);
            // 时间戳表示最近一次成功采样，即使数值未变化也必须刷新。
            x.setJitterSampleTsMs(metricTimestampMs());
            if (valueChanged || levelChanged) {
                changed = true;
                if (x.usingNow()) {
                    LOG_INFO(LogModule::NETWORK, "using iface " << iface_name
                             << " jitter updated: " << jitter_ms << "ms (" << jitter_level << ")");
                }
            }
            break;
        }
    }
    return changed;
}

// 流量分析相关函数实现
void WeakNetMgr::startTrafficAnalysis(const std::string& interface, int interval_seconds,
                                      const weaknet::MapSizingPlan& plan) {
    if (!traffic_analyzer_) {
        traffic_analyzer_ = std::make_shared<TrafficAnalyzer>();
    }
    traffic_analyzer_->start(interface, interval_seconds, plan);
    if (traffic_analyzer_->isDegradedMode()) {
        LOG_WARNING(LogModule::WEAK_MGR, "Traffic analysis started in degraded mode for interface: " << interface);
    }
    LOG_INFO(LogModule::WEAK_MGR, "Started traffic analysis for interface: " << interface);
}

void WeakNetMgr::stopTrafficAnalysis() {
    if (traffic_analyzer_) {
        traffic_analyzer_->stop();
        LOG_INFO(LogModule::WEAK_MGR, "Stopped traffic analysis");
    }
}

bool WeakNetMgr::updateTrafficAnalysis(std::vector<NetInfo>& list) {
    if (!traffic_analyzer_ || !traffic_analyzer_->isRunning()) {
        return false;
    }

    bool changed = false;

    try {
        // 获取当前流量统计
        auto stats = traffic_analyzer_->getCurrentStats();

        // 获取Top流量连接
        auto topFlows = traffic_analyzer_->getTopFlows(5, 10);

        // 检测异常流量
        auto anomalies = traffic_analyzer_->detectAnomalies(5);

        // 更新当前上网网卡的流量信息
        for (auto& net : list) {
            if (net.usingNow()) {
                // 更新流量统计信息
                net.setTrafficStats(stats.totalBps, stats.totalPps, stats.activeFlows);
                net.setTrafficSampleTsMs(metricTimestampMs());

                // 如果有异常流量，记录日志
                if (!anomalies.empty()) {
                    LOG_INFO(LogModule::WEAK_MGR, "Traffic anomalies detected on " << net.ifName() 
                        << ": " << anomalies.size() << " anomalies");
                    for (const auto& anomaly : anomalies) {
                        LOG_INFO(LogModule::WEAK_MGR, "Anomaly: " << anomaly.anomalyType 
                            << " severity: " << (anomaly.severity * 100) << "%");
                    }
                }

                LOG_INFO(LogModule::WEAK_MGR, "Updated traffic stats for " << net.ifName() 
                    << ": " << (stats.totalBps / (1024*1024)) << " MB/s, " 
                    << stats.activeFlows << " flows, " << stats.totalPps << " pps");

                changed = true;
                break;
            }
        }

    } catch (const std::exception& e) {
        LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis update error: " << e.what());
    }

    return changed;
}

// 线程安全的接口列表操作方法实现
std::vector<NetInfo> WeakNetMgr::getCurrentInterfaces() const {
    std::lock_guard<std::mutex> lock(iface_mutex_);
    return current_interfaces_;
}

void WeakNetMgr::updateInterfaces(const std::vector<NetInfo>& new_interfaces) {
    std::lock_guard<std::mutex> lock(iface_mutex_);
    current_interfaces_ = new_interfaces;
    ++snapshot_generation_;
    const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
    LOG_INFO(LogModule::WEAK_MGR, "Updated interfaces list: " << current_interfaces_.size() << " interfaces");
}

bool WeakNetMgr::markMetricUnavailable(const std::string& metric) {
    std::lock_guard<std::mutex> lock(iface_mutex_);
    for (auto& iface : current_interfaces_) {
        if (metric == "rtt") iface.setRttMs(-1);
        else if (metric == "jitter") iface.setJitterMs(-1.0);
        else if (metric == "rssi") { iface.setRssiDbm(-1000); iface.setRssiEstimated(false); }
        else if (metric == "tcp_loss") iface.setTcpLossRate(-1.0);
        else if (metric == "traffic") iface.setTrafficStats(0, 0, 0);
        else return false;
    }
    ++snapshot_generation_;
    const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
    return true;
}

std::optional<std::string> WeakNetMgr::getCurrentUsingInterface() const {
    std::lock_guard<std::mutex> lock(iface_mutex_);
    for (const auto& iface : current_interfaces_) {
        if (iface.usingNow()) {
            return iface.ifName();
        }
    }
    // 无上行时如实返回 nullopt，**不再回退到 current_interfaces_[0]**。
    // 回退会凭空造出一个"正在上网"的网卡：启动早期或路由抖动期间，
    // 所有 SLE 结论、D-Bus 快照的 interface 字段与历史行都会被归到那张
    // 列表首位的网卡上，而设备和它毫无关系。调用方必须显式处理"无上行"。
    return std::nullopt;
}

bool WeakNetMgr::updateRttAndStateForIfaceSafe(const std::string& iface_name, int rtt_ms) {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateRttAndStateForIfaceSafe: acquiring lock, iface=" << iface_name << " rtt=" << rtt_ms);
    bool result = false;
    int rtt_for_publish = rtt_ms;
    {
        std::lock_guard<std::mutex> lock(iface_mutex_);
        for (auto& x : current_interfaces_) {
            if (x.ifName() != iface_name) continue;
            int prev = x.rttMs();
            const bool rttChanged = x.rttMs() != rtt_ms;
            x.setPrevRttMs(prev);
            x.setRttMs(rtt_ms);
            if (rttChanged) { result = true; }
            x.setRttSampleTsMs(metricTimestampMs());
            LinkQuality q = classifyQualityFromRtt(rtt_ms, prev);
            if (x.quality() != q) { x.setQuality(q); result = true; }
            NetState ns = (rtt_ms >= 0) ? NetState::Up : NetState::Down;
            if (x.state() != ns) { x.setState(ns); result = true; }
            if (result) {
                ++snapshot_generation_;
                const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::system_clock::now().time_since_epoch()).count();
                x.markMetricUpdated(snapshot_generation_, now);
            }
            break;
        }
    }

    // MR-2 铁律：必须在释放 iface_mutex_ 后再向 MetricsRegistry 发布
    if (metrics_registry_) {
        if (rtt_for_publish >= 0) {
            metrics_registry_->publish(iface_name, weaknet::MetricId::RTT_MS, weaknet::MetricSample::valid(rtt_for_publish));
            metrics_registry_->publish(iface_name, weaknet::MetricId::REACHABILITY_SUCCESS, weaknet::MetricSample::valid(1.0));
        } else {
            metrics_registry_->publish(iface_name, weaknet::MetricId::REACHABILITY_SUCCESS, weaknet::MetricSample::valid(0.0));
        }
    }
    return result;
}

bool WeakNetMgr::updateWifiRssiSafe(const std::string& ctrlDir) {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: acquiring lock");
    std::vector<std::pair<std::string, int>> rssi_snapshots;
    bool result = false;
    {
        std::lock_guard<std::mutex> lock(iface_mutex_);
        LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: lock acquired, calling updateWifiRssi");
        result = updateWifiRssi(current_interfaces_, ctrlDir);
        if (result) ++snapshot_generation_;
        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        if (result) {
            for (auto& iface : current_interfaces_) {
                iface.markMetricUpdated(snapshot_generation_, now);
                rssi_snapshots.emplace_back(iface.ifName(), iface.rssiDbm());
            }
        }
        LOG_DEBUG(LogModule::WEAK_MGR, "updateWifiRssiSafe: updateWifiRssi completed, releasing lock");
    }

    // MR-2: 锁外发布
    if (metrics_registry_ && result) {
        for (const auto& item : rssi_snapshots) {
            if (item.second > -1000) {
                metrics_registry_->publish(item.first, weaknet::MetricId::RSSI_DBM, weaknet::MetricSample::valid(item.second));
            }
        }
    }
    return result;
}

bool WeakNetMgr::updateTcpLossRateSafe(const std::string& iface_name, double loss_rate, const std::string& loss_level) {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateTcpLossRateSafe: acquiring lock");
    bool result = false;
    {
        std::lock_guard<std::mutex> lock(iface_mutex_);
        LOG_DEBUG(LogModule::WEAK_MGR, "updateTcpLossRateSafe: lock acquired, calling updateTcpLossRate");
        result = updateTcpLossRate(current_interfaces_, iface_name, loss_rate, loss_level);
        if (result) ++snapshot_generation_;
        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        if (result) for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
        LOG_DEBUG(LogModule::WEAK_MGR, "updateTcpLossRateSafe: updateTcpLossRate completed, releasing lock");
    }

    // MR-2: 锁外发布
    if (metrics_registry_ && result) {
        metrics_registry_->publish(iface_name, weaknet::MetricId::TCP_LOSS_RATE, weaknet::MetricSample::valid(loss_rate));
    }
    return result;
}

bool WeakNetMgr::updateJitterSafe(const std::string& iface_name, double jitter_ms, const std::string& jitter_level) {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateJitterSafe: acquiring lock");
    bool result = false;
    {
        std::lock_guard<std::mutex> lock(iface_mutex_);
        LOG_DEBUG(LogModule::WEAK_MGR, "updateJitterSafe: lock acquired, calling updateJitter");
        result = updateJitter(current_interfaces_, iface_name, jitter_ms, jitter_level);
        if (result) ++snapshot_generation_;
        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        if (result) for (auto& iface : current_interfaces_) iface.markMetricUpdated(snapshot_generation_, now);
        LOG_DEBUG(LogModule::WEAK_MGR, "updateJitterSafe: updateJitter completed, releasing lock");
    }

    // MR-2: 锁外发布
    if (metrics_registry_ && result) {
        metrics_registry_->publish(iface_name, weaknet::MetricId::JITTER_MS, weaknet::MetricSample::valid(jitter_ms));
    }
    return result;
}

bool WeakNetMgr::updateTrafficAnalysisSafe() {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: acquiring lock");

    // 先在锁外获取流量统计（避免长时间阻塞）
    NetTrafficAnalyzer::RealTimeStats stats;
    std::vector<FlowRate> topFlows;
    std::vector<TrafficAnomaly> anomalies;
    bool hasStats = false;

    if (traffic_analyzer_ && traffic_analyzer_->isRunning()) {
        try {
            stats = traffic_analyzer_->getCurrentStats();
            hasStats = true;
            // 注意：getTopFlows 和 detectAnomalies 会阻塞，但在锁外执行
            topFlows = traffic_analyzer_->getTopFlows(5, 10);
            anomalies = traffic_analyzer_->detectAnomalies(5);
        } catch (const std::exception& e) {
            LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis data fetch error: " << e.what());
        }
    }

    // 然后在锁内更新接口列表（快速操作）
    std::lock_guard<std::mutex> lock(iface_mutex_);
    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: lock acquired, updating interfaces");

    bool changed = false;
    if (hasStats) {
        // 归因必须用分析器**实际绑定**的网卡，而不是"当前恰好是上行"的网卡。
        // 分析器在启动时绑定一次（TrafficAnalyzer::start 的 running_ 守卫使重绑定
        // 需要拆建 BPF，不在本函数职责内），此后一直采样那一张网卡。若按
        // usingNow() 归因，上行从 wlan0 切到 eth0 后，wlan0 的采样值会被写到
        // eth0 上——history.db 里 eth0 出现凭空捏造的流量，而 wlan0 的真实流量
        // 消失，且没有任何日志能暴露这个错位。
        const std::string bound_iface = traffic_analyzer_->boundInterface();
        for (auto& net : current_interfaces_) {
            if (net.ifName() != bound_iface) continue;

            net.setTrafficStats(stats.totalBps, stats.totalPps, stats.activeFlows);
            net.setTrafficSampleTsMs(metricTimestampMs());

            if (!anomalies.empty()) {
                LOG_INFO(LogModule::WEAK_MGR, "Traffic anomalies detected on " << net.ifName()
                    << ": " << anomalies.size() << " anomalies");
                for (const auto& anomaly : anomalies) {
                    LOG_INFO(LogModule::WEAK_MGR, "Anomaly: " << anomaly.anomalyType
                        << " severity: " << (anomaly.severity * 100) << "%");
                }
            }

            LOG_INFO(LogModule::WEAK_MGR, "Updated traffic stats for " << net.ifName()
                << ": " << (stats.totalBps / (1024*1024)) << " MB/s, "
                << stats.activeFlows << " flows, " << stats.totalPps << " pps");

            changed = true;
            break;
        }
    }

    LOG_DEBUG(LogModule::WEAK_MGR, "updateTrafficAnalysisSafe: completed, releasing lock");
    return changed;
}

bool WeakNetMgr::updateCurrentUsingSafe() {
    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: acquiring lock");
    std::lock_guard<std::mutex> lock(iface_mutex_);
    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: lock acquired, calling updateCurrentUsing");
    bool result = updateCurrentUsing(current_interfaces_, true);
    // 上行网卡切换同样是"快照内容变了"，必须推进代次并刷新各接口的
    // markMetricUpdated。此前这里漏了，导致切换前后 history.db 里两条
    // 记录可能携带相同的 generation/last_updated_ms，而它们描述的却是
    // 不同的活动网卡，削弱了采样一致性元数据的可信度。
    if (result) {
        ++snapshot_generation_;
        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        for (auto& iface : current_interfaces_) {
            iface.markMetricUpdated(snapshot_generation_, now);
        }
    }
    LOG_DEBUG(LogModule::WEAK_MGR, "updateCurrentUsingSafe: updateCurrentUsing completed, releasing lock");
    return result;
}

