30	HciConnectionKey BtHciConnectionTracker::onConnectionEstablished(
31	    const std::string& controller,
32	    uint16_t handle,
33	    const std::string& mac,
34	    const std::string& addr_type) {
35	
36	    uint16_t valid_handle = handle & 0x0FFF;
37	    std::string slot_key = makeSlotKey(controller, valid_handle);
38	    std::string clean_mac = normalizeMac(mac);
39	
40	    std::lock_guard<std::mutex> lock(mutex_);
41	
42	    auto it = active_map_.find(slot_key);
43	    if (it != active_map_.end() && it->second.is_active) {
44	        // 重复通知幂等处理：若 MAC 一致，直接复用当前代次
45	        if (!clean_mac.empty() && it->second.device_mac == clean_mac) {
46	            return it->second.key;
47	        }
48	        // 若 MAC 发生冲突或前连接未正常收到 disconnect，强制递增代次
49	        it->second.is_active = false;
50	        it->second.disconnected_at = std::chrono::steady_clock::now();
51	    }
52	
53	    uint32_t next_gen = ++generation_counter_[slot_key];
54	
55	    HciConnectionKey key{controller, valid_handle, next_gen};
56	    HciConnectionRecord record;
57	    record.key = key;
58	    record.device_mac = clean_mac;
59	    record.address_type = addr_type.empty() ? "UNKNOWN" : addr_type;
60	    record.attribution_scope = clean_mac.empty() ? "controller" : "device";
61	    record.connected_at = std::chrono::steady_clock::now();
62	    record.is_active = true;
63	
64	    active_map_[slot_key] = record;
65	    return key;
66	}
