74	    std::lock_guard<std::mutex> lock(mutex_);
75	    auto it = active_map_.find(slot_key);
76	    if (it == active_map_.end() || !it->second.is_active) {
77	        return false;
78	    }
79	
80	    it->second.is_active = false;
81	    it->second.disconnected_at = std::chrono::steady_clock::now();
82	    return true;
83	}
84	
85	std::optional<HciConnectionRecord> BtHciConnectionTracker::getActiveConnection(
86	    const std::string& controller, uint16_t handle) const {
87	
88	    uint16_t valid_handle = handle & 0x0FFF;
89	    std::string slot_key = makeSlotKey(controller, valid_handle);
90	
91	    std::lock_guard<std::mutex> lock(mutex_);
92	    auto it = active_map_.find(slot_key);
93	    if (it != active_map_.end() && it->second.is_active) {
94	        return it->second;
95	    }
96	    return std::nullopt;
97	}
98	
99	std::vector<HciConnectionRecord> BtHciConnectionTracker::getActiveConnections(
100	    const std::string& controller) const {
101	
102	    std::lock_guard<std::mutex> lock(mutex_);
103	    std::vector<HciConnectionRecord> res;
104	    for (const auto& [k, v] : active_map_) {
105	        if (v.is_active && v.key.controller_id == controller) {
106	            res.push_back(v);
107	        }
108	    }
109	    return res;
110	}
111	
112	void BtHciConnectionTracker::resetController(const std::string& controller) {
113	    std::lock_guard<std::mutex> lock(mutex_);
114	    auto now = std::chrono::steady_clock::now();
115	    for (auto& [k, v] : active_map_) {
116	        if (v.key.controller_id == controller && v.is_active) {
117	            v.is_active = false;
118	            v.disconnected_at = now;
119	            // 控制器复位时提前递增代次计数，避免硬件重启后立即重分配同句柄造成串号
120	            generation_counter_[k]++;
121	        }
122	    }
123	}
