125	size_t BtHciConnectionTracker::syncFromKernel(const std::string& controller) {
126	    // 1. 打开 HCI 控制套接字 (AF_BLUETOOTH, SOCK_RAW, BTPROTO_HCI)
127	    #ifndef AF_BLUETOOTH
128	    #define AF_BLUETOOTH 31
129	    #endif
130	    #ifndef BTPROTO_HCI
131	    #define BTPROTO_HCI 1
132	    #endif
133	    #ifndef HCIGETCONNLIST
134	    // _IOR('H', 212, int) = 0x800448d4
135	    #define HCIGETCONNLIST 0x800448d4
136	    #endif
137	
138	    int sock = ::socket(AF_BLUETOOTH, SOCK_RAW | SOCK_CLOEXEC, BTPROTO_HCI);
139	    if (sock < 0) {
140	        return activeCount();
141	    }
142	
143	    // 解析 controller 编号，如 "hci0" -> 0
144	    uint16_t dev_id = 0;
145	    if (controller.rfind("hci", 0) == 0 && controller.size() > 3) {
146	        try {
147	            dev_id = static_cast<uint16_t>(std::stoi(controller.substr(3)));
148	        } catch (...) {
149	            dev_id = 0;
150	        }
151	    }
152	
153	    // 内存缓冲区：头部 4 字节 (dev_id + conn_num) + 最多 64 条 struct hci_conn_info (每条 16 字节)
154	    struct RawHciConnInfo {
155	        uint16_t handle;
156	        uint8_t bdaddr[6];
157	        uint8_t type;
158	        uint8_t out;
159	        uint16_t state;
160	        uint32_t link_mode;
161	    } __attribute__((packed));
162	
163	    uint8_t buf[4 + 64 * sizeof(RawHciConnInfo)] = {0};
164	    *reinterpret_cast<uint16_t*>(buf) = dev_id;
165	    *reinterpret_cast<uint16_t*>(buf + 2) = 64; // 最多获取 64 个连接
166	
167	    int ret = ::ioctl(sock, HCIGETCONNLIST, buf);
168	    ::close(sock);
169	
170	    if (ret < 0) {
171	        return activeCount();
172	    }
173	
174	    uint16_t conn_num = *reinterpret_cast<uint16_t*>(buf + 2);
175	    if (conn_num > 64) conn_num = 64;
176	
177	    std::set<uint16_t> live_handles;
178	    const RawHciConnInfo* conns = reinterpret_cast<const RawHciConnInfo*>(buf + 4);
179	
180	    for (uint16_t i = 0; i < conn_num; ++i) {
181	        uint16_t handle = conns[i].handle & 0x0FFF;
182	
183	        // 过滤未建立链路：内核 conn list 会包含 BT_CONNECT（page 进行中）的
184	        // 半开连接，其 handle 恒为 0（Connection Complete 之前控制器还没分配）。
185	        // 板端实测：一次失败的 l2ping page 就会留下 handle=0 的记录，被当作
186	        // 活跃连接后 STALL 规则会对"从未连上"的设备持续误报（与 bt_events BPF
187	        // 对 handle=0 的过滤同理——理论边界是句柄 0 合法，但控制器实际分配
188	        // 几乎总是从非 0 开始，过滤海量失败尝试是净收益）。
189	        // 注意：跳过的 handle=0 不进 live_handles，若曾有残留记录会被下方清理。
190	        if (handle == 0) continue;
191	        live_handles.insert(handle);
192	
193	        // 内核 bdaddr 反序存储 (b[0] 为低位)
194	        char mac_buf[18];
195	        snprintf(mac_buf, sizeof(mac_buf), "%02X:%02X:%02X:%02X:%02X:%02X",
