200	        std::string addr_type = (conns[i].type == 0x80) ? "LE" : "BREDR";
201	
202	        // 更新/建立真实连接
203	        onConnectionEstablished(controller, handle, mac, addr_type);
204	    }
205	
206	    // 检查并清理已被内核销毁但尚未收到事件的句柄
207	    std::vector<HciConnectionRecord> current_actives = getActiveConnections(controller);
208	    for (const auto& rec : current_actives) {
209	        if (live_handles.find(rec.key.handle) == live_handles.end()) {
210	            onConnectionDisconnected(controller, rec.key.handle);
211	        }
212	    }
213	
214	    return activeCount();
215	}
