1	/**
2	 * @file bt_event_normalizer.cpp
3	 * @brief 蓝牙原始观测归一化器实现
4	 *
5	 * 核心不变式（修改本文件前必须读懂）：
6	 *   - 每个 kprobe 只产生 RawBtObservation，绝不产生 WirelessDeviceEvent
7	 *   - 合并键含 gateway_id / hci_index / address_type，同 MAC 跨控制器不合并
8	 *   - 窗口外不合并：两次真实断连必须产生两个 canonical 事件
9	 *   - 原因定案遵循优先级（mgmt raw > 其余 raw > supplemental hint > Unknown），
10	 *     但所有观测一律进入 raw_evidence，优先级不覆盖原始事实
11	 *   - reason 的归一化按**来源域**选择映射：mgmt 来源用 MGMT_DEV_DISCONN_* 枚举，
12	 *     其余来源用 HCI error code；两域取值空间不同不可互套
13	 *   - 不产出 suspected_cause（那是诊断器的职责）
14	 */
15	
16	#include "bt_event_normalizer.hpp"
17	
18	#include <algorithm>
19	#include <iomanip>
20	#include <random>
21	#include <sstream>
22	#include <tuple>
23	
24	namespace weaknet_dbus {
25	
26	// ============================================================================
27	// MergeKey
28	// ============================================================================
29	
30	bool BtEventNormalizer::MergeKey::operator<(const MergeKey& other) const {
31	    // 逐字段字典序比较，等价于对五元组做全序排序。
32	    // 用 std::tie 而非手写嵌套 if，避免遗漏字段导致"看起来不同的事件被合并"。
33	    return std::tie(gateway_id, hci_index, address_type, device_address, event_type) <
34	           std::tie(other.gateway_id, other.hci_index, other.address_type,
35	                    other.device_address, other.event_type);
36	}
37	
38	// ============================================================================
39	// 构造 / 诊断
40	// ============================================================================
41	
42	BtEventNormalizer::BtEventNormalizer(BtNormalizerConfig cfg) : cfg_(std::move(cfg)) {
43	    // 每实例一个随机短码（8 个 hex 字符）。不同进程/不同重启之间碰撞概率
44	    // 极低，配合 seq 即可保证 event_id 跨重启唯一（见头文件成员注释）。
45	    std::random_device rd;
46	    std::mt19937_64 gen(rd());
47	    std::uniform_int_distribution<uint64_t> dis;
48	    std::ostringstream nonce;
49	    nonce << std::hex << std::setfill('0') << std::setw(8)
50	          << (dis(gen) & 0xFFFFFFFFULL);
51	    instance_nonce_ = nonce.str();
52	}
53	
54	size_t BtEventNormalizer::pendingCount() const {
55	    std::lock_guard<std::mutex> lock(mu_);
56	    return pending_.size();
57	}
58	
59	uint64_t BtEventNormalizer::normalizedCount() const {
60	    std::lock_guard<std::mutex> lock(mu_);
61	    return normalized_total_;
62	}
63	
64	void BtEventNormalizer::reset() {
65	    std::lock_guard<std::mutex> lock(mu_);
66	    pending_.clear();
67	    seq_ = 0;
68	    normalized_total_ = 0;
69	}
70	
71	// ============================================================================
72	// 投递观测
73	// ============================================================================
74	
75	BtEventNormalizer::MergeKey BtEventNormalizer::makeKey(const RawBtObservation& obs) {
76	    MergeKey key;
77	    key.gateway_id = obs.gateway_id;
78	    key.hci_index = obs.hci_index;
79	    key.address_type = obs.address_type;
80	    key.device_address = obs.device_address;
81	    key.event_type = obs.event_type;
82	    return key;
83	}
84	
85	void BtEventNormalizer::submit(const RawBtObservation& obs) {
86	    std::lock_guard<std::mutex> lock(mu_);
87	
88	    const MergeKey key = makeKey(obs);
89	    auto it = pending_.find(key);
90	
91	    // 已存在 pending 且仍在合并窗口内 -> 归入同一 canonical 事件
92	    if (it != pending_.end() &&
93	        obs.timestamp_ms <= it->second.last_obs_ms + cfg_.merge_window_ms) {
94	        applyObservation(it->second, obs);
95	        return;
96	    }
97	
98	    // 窗口外（或首次）-> 定案旧事件，另开新的
99	    //
100	    // 注意：这里刻意不把旧事件立即返回给调用方，而是留在 pending_ 里等
101	    // flushExpired() 统一取走——submit 的语义是"吸收观测"，不是"产出事件"。
102	    // 但旧事件若非空，必须先落定，否则同键的两条记录会互相覆盖。
103	    if (it != pending_.end()) {
104	        // 旧事件已过窗口：标记为可刷出。这里把它移到 completed_ 队列。
105	        completed_.push_back(finalize(it->second, seq_++));
106	        pending_.erase(it);
107	    }
108	
109	    // 建立新 pending
110	    PendingEvent pending;
111	    pending.event.site_id = obs.gateway_id.empty() ? "" : "";  // site 由 Store 层补齐
112	    pending.event.gateway_id = obs.gateway_id;
113	    pending.event.hci_index = obs.hci_index;
114	    pending.event.protocol = WirelessProtocol::Bluetooth;
115	    pending.event.device_address = obs.device_address;
116	    pending.event.address_type = obs.address_type;
117	    pending.event.event_type = obs.event_type;
118	    pending.event.timestamp_ms = obs.timestamp_ms;
119	    applyObservation(pending, obs);
120	
121	    // 容量保护：超过上限时强制定案最老的一条，防止内存无界增长
122	    if (pending_.size() >= cfg_.max_pending) {
123	        auto oldest = pending_.begin();
124	        for (auto i = pending_.begin(); i != pending_.end(); ++i) {
125	            if (i->second.last_obs_ms < oldest->second.last_obs_ms) oldest = i;
126	        }
127	        completed_.push_back(finalize(oldest->second, seq_++));
128	        pending_.erase(oldest);
129	    }
130	
131	    pending_.emplace(makeKey(obs), std::move(pending));
132	}
133	
134	// ============================================================================
135	// 原因定案优先级
136	// ============================================================================
137	
138	int BtEventNormalizer::reasonRank(const RawBtObservation& obs) {
139	    // mgmt 层的原始码（MGMT_DEV_DISCONN_* 域）—— 最权威的事实来源
140	    if (obs.raw_reason_code.has_value() && obs.source == EvidenceSource::KernelMgmt) {
141	        return 3;
142	    }
143	    // 其余来源携带的原始码（HCI error 域，如 hci_disconnect 的 reason）
144	    // 原始码是事实，必须排在推断 hint 之上——否则先到的 raw 会被后到的 hint 覆盖
145	    if (obs.raw_reason_code.has_value()) {
146	        return 2;
147	    }
148	    // supplemental hook 带来归一化原因（如 hci_conn_timeout -> ConnectionTimeout）
149	    if (obs.reason_hint != DisconnectReason::Unknown) {
150	        return 1;
151	    }
152	    return 0;
153	}
154	
155	// ============================================================================
156	// 观测 -> pending 事件
157	// ============================================================================
158	
159	void BtEventNormalizer::applyObservation(PendingEvent& pending, const RawBtObservation& obs) {
160	    // 事件时间为窗口中**最早**一条观测的时刻：现实故障发生在最早观测到的那一刻，
161	    // 而不是最后一条证据到达的时刻。
162	    if (pending.evidence.empty() || obs.timestamp_ms < pending.event.timestamp_ms) {
163	        pending.event.timestamp_ms = obs.timestamp_ms;
164	        pending.event.monotonic_ns = obs.monotonic_ns;
165	    }
166	    if (obs.timestamp_ms > pending.last_obs_ms) {
167	        pending.last_obs_ms = obs.timestamp_ms;
168	    }
169	
170	    // RSSI：只取第一个有值的观测。断连瞬间的链路质量比最后一条证据更有诊断价值。
171	    if (!pending.event.rssi_at_event_dbm.has_value() && obs.rssi_dbm.has_value()) {
172	        pending.event.rssi_at_event_dbm = obs.rssi_dbm;
173	    }
174	
175	    // 原因定案：仅当本条观测的优先级严格高于当前定案时才覆盖。
176	    // 这保证 mgmt 的原始 reason 不会被后到的 supplemental hint 冲掉。
177	    const int rank = reasonRank(obs);
178	    if (rank > pending.reason_rank) {
179	        pending.reason_rank = rank;
180	        pending.event.source = obs.source;
181	        pending.event.source_detail = obs.source_detail;
182	        if (obs.raw_reason_code.has_value()) {
183	            // 原始 code 无损保存，归一化解释由**按来源域**的映射函数给出：
184	            //   KernelMgmt -> MGMT_DEV_DISCONN_*（内核 mgmt 枚举，非 HCI error）
185	            //   其余       -> HCI error code
186	            // 两个域的取值空间完全不同（如 0x02 在 mgmt 域=本地断开，
187	            // 在 HCI 域=Unknown Connection Identifier），混用会得出错误原因。
188	            pending.event.raw_reason_code = *obs.raw_reason_code;
189	            pending.event.reason =
190	                (obs.source == EvidenceSource::KernelMgmt)
191	                    ? disconnectReasonFromMgmtCode(*obs.raw_reason_code)
192	                    : disconnectReasonFromHciCode(*obs.raw_reason_code);
193	        } else if (obs.reason_hint != DisconnectReason::Unknown) {
194	            // 该来源没有原始 code（如 hci_conn_timeout），只用它的归一化结论
195	            pending.event.reason = obs.reason_hint;
196	        }
197	    }
198	
199	    // 无条件追加原始证据：优先级只影响 canonical 字段，不影响证据留存
200	    pending.evidence.push_back(obs);
201	}
202	
203	// ============================================================================
204	// 定案
205	// ============================================================================
206	
207	WirelessDeviceEvent BtEventNormalizer::finalize(PendingEvent& pending, uint64_t seq) {
208	    WirelessDeviceEvent ev = pending.event;
209	
210	    // event_id = <prefix>_<实例随机码>_<seq>：进程内单调、跨进程（服务重启）不碰撞。
211	    // device_events.event_id 是 UNIQUE 且 INSERT OR IGNORE——跨重启重复即静默丢事件，
212	    // 所以唯一性必须在生成方保证（早期版本只有 prefix+seq，重启后必撞，已修）。
213	    std::ostringstream id;
214	    id << cfg_.event_id_prefix << "_" << instance_nonce_ << "_" << seq;
215	    ev.event_id = id.str();
216	
217	    // 拼接 raw_evidence 数组
218	    std::string details;
219	    for (const auto& obs : pending.evidence) {
220	        details = appendRawEvidence(details, obs);
221	    }
222	    ev.details_json = details;
223	
224	    // 采集层不做诊断：suspected_cause 恒为空，
225	    // 由 Phase 2/3 的 LinkAnomalyDetector / SiteIncidentCorrelator 填充。
226	    ev.suspected_cause = std::nullopt;
227	
228	    ++normalized_total_;
229	    return ev;
230	}
231	
232	// ============================================================================
233	// 刷出
234	// ============================================================================
235	
236	std::vector<WirelessDeviceEvent> BtEventNormalizer::flushExpired(uint64_t now_ms) {
237	    std::lock_guard<std::mutex> lock(mu_);
238	
239	    std::vector<WirelessDeviceEvent> out = std::move(completed_);
240	    completed_.clear();
241	
242	    for (auto it = pending_.begin(); it != pending_.end();) {
243	        if (now_ms > it->second.last_obs_ms + cfg_.merge_window_ms) {
244	            out.push_back(finalize(it->second, seq_++));
245	            it = pending_.erase(it);
246	        } else {
247	            ++it;
248	        }
249	    }
250	    return out;
251	}
252	
253	std::vector<WirelessDeviceEvent> BtEventNormalizer::flushAll() {
254	    std::lock_guard<std::mutex> lock(mu_);
255	
256	    std::vector<WirelessDeviceEvent> out = std::move(completed_);
257	    completed_.clear();
258	
259	    for (auto& kv : pending_) {
260	        out.push_back(finalize(kv.second, seq_++));
261	    }
262	    pending_.clear();
263	    return out;
264	}
265	
266	}  // namespace weaknet_dbus
