1	/**
2	 * @file wireless_event_store.cpp
3	 * @brief 规范化无线设备事件存储实现
4	 */
5	
6	#include "wireless_event_store.hpp"
7	
8	#include <algorithm>
9	
10	#include "database_manager.hpp"
11	#include "logger.hpp"
12	#include "site_incident_correlator.hpp"
13	
14	namespace weaknet_dbus {
15	
16	WirelessEventStore::WirelessEventStore(DatabaseManager* db, WirelessEventStoreConfig cfg)
17	    : db_(db), cfg_(std::move(cfg)) {
18	    // 环形缓冲按容量预留，避免运行期反复扩容
19	    (void)0;
20	}
21	
22	bool WirelessEventStore::recordEvent(const WirelessDeviceEvent& event) {
23	    // 待投递给关联器的事件快照。**必须在锁内拷贝**：调用方可能在栈上复用
24	    // 同一个 event 对象，锁外再引用它就成了悬垂读（这不是假设——单元测试与
25	    // 消费循环都会循环复用同一个变量）。
26	    std::optional<WirelessDeviceEvent> to_observe;
27	
28	    {
29	        std::lock_guard<std::mutex> lock(mu_);
30	
31	        // 补齐来源身份：Phase 1 运行模型是"1 Gateway = 1 Site"，
32	        // 事件若未自带 site_id/gateway_id（如来自测试或未来的其它生产者），
33	        // 用 store 配置兜底，保证落库行永远可回答"这个事件是哪台探针看到的"。
34	        WirelessDeviceEvent ev = event;
35	        if (ev.gateway_id.empty()) ev.gateway_id = cfg_.gateway_id;
36	        if (ev.site_id.empty()) {
37	            ev.site_id = cfg_.site_id.empty() ? ev.gateway_id : cfg_.site_id;
38	        }
39	
40	        ring_.push_back(ev);
41	        while (ring_.size() > cfg_.ring_capacity) {
42	            ring_.pop_front();
43	        }
44	        ++total_recorded_;
45	
46	        // 只有真的落库成功的事件才参与区域关联：关联窗口的证据回链要求
47	        // site_incident_events 能 JOIN 到 device_events 行，未落库的事件
48	        // 关联出来的 incident 查不出设备清单。db_ 为空（纯内存模式）时同样跳过。
49	        bool persist_ok = false;
50	        if (db_) {
51	            persist_ok = db_->insertDeviceEvent(
52	                ev.event_id,
53	                static_cast<int64_t>(ev.timestamp_ms),
54	                ev.site_id,
55	                ev.gateway_id,
56	                toString(ev.protocol),
57	                ev.device_address,
58	                toString(ev.address_type),
59	                ev.hci_index,
60	                toString(ev.event_type),
61	                ev.rssi_at_event_dbm,
62	                ev.raw_reason_code,
63	                toString(ev.reason),
64	                toString(ev.source),
65	                ev.source_detail,
66	                ev.suspected_cause,
67	                ev.details_json);
68	            if (!persist_ok) {
69	                ++persist_failures_;
70	                LOG_WARNING(LogModule::BLUETOOTH,
71	                            "WirelessEventStore: failed to persist event " << ev.event_id
72	                            << " (device=" << ev.device_address
73	                            << ", type=" << toString(ev.event_type) << ")");
74	            }
75	        }
76	
77	        // Phase 3a：把同一条事件投递给区域级关联器，产出/推进 SiteIncident。
78	        // 关联发生在**落库之后**：即使关联器失败，设备事件这一**事实**已经持久化。
79	        if (correlator_ && persist_ok) {
80	            to_observe = std::move(ev);
81	        }
82	    }
83	
84	    // 关联调用刻意放在锁外：correlator 有独立 mutex_，且会去拿
85	    // DatabaseManager::mutex_。在持有 mu_ 时调用就形成
86	    // store.mu_ -> correlator.mutex_ -> db.mutex_ 的三段嵌套，
87	    // 一旦任何一处反向加锁即死锁。
88	    if (to_observe.has_value()) {
89	        correlator_->observe(*to_observe);
90	    }
91	
92	    return true;
93	}
94	
95	void WirelessEventStore::setIncidentCorrelator(SiteIncidentCorrelator* correlator) {
96	    std::lock_guard<std::mutex> lock(mu_);
97	    correlator_ = correlator;
98	}
99	
100	size_t WirelessEventStore::tickIncidents(uint64_t now_ms) {
101	    // 关联器指针只在插件 start/stop 时变更，且 stop 会先停消费线程，
102	    // 因此这里不加锁读取是安全的（与 queryPersisted 同一纪律：不制造
103	    // store 锁 -> 关联器锁的嵌套）。
104	    if (!correlator_) return 0;
105	    return correlator_->tick(now_ms).size();
106	}
107	
108	std::string WirelessEventStore::querySiteIncidents(const std::string& state,
109	                                                   int64_t start_ms,
110	                                                   int64_t end_ms,
111	                                                   int limit) const {
112	    if (!correlator_) return "[]";
113	    return correlator_->queryPersisted(state, start_ms, end_ms, limit, true);
114	}
115	
116	std::vector<WirelessDeviceEvent> WirelessEventStore::recentEvents(
117	    const std::string& device_address, size_t limit) const {
118	    std::lock_guard<std::mutex> lock(mu_);
119	
120	    std::vector<WirelessDeviceEvent> out;
121	    if (limit == 0) return out;
122	
123	    // ring_ 是时间正序，这里倒序遍历以获得"最近优先"
124	    for (auto it = ring_.rbegin(); it != ring_.rend(); ++it) {
125	        if (!device_address.empty() && it->device_address != device_address) continue;
126	        out.push_back(*it);
127	        if (out.size() >= limit) break;
128	    }
129	    return out;
130	}
131	
132	uint64_t WirelessEventStore::totalRecorded() const {
133	    std::lock_guard<std::mutex> lock(mu_);
134	    return total_recorded_;
135	}
136	
137	uint64_t WirelessEventStore::persistFailures() const {
138	    std::lock_guard<std::mutex> lock(mu_);
139	    return persist_failures_;
140	}
141	
142	std::string WirelessEventStore::queryPersisted(const std::string& device_address,
143	                                               const std::string& event_type,
144	                                               int64_t start_ms,
145	                                               int64_t end_ms,
146	                                               int limit) const {
147	    if (!db_) return "[]";
