1	/**
2	 * @file bt_event_monitor.cpp
3	 * @brief 蓝牙设备事件采集器实现
4	 *
5	 * 见头文件的设计说明。本文件的关键实现点：
6	 *   - 逐个 hook 独立挂载、独立降级（attachOne 失败只记状态不中止）
7	 *   - ringbuf 消费线程用 ring_buffer__poll(200ms) 便于及时响应 stop_
8	 *   - 内核观测 -> RawBtObservation 的转换集中在一处，便于核对字段语义
9	 *   - 不在此层做任何原因推断或事件合并（那是 normalizer 的职责）
10	 */
11	
12	#include "bt_event_monitor.hpp"
13	#include "bt_link_quality_tracker.hpp"
14	
15	#include <bpf/bpf.h>
16	#include <bpf/libbpf.h>
17	
18	#include <cerrno>
19	#include <chrono>
20	#include <cstring>
21	#include <sstream>
22	
23	#include "logger.hpp"
24	
25	namespace weaknet_dbus {
26	
27	namespace {
28	
29	/// 内核枚举 -> 用户态枚举（值域必须一致，见 bt_events.bpf.c 的 enum 定义）
30	///
31	/// **按来源域选择映射函数**：mgmt 来源的 raw_reason 是内核 mgmt 枚举
32	/// （MGMT_DEV_DISCONN_*），其余来源是 HCI error code。两者取值空间不同，
33	/// 混用会得出错误原因（见 wireless_event.hpp 的 disconnectReasonFromMgmtCode）。
34	DisconnectReason mapReasonFromKernel(uint8_t source, bool has_reason, uint8_t raw_reason) {
35	    if (has_reason) {
36	        return (source == static_cast<uint8_t>(EvidenceSource::KernelMgmt))
37	                   ? disconnectReasonFromMgmtCode(raw_reason)
38	                   : disconnectReasonFromHciCode(raw_reason);
39	    }
40	    // hci_conn_timeout 不携带 reason，但它的语义就是链路超时——
41	    // 这是"来源推断"，作为 supplemental hint 参与归一化（优先级低于 mgmt）。
42	    if (source == static_cast<uint8_t>(EvidenceSource::KernelHciTimeout)) {
43	        return DisconnectReason::ConnectionTimeout;
44	    }
45	    return DisconnectReason::Unknown;
46	}
47	
48	/// 内核接口层的 addr_type -> 用户态 BtAddressType
49	///
50	/// 注意：**必须同时看 link_type**。内核在这里用的是 HCI 域取值
51	/// （0=public, 1=random, 2=public_resolved, 3=random_resolved），
52	/// 单看 addr_type 无法区分 BR/EDR 与 LE（BR/EDR 连接的该字段也常为 0）。
53	/// 板端实测踩过：LE Random 设备因只读 addr_type 且缺 link_type 判定，
54	/// 被误记为 BREDR / LE_PUBLIC。
55	BtAddressType mapAddressType(uint8_t link_type, uint8_t kernel_addr_type) {
56	    return btAddressTypeFromKernel(link_type, kernel_addr_type);
57	}
58	
59	/// 墙钟毫秒（内核 ringbuf 时间戳是 CLOCK_MONOTONIC，不能直接当事件时间用）
60	uint64_t softwareTimestampMs() {
61	    return static_cast<uint64_t>(
62	        std::chrono::duration_cast<std::chrono::milliseconds>(
63	            std::chrono::system_clock::now().time_since_epoch()).count());
64	}
65	
66	}  // namespace
67	
68	// ============================================================================
69	// 构造 / 析构
70	// ============================================================================
71	
72	BtEventMonitor::BtEventMonitor(WirelessEventStore* store,
73	                               BtLinkQualityTracker* tracker,
74	                               BtNormalizerConfig normalizer_cfg)
75	    : store_(store), tracker_(tracker), normalizer_(std::move(normalizer_cfg)) {}
76	
77	BtEventMonitor::~BtEventMonitor() {
78	    stop();
79	}
80	
81	// ============================================================================
82	// 生命周期
83	// ============================================================================
84	
85	bool BtEventMonitor::init(const std::string& bpf_object_path, const std::string& gateway_id) {
86	    std::lock_guard<std::mutex> lock(mutex_);
87	
88	    if (bpf_obj_) {
89	        last_error_ = "already initialized";
90	        return true;
91	    }
92	
93	    stateSupport_.setState(EbpfMonitorState::Initializing, false);
94	    bpf_object_path_ = bpf_object_path;
95	    gateway_id_ = gateway_id;
96	
97	    bpf_obj_ = bpf_object__open(bpf_object_path.c_str());
98	    if (!bpf_obj_) {
99	        last_error_ = "bpf_object__open failed for " + bpf_object_path +
100	                      ": " + std::string(strerror(errno));
101	        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
102	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
103	        return false;
104	    }
105	
106	    if (bpf_object__load(bpf_obj_) != 0) {
107	        last_error_ = "bpf_object__load failed: " + std::string(strerror(errno));
108	        bpf_object__close(bpf_obj_);
109	        bpf_obj_ = nullptr;
110	        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
111	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
112	        return false;
113	    }
114	
115	    // ---- 逐个挂载 hook，各自独立降级 ----
116	    //
117	    // 挂点清单与 bt_events.bpf.c 的 SEC() 一一对应。
118	    // mgmt_device_disconnected 是首选事实来源（内核 mgmt 层统一出口，参数带
119	    // reason），其余作为补充证据。任一失败不影响其它。
120	    struct HookSpec {
121	        const char* kernel_function;
122	        const char* program_name;
123	    };
124	    const HookSpec specs[] = {
125	        {"mgmt_device_disconnected", "bt_mgmt_device_disconnected"},
126	        {"hci_disconnect",           "bt_hci_disconnect"},
127	        {"hci_conn_timeout",         "bt_hci_conn_timeout"},
128	        {"hci_conn_del",             "bt_hci_conn_del"},
129	    };
130	
131	    int attached_count = 0;
132	    for (const auto& spec : specs) {
133	        BtHookStatus status = attachOne(spec.kernel_function, spec.program_name);
134	        if (status.attached) ++attached_count;
135	        hooks_.push_back(std::move(status));
136	    }
137	
138	    if (attached_count == 0) {
139	        last_error_ = "all kprobe attach attempts failed";
140	        bpf_object__close(bpf_obj_);
141	        bpf_obj_ = nullptr;
142	        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
143	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_
144	                    << " — bluetooth event capture degraded to disabled");
145	        return false;
146	    }
147	
148	    // ---- ringbuf ----
149	    const int rb_map_fd = bpf_object__find_map_fd_by_name(bpf_obj_, "bt_events");
150	    if (rb_map_fd < 0) {
151	        last_error_ = "ringbuf map 'bt_events' not found";
152	        for (bpf_link* link : links_) {
153	            if (link) bpf_link__destroy(link);
154	        }
155	        links_.clear();
156	        bpf_object__close(bpf_obj_);
157	        bpf_obj_ = nullptr;
158	        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
159	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
160	        return false;
161	    }
162	    ringbuf_ = ring_buffer__new(rb_map_fd, &BtEventMonitor::onRingbufSample, this, nullptr);
163	    if (!ringbuf_) {
164	        last_error_ = "ring_buffer__new failed: " + std::string(strerror(errno));
165	        for (bpf_link* link : links_) {
166	            if (link) bpf_link__destroy(link);
167	        }
168	        links_.clear();
169	        bpf_object__close(bpf_obj_);
170	        bpf_obj_ = nullptr;
171	        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
172	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
173	        return false;
174	    }
175	
176	    cfg_map_fd_ = bpf_object__find_map_fd_by_name(bpf_obj_, "bt_events_cfg");
177	
178	    stateSupport_.setState(EbpfMonitorState::Attached, true, attachedHooksSummary());
179	    LOG_INFO(LogModule::BLUETOOTH,
180	             "BtEventMonitor: attached hooks: " << attachedHooksSummary());
181	    return true;
182	}
183	
184	bool BtEventMonitor::start() {
185	    std::lock_guard<std::mutex> lock(mutex_);
186	    if (!bpf_obj_ || !ringbuf_) {
187	        last_error_ = "start() called before successful init()";
188	        return false;
189	    }
190	
191	    // 打开内核侧开关：init 阶段不统计，start 后才开始上报
192	    if (cfg_map_fd_ >= 0) {
193	        uint32_t key = 0;
194	        uint32_t value = 1;
195	        bpf_map_update_elem(cfg_map_fd_, &key, &value, BPF_ANY);
196	    }
197	
198	    stop_.store(false);
199	    running_.store(true);
200	    consumer_ = std::thread(&BtEventMonitor::consumeLoop, this);
201	    return true;
202	}
203	
204	void BtEventMonitor::stop() {
205	    {
206	        std::lock_guard<std::mutex> lock(mutex_);
207	        stop_.store(true);
208	    }
209	    if (consumer_.joinable()) consumer_.join();
210	
211	    std::lock_guard<std::mutex> lock(mutex_);
212	    running_.store(false);
213	
214	    // 关内核开关，避免 detach 前继续产生观测
215	    if (cfg_map_fd_ >= 0) {
216	        uint32_t key = 0;
217	        uint32_t value = 0;
218	        bpf_map_update_elem(cfg_map_fd_, &key, &value, BPF_ANY);
219	    }
220	
221	    for (bpf_link* link : links_) {
222	        if (link) bpf_link__destroy(link);
223	    }
224	    links_.clear();
225	
226	    if (ringbuf_) {
227	        ring_buffer__free(ringbuf_);
228	        ringbuf_ = nullptr;
229	    }
230	    if (bpf_obj_) {
231	        bpf_object__close(bpf_obj_);
232	        bpf_obj_ = nullptr;
233	    }
234	    cfg_map_fd_ = -1;
235	
236	    if (!hooks_.empty()) {
237	        stateSupport_.setState(EbpfMonitorState::Stopped, false, "stopped");
238	    }
239	}
240	
241	// ============================================================================
242	// 挂载
243	// ============================================================================
244	
245	BtHookStatus BtEventMonitor::attachOne(const std::string& kernel_function,
246	                                       const std::string& program_name) {
247	    BtHookStatus status;
248	    status.kernel_function = kernel_function;
249	
250	    bpf_program* prog = bpf_object__find_program_by_name(bpf_obj_, program_name.c_str());
251	    if (!prog) {
252	        status.error = "program not found in BPF object";
253	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: program '" << program_name
254	                    << "' not found — skipping hook " << kernel_function);
255	        return status;
256	    }
257	
258	    bpf_link* link = bpf_program__attach(prog);
259	    const long err = libbpf_get_error(link);
260	    if (err) {
261	        status.error = "attach failed: " + std::string(strerror(errno));
262	        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: attach " << program_name
263	                    << " -> kprobe/" << kernel_function << " failed: "
264	                    << strerror(errno) << " — continuing with remaining hooks");
265	        return status;
266	    }
267	
268	    links_.push_back(link);
269	    status.attached = true;
270	    LOG_INFO(LogModule::BLUETOOTH, "BtEventMonitor: " << program_name
271	             << " attached to kprobe/" << kernel_function);
272	    return status;
273	}
274	
275	// ============================================================================
276	// ringbuf 消费
277	// ============================================================================
278	
279	int BtEventMonitor::onRingbufSample(void* ctx, void* data, size_t size) {
280	    auto* self = static_cast<BtEventMonitor*>(ctx);
281	    if (!self || !data || size < sizeof(KernelBtObservation)) return 0;
282	    self->handleObservation(*static_cast<const KernelBtObservation*>(data));
283	    return 0;
284	}
285	
286	void BtEventMonitor::handleObservation(const KernelBtObservation& obs) {
287	    // 内核观测 -> 用户态原始观测。
288	    // 注意本函数**不**决定"这是不是一个业务事件"——它只把事实投递给归一化器，
289	    // 由归一化器按合并键与时间窗决定最终产出几个 canonical 事件。
290	    RawBtObservation out;
291	    out.timestamp_ms = softwareTimestampMs();  // 墙钟时间（展示/持久化）
292	    out.monotonic_ns = obs.timestamp_ns;       // 直接保留 BPF 产生的 bpf_ktime_get_ns()（严防因果倒错）
293	    out.gateway_id = gateway_id_;
294	    out.hci_index = obs.hci_index;
295	    out.device_address = formatBdaddr(obs.bdaddr);
296	    out.address_type = mapAddressType(obs.link_type, obs.addr_type);
297	    out.event_type = DeviceEventType::LinkDisconnected;  // 当前全部 hook 都是断连语义
298	    out.source = static_cast<EvidenceSource>(obs.source);
299	    out.source_detail = reinterpret_cast<const char*>(obs.source_detail);
300	
301	    if (obs.has_reason) {
302	        out.raw_reason_code = obs.reason;   // 原始事实，无损
303	    }
304	    out.reason_hint = mapReasonFromKernel(obs.source, obs.has_reason != 0, obs.reason);
305	
306	    normalizer_.submit(out);
307	    observations_consumed_.fetch_add(1);
308	    stateSupport_.recordReadSuccess(0);
309	}
310	
311	void BtEventMonitor::consumeLoop() {
312	    while (!stop_.load()) {
313	        // 200ms 超时：既保证事件及时上送，又能快速响应 stop_
314	        const int rc = ring_buffer__poll(ringbuf_, 200);
315	        if (rc < 0 && rc != -EINTR) {
316	            stateSupport_.recordReadFailure("ring_buffer__poll failed: " +
317	                                            std::string(strerror(errno)));
318	            continue;
319	        }
320	        const uint64_t now_ms = softwareTimestampMs();
321	        flushToStore(now_ms);
322	        advanceIncidents(now_ms);
323	    }
324	    // 退出前把窗口内剩余事件定案，避免丢最后一批
325	    const uint64_t now_ms = softwareTimestampMs();
326	    flushToStore(now_ms);
327	    advanceIncidents(now_ms);
328	}
329	
330	void BtEventMonitor::flushToStore(uint64_t now_ms) {
331	    auto events = normalizer_.flushExpired(now_ms);
332	    if (events.empty()) return;
333	
334	    for (auto& ev : events) {
335	        // Phase 2 核心设计：RSSI 回填在 Normalizer 之后执行（Canonical Enrichment）。
336	        // 一次断连确定只产生唯一一个 canonical event 并继承最早的单调时间戳后，
337	        // 严格向前检索断连发生前的最近有效 RSSI（严禁取断开之后的新采样！）。
338	        if (tracker_ && !ev.rssi_at_event_dbm.has_value() && ev.monotonic_ns > 0) {
339	            WirelessDeviceKey dev_key;
340	            dev_key.site_id = ev.site_id;
341	            dev_key.gateway_id = ev.gateway_id;
342	            dev_key.hci_index = ev.hci_index;
343	            dev_key.protocol = ev.protocol;
344	            dev_key.address_type = ev.address_type;
345	            dev_key.device_address = ev.device_address;
346	
347	            auto recent_rssi = tracker_->getRssiBeforeEvent(dev_key, ev.monotonic_ns);
348	            if (recent_rssi.has_value()) {
349	                ev.rssi_at_event_dbm = *recent_rssi;
350	            }
351	        }
352	
353	        if (store_) {
354	            store_->recordEvent(ev);
355	        }
356	        events_emitted_.fetch_add(1);
357	    }
358	    stateSupport_.recordReadSuccess(0);
359	}
360	
361	void BtEventMonitor::advanceIncidents(uint64_t now_ms) {
362	    // Phase 3a：关联器是事件驱动的——静默期内没有新事件，也就没人调用它的 tick()。
363	    // 由消费线程每轮推进一次，保证"这片区域已经不再出现异常"同样能推动
364	    // 事故从 OPEN/ONGOING 走向 RESOLVED（否则结案只能等下一个事件到来，
365	    // 而那个事件可能属于另一起事故）。
366	    if (store_) {
367	        store_->tickIncidents(now_ms);
368	    }
369	}
370	
371	// ============================================================================
372	// 状态查询
373	// ============================================================================
374	
375	EbpfMonitorState BtEventMonitor::commonState() const {
376	    return stateSupport_.state();
377	}
378	
379	bool BtEventMonitor::isAvailable() const {
380	    std::lock_guard<std::mutex> lock(mutex_);
381	    return bpf_obj_ != nullptr &&
382	           stateSupport_.state() == EbpfMonitorState::Attached;
383	}
384	
385	std::vector<BtHookStatus> BtEventMonitor::hookStatuses() const {
386	    std::lock_guard<std::mutex> lock(mutex_);
387	    return hooks_;
388	}
389	
390	std::string BtEventMonitor::attachedHooksSummary() const {
391	    // 注意：本方法会在 init() 持有 mutex_ 的状态下被调用，
392	    // 因此**不**加锁，只读 hooks_（init 是 hooks_ 的唯一写入点，串行执行）。
393	    std::ostringstream oss;
394	    bool first = true;
395	    for (const auto& h : hooks_) {
396	        if (!h.attached) continue;
397	        if (!first) oss << ", ";
398	        oss << h.kernel_function;
399	        first = false;
400	    }
401	    return oss.str();
402	}
403	
404	std::string BtEventMonitor::lastError() const {
405	    std::lock_guard<std::mutex> lock(mutex_);
406	    return last_error_;
407	}
