/**
 * @file bt_event_monitor.cpp
 * @brief 蓝牙设备事件采集器实现
 *
 * 见头文件的设计说明。本文件的关键实现点：
 *   - 逐个 hook 独立挂载、独立降级（attachOne 失败只记状态不中止）
 *   - ringbuf 消费线程用 ring_buffer__poll(200ms) 便于及时响应 stop_
 *   - 内核观测 -> RawBtObservation 的转换集中在一处，便于核对字段语义
 *   - 不在此层做任何原因推断或事件合并（那是 normalizer 的职责）
 */

#include "bt_event_monitor.hpp"
#include "bt_link_quality_tracker.hpp"

#include <bpf/bpf.h>
#include <bpf/libbpf.h>

#include <cerrno>
#include <chrono>
#include <cstring>
#include <sstream>

#include "logger.hpp"

namespace weaknet_dbus {

namespace {

/// 内核枚举 -> 用户态枚举（值域必须一致，见 bt_events.bpf.c 的 enum 定义）
///
/// **按来源域选择映射函数**：mgmt 来源的 raw_reason 是内核 mgmt 枚举
/// （MGMT_DEV_DISCONN_*），其余来源是 HCI error code。两者取值空间不同，
/// 混用会得出错误原因（见 wireless_event.hpp 的 disconnectReasonFromMgmtCode）。
DisconnectReason mapReasonFromKernel(uint8_t source, bool has_reason, uint8_t raw_reason) {
    if (has_reason) {
        return (source == static_cast<uint8_t>(EvidenceSource::KernelMgmt))
                   ? disconnectReasonFromMgmtCode(raw_reason)
                   : disconnectReasonFromHciCode(raw_reason);
    }
    // hci_conn_timeout 不携带 reason，但它的语义就是链路超时——
    // 这是"来源推断"，作为 supplemental hint 参与归一化（优先级低于 mgmt）。
    if (source == static_cast<uint8_t>(EvidenceSource::KernelHciTimeout)) {
        return DisconnectReason::ConnectionTimeout;
    }
    return DisconnectReason::Unknown;
}

/// 内核接口层的 addr_type -> 用户态 BtAddressType
///
/// 注意：**必须同时看 link_type**。内核在这里用的是 HCI 域取值
/// （0=public, 1=random, 2=public_resolved, 3=random_resolved），
/// 单看 addr_type 无法区分 BR/EDR 与 LE（BR/EDR 连接的该字段也常为 0）。
/// 板端实测踩过：LE Random 设备因只读 addr_type 且缺 link_type 判定，
/// 被误记为 BREDR / LE_PUBLIC。
BtAddressType mapAddressType(uint8_t link_type, uint8_t kernel_addr_type) {
    return btAddressTypeFromKernel(link_type, kernel_addr_type);
}

/// 墙钟毫秒（内核 ringbuf 时间戳是 CLOCK_MONOTONIC，不能直接当事件时间用）
uint64_t softwareTimestampMs() {
    return static_cast<uint64_t>(
        std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count());
}

}  // namespace

// ============================================================================
// 构造 / 析构
// ============================================================================

BtEventMonitor::BtEventMonitor(WirelessEventStore* store,
                               BtLinkQualityTracker* tracker,
                               BtNormalizerConfig normalizer_cfg)
    : store_(store), tracker_(tracker), normalizer_(std::move(normalizer_cfg)) {}

BtEventMonitor::~BtEventMonitor() {
    stop();
}

// ============================================================================
// 生命周期
// ============================================================================

bool BtEventMonitor::init(const std::string& bpf_object_path, const std::string& gateway_id) {
    std::lock_guard<std::mutex> lock(mutex_);

    if (bpf_obj_) {
        last_error_ = "already initialized";
        return true;
    }

    stateSupport_.setState(EbpfMonitorState::Initializing, false);
    bpf_object_path_ = bpf_object_path;
    gateway_id_ = gateway_id;

    bpf_obj_ = bpf_object__open(bpf_object_path.c_str());
    if (!bpf_obj_) {
        last_error_ = "bpf_object__open failed for " + bpf_object_path +
                      ": " + std::string(strerror(errno));
        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
        return false;
    }

    if (bpf_object__load(bpf_obj_) != 0) {
        last_error_ = "bpf_object__load failed: " + std::string(strerror(errno));
        bpf_object__close(bpf_obj_);
        bpf_obj_ = nullptr;
        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
        return false;
    }

    // ---- 逐个挂载 hook，各自独立降级 ----
    //
    // 挂点清单与 bt_events.bpf.c 的 SEC() 一一对应。
    // mgmt_device_disconnected 是首选事实来源（内核 mgmt 层统一出口，参数带
    // reason），其余作为补充证据。任一失败不影响其它。
    struct HookSpec {
        const char* kernel_function;
        const char* program_name;
    };
    const HookSpec specs[] = {
        {"mgmt_device_disconnected", "bt_mgmt_device_disconnected"},
        {"hci_disconnect",           "bt_hci_disconnect"},
        {"hci_conn_timeout",         "bt_hci_conn_timeout"},
        {"hci_conn_del",             "bt_hci_conn_del"},
    };

    int attached_count = 0;
    for (const auto& spec : specs) {
        BtHookStatus status = attachOne(spec.kernel_function, spec.program_name);
        if (status.attached) ++attached_count;
        hooks_.push_back(std::move(status));
    }

    if (attached_count == 0) {
        last_error_ = "all kprobe attach attempts failed";
        bpf_object__close(bpf_obj_);
        bpf_obj_ = nullptr;
        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_
                    << " — bluetooth event capture degraded to disabled");
        return false;
    }

    // ---- ringbuf ----
    const int rb_map_fd = bpf_object__find_map_fd_by_name(bpf_obj_, "bt_events");
    if (rb_map_fd < 0) {
        last_error_ = "ringbuf map 'bt_events' not found";
        for (bpf_link* link : links_) {
            if (link) bpf_link__destroy(link);
        }
        links_.clear();
        bpf_object__close(bpf_obj_);
        bpf_obj_ = nullptr;
        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
        return false;
    }
    ringbuf_ = ring_buffer__new(rb_map_fd, &BtEventMonitor::onRingbufSample, this, nullptr);
    if (!ringbuf_) {
        last_error_ = "ring_buffer__new failed: " + std::string(strerror(errno));
        for (bpf_link* link : links_) {
            if (link) bpf_link__destroy(link);
        }
        links_.clear();
        bpf_object__close(bpf_obj_);
        bpf_obj_ = nullptr;
        stateSupport_.setState(EbpfMonitorState::Fallback, false, last_error_);
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: " << last_error_);
        return false;
    }

    cfg_map_fd_ = bpf_object__find_map_fd_by_name(bpf_obj_, "bt_events_cfg");

    stateSupport_.setState(EbpfMonitorState::Attached, true, attachedHooksSummary());
    LOG_INFO(LogModule::BLUETOOTH,
             "BtEventMonitor: attached hooks: " << attachedHooksSummary());
    return true;
}

bool BtEventMonitor::start() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!bpf_obj_ || !ringbuf_) {
        last_error_ = "start() called before successful init()";
        return false;
    }

    // 打开内核侧开关：init 阶段不统计，start 后才开始上报
    if (cfg_map_fd_ >= 0) {
        uint32_t key = 0;
        uint32_t value = 1;
        bpf_map_update_elem(cfg_map_fd_, &key, &value, BPF_ANY);
    }

    stop_.store(false);
    running_.store(true);
    consumer_ = std::thread(&BtEventMonitor::consumeLoop, this);
    return true;
}

void BtEventMonitor::stop() {
    {
        std::lock_guard<std::mutex> lock(mutex_);
        stop_.store(true);
    }
    if (consumer_.joinable()) consumer_.join();

    std::lock_guard<std::mutex> lock(mutex_);
    running_.store(false);

    // 关内核开关，避免 detach 前继续产生观测
    if (cfg_map_fd_ >= 0) {
        uint32_t key = 0;
        uint32_t value = 0;
        bpf_map_update_elem(cfg_map_fd_, &key, &value, BPF_ANY);
    }

    for (bpf_link* link : links_) {
        if (link) bpf_link__destroy(link);
    }
    links_.clear();

    if (ringbuf_) {
        ring_buffer__free(ringbuf_);
        ringbuf_ = nullptr;
    }
    if (bpf_obj_) {
        bpf_object__close(bpf_obj_);
        bpf_obj_ = nullptr;
    }
    cfg_map_fd_ = -1;

    if (!hooks_.empty()) {
        stateSupport_.setState(EbpfMonitorState::Stopped, false, "stopped");
    }
}

// ============================================================================
// 挂载
// ============================================================================

BtHookStatus BtEventMonitor::attachOne(const std::string& kernel_function,
                                       const std::string& program_name) {
    BtHookStatus status;
    status.kernel_function = kernel_function;

    bpf_program* prog = bpf_object__find_program_by_name(bpf_obj_, program_name.c_str());
    if (!prog) {
        status.error = "program not found in BPF object";
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: program '" << program_name
                    << "' not found — skipping hook " << kernel_function);
        return status;
    }

    bpf_link* link = bpf_program__attach(prog);
    const long err = libbpf_get_error(link);
    if (err) {
        status.error = "attach failed: " + std::string(strerror(errno));
        LOG_WARNING(LogModule::BLUETOOTH, "BtEventMonitor: attach " << program_name
                    << " -> kprobe/" << kernel_function << " failed: "
                    << strerror(errno) << " — continuing with remaining hooks");
        return status;
    }

    links_.push_back(link);
    status.attached = true;
    LOG_INFO(LogModule::BLUETOOTH, "BtEventMonitor: " << program_name
             << " attached to kprobe/" << kernel_function);
    return status;
}

// ============================================================================
// ringbuf 消费
// ============================================================================

int BtEventMonitor::onRingbufSample(void* ctx, void* data, size_t size) {
    auto* self = static_cast<BtEventMonitor*>(ctx);
    if (!self || !data || size < sizeof(KernelBtObservation)) return 0;
    self->handleObservation(*static_cast<const KernelBtObservation*>(data));
    return 0;
}

void BtEventMonitor::handleObservation(const KernelBtObservation& obs) {
    // 内核观测 -> 用户态原始观测。
    // 注意本函数**不**决定"这是不是一个业务事件"——它只把事实投递给归一化器，
    // 由归一化器按合并键与时间窗决定最终产出几个 canonical 事件。
    RawBtObservation out;
    out.timestamp_ms = softwareTimestampMs();  // 墙钟时间（展示/持久化）
    out.monotonic_ns = obs.timestamp_ns;       // 直接保留 BPF 产生的 bpf_ktime_get_ns()（严防因果倒错）
    out.gateway_id = gateway_id_;
    out.hci_index = obs.hci_index;
    out.device_address = formatBdaddr(obs.bdaddr);
    out.address_type = mapAddressType(obs.link_type, obs.addr_type);
    out.event_type = DeviceEventType::LinkDisconnected;  // 当前全部 hook 都是断连语义
    out.source = static_cast<EvidenceSource>(obs.source);
    out.source_detail = reinterpret_cast<const char*>(obs.source_detail);

    if (obs.has_reason) {
        out.raw_reason_code = obs.reason;   // 原始事实，无损
    }
    out.reason_hint = mapReasonFromKernel(obs.source, obs.has_reason != 0, obs.reason);

    normalizer_.submit(out);
    observations_consumed_.fetch_add(1);
    stateSupport_.recordReadSuccess(0);
}

void BtEventMonitor::consumeLoop() {
    while (!stop_.load()) {
        // 200ms 超时：既保证事件及时上送，又能快速响应 stop_
        const int rc = ring_buffer__poll(ringbuf_, 200);
        if (rc < 0 && rc != -EINTR) {
            stateSupport_.recordReadFailure("ring_buffer__poll failed: " +
                                            std::string(strerror(errno)));
            continue;
        }
        const uint64_t now_ms = softwareTimestampMs();
        flushToStore(now_ms);
        advanceIncidents(now_ms);
    }
    // 退出前把窗口内剩余事件定案，避免丢最后一批
    const uint64_t now_ms = softwareTimestampMs();
    flushToStore(now_ms);
    advanceIncidents(now_ms);
}

void BtEventMonitor::flushToStore(uint64_t now_ms) {
    auto events = normalizer_.flushExpired(now_ms);
    if (events.empty()) return;

    for (auto& ev : events) {
        // Phase 2 核心设计：RSSI 回填在 Normalizer 之后执行（Canonical Enrichment）。
        // 一次断连确定只产生唯一一个 canonical event 并继承最早的单调时间戳后，
        // 严格向前检索断连发生前的最近有效 RSSI（严禁取断开之后的新采样！）。
        if (tracker_ && !ev.rssi_at_event_dbm.has_value() && ev.monotonic_ns > 0) {
            WirelessDeviceKey dev_key;
            dev_key.site_id = ev.site_id;
            dev_key.gateway_id = ev.gateway_id;
            dev_key.hci_index = ev.hci_index;
            dev_key.protocol = ev.protocol;
            dev_key.address_type = ev.address_type;
            dev_key.device_address = ev.device_address;

            auto recent_rssi = tracker_->getRssiBeforeEvent(dev_key, ev.monotonic_ns);
            if (recent_rssi.has_value()) {
                ev.rssi_at_event_dbm = *recent_rssi;
            }
        }

        if (store_) {
            store_->recordEvent(ev);
        }
        events_emitted_.fetch_add(1);
    }
    stateSupport_.recordReadSuccess(0);
}

void BtEventMonitor::advanceIncidents(uint64_t now_ms) {
    // Phase 3a：关联器是事件驱动的——静默期内没有新事件，也就没人调用它的 tick()。
    // 由消费线程每轮推进一次，保证"这片区域已经不再出现异常"同样能推动
    // 事故从 OPEN/ONGOING 走向 RESOLVED（否则结案只能等下一个事件到来，
    // 而那个事件可能属于另一起事故）。
    if (store_) {
        store_->tickIncidents(now_ms);
    }
}

// ============================================================================
// 状态查询
// ============================================================================

EbpfMonitorState BtEventMonitor::commonState() const {
    return stateSupport_.state();
}

bool BtEventMonitor::isAvailable() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return bpf_obj_ != nullptr &&
           stateSupport_.state() == EbpfMonitorState::Attached;
}

std::vector<BtHookStatus> BtEventMonitor::hookStatuses() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return hooks_;
}

std::string BtEventMonitor::attachedHooksSummary() const {
    // 注意：本方法会在 init() 持有 mutex_ 的状态下被调用，
    // 因此**不**加锁，只读 hooks_（init 是 hooks_ 的唯一写入点，串行执行）。
    std::ostringstream oss;
    bool first = true;
    for (const auto& h : hooks_) {
        if (!h.attached) continue;
        if (!first) oss << ", ";
        oss << h.kernel_function;
        first = false;
    }
    return oss.str();
}

std::string BtEventMonitor::lastError() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return last_error_;
}

std::vector<WirelessDeviceEvent> BtEventMonitor::drainNormalizedEvents() {
    return normalizer_.flushAll();
}

}  // namespace weaknet_dbus

/**
 * @file bt_data_path_anomaly_detector.cpp
 * @brief Phase 2 规则驱动工业蓝牙 L2 数据通道异常检测器实现
 */

#include "bt_data_path_anomaly_detector.hpp"
#include "utils/json_escape.hpp"
#include <sstream>

namespace weaknet_dbus {

std::string BtDataPathAnomaly::toJson() const {
    std::ostringstream oss;
    oss << "{"
        << "\"anomaly_type\":\"" << weaknet_utils::escapeJsonString(anomaly_type) << "\","
        << "\"controller_id\":\"" << weaknet_utils::escapeJsonString(controller_id) << "\","
        << "\"handle\":" << connection_handle << ","
        << "\"generation\":" << connection_generation << ","
        << "\"device_address\":\"" << weaknet_utils::escapeJsonString(device_address) << "\","
        << "\"severity\":\"" << weaknet_utils::escapeJsonString(severity) << "\","
        << "\"description\":\"" << weaknet_utils::escapeJsonString(description) << "\","
        << "\"detected_at_ms\":" << detected_at_ms << ","
        << "\"evidence\":{"
        << "\"tx_bytes\":" << tx_bytes << ","
        << "\"rx_bytes\":" << rx_bytes << ","
        << "\"actual_bps\":" << actual_bps << ","
        << "\"expected_bps\":" << expected_bps << ","
        << "\"consecutive_windows\":" << consecutive_windows << ","
        << "\"max_gap_ms\":" << max_gap_ms
        << "}"
        << "}";
    return oss.str();
}

BtDataPathAnomalyDetector::BtDataPathAnomalyDetector(BtAnomalyDetectorConfig config)
    : config_(std::move(config)) {}

void BtDataPathAnomalyDetector::updateConfig(const BtAnomalyDetectorConfig& config) {
    config_ = config;
}

BtAnomalyDetectorConfig BtDataPathAnomalyDetector::config() const {
    return config_;
}

void BtDataPathAnomalyDetector::resetConnectionState(const std::string& controller, uint16_t handle) {
    std::string key = controller + ":" + std::to_string(handle & 0x0FFF);
    conn_states_.erase(key);
}

std::vector<BtDataPathAnomaly> BtDataPathAnomalyDetector::evaluate(
    const std::vector<BtDataPathObservation>& observations,
    int64_t now_ms) {

    std::vector<BtDataPathAnomaly> anomalies;

    for (const auto& obs : observations) {
        std::string slot_key = obs.controller_id + ":" + std::to_string(obs.connection_handle & 0x0FFF);
        auto& state = conn_states_[slot_key];

        // 代次跃迁或新连接：状态归零重置
        if (state.generation != obs.connection_generation) {
            state.generation = obs.connection_generation;
            state.consecutive_stalls = 0;
            state.consecutive_degraded = 0;
            state.last_active_ts_ms = now_ms;
            state.stall_reported_level = 0;
            state.degraded_reported = false;
            state.attribution_reported = false;
        }

        const bool has_traffic = (obs.tx_bytes > 0 || obs.rx_bytes > 0);
        const double total_bps = obs.tx_throughput_bps + obs.rx_throughput_bps;

        // -----------------------------------------------------------------
        // 规则 1：BT_DATAPATH_ATTRIBUTION_LOST (归因丢失)
        // 存在真实控制器级传输，但未能绑定到具体设备 BDADDR。
        // 抑制重复：同一连接只在归因丢失期间上报一次，归因恢复或代次变迁后重置。
        // -----------------------------------------------------------------
        if (has_traffic && (obs.attribution_scope == "controller" || obs.attribution_scope == "unknown")) {
            if (!state.attribution_reported) {
                state.attribution_reported = true;
                BtDataPathAnomaly a;
                a.anomaly_type = btAnomalyTypeToString(BtAnomalyType::AttributionLost);
                a.controller_id = obs.controller_id;
                a.connection_handle = obs.connection_handle;
                a.connection_generation = obs.connection_generation;
                a.device_address = obs.device_id.value_or("");
                a.severity = "WARNING";
                a.description = "Controller observed active ACL payload traffic, but device identity could not be reliably attributed.";
                a.detected_at_ms = now_ms;
                a.tx_bytes = obs.tx_bytes;
                a.rx_bytes = obs.rx_bytes;
                a.actual_bps = total_bps;
                a.consecutive_windows = 1;
                a.max_gap_ms = obs.max_gap_ms;
                anomalies.push_back(std::move(a));
            }
        } else {
            state.attribution_reported = false;
        }

        // -----------------------------------------------------------------
        // 规则 2：BT_DATAPATH_STALL_SUSPECTED (疑似数据流停顿)
        // 必须配置了业务心跳预期 (stall_timeout_ms > 0)。
        // 只对已归因到具体设备的连接生效：心跳 SLA 是设备级契约，没有设备
        // 身份就无从谈起；controller 归因的活跃流量异常由规则 1 覆盖。
        // 抑制重复：只在阈值首次跨越上报 WARNING、达到 2 倍阈值再上报一次
        // CRITICAL 升级——持续静默期间不逐窗口重复刷（板端实测每 2 秒一条）。
        // -----------------------------------------------------------------
        if (config_.stall_timeout_ms > 0 &&
            obs.attribution_scope == "device" && obs.device_id.has_value()) {
            if (!has_traffic) {
                state.consecutive_stalls++;
                if (state.consecutive_stalls >= config_.stall_consecutive_windows) {
                    const int level = (state.consecutive_stalls >= config_.stall_consecutive_windows * 2) ? 2 : 1;
                    if (level > state.stall_reported_level) {
                        state.stall_reported_level = level;
                        BtDataPathAnomaly a;
                        a.anomaly_type = btAnomalyTypeToString(BtAnomalyType::StallSuspected);
                        a.controller_id = obs.controller_id;
                        a.connection_handle = obs.connection_handle;
                        a.connection_generation = obs.connection_generation;
                        a.device_address = obs.device_id.value_or("");
                        a.severity = (level == 2) ? "CRITICAL" : "WARNING";
                        a.description = "Consecutive silence windows detected under configured heartbeat SLA expectation.";
                        a.detected_at_ms = now_ms;
                        a.tx_bytes = 0;
                        a.rx_bytes = 0;
                        a.actual_bps = 0.0;
                        a.expected_bps = config_.min_expected_bps;
                        a.consecutive_windows = state.consecutive_stalls;
                        a.max_gap_ms = obs.max_gap_ms;
                        anomalies.push_back(std::move(a));
                    }
                }
            } else {
                state.consecutive_stalls = 0;
                state.stall_reported_level = 0;
                state.last_active_ts_ms = now_ms;
            }
        } else {
            // 非设备归因连接（幻影观测/归因丢失期间）：清空停顿状态，
            // 避免死句柄残留观测在归因恢复后带着旧计数复活误报。
            state.consecutive_stalls = 0;
            state.stall_reported_level = 0;
        }

        // -----------------------------------------------------------------
        // 规则 3：BT_DATAPATH_THROUGHPUT_DEGRADED (吞吐量持续劣化)
        // 必须配置了最低保底预期 (min_expected_bps > 0)，且连接处于通信状态。
        // 抑制重复：自上次恢复起只上报一次，吞吐回到阈值之上后重新武装。
        // -----------------------------------------------------------------
        if (config_.min_expected_bps > 0.0) {
            if (has_traffic && total_bps < config_.min_expected_bps) {
                state.consecutive_degraded++;
                if (state.consecutive_degraded >= config_.degraded_consecutive_windows &&
                    !state.degraded_reported) {
                    state.degraded_reported = true;
                    BtDataPathAnomaly a;
                    a.anomaly_type = btAnomalyTypeToString(BtAnomalyType::ThroughputDegraded);
                    a.controller_id = obs.controller_id;
                    a.connection_handle = obs.connection_handle;
                    a.connection_generation = obs.connection_generation;
                    a.device_address = obs.device_id.value_or("");
                    a.severity = "WARNING";
                    a.description = "Observed throughput consistently below configured operational threshold.";
                    a.detected_at_ms = now_ms;
                    a.tx_bytes = obs.tx_bytes;
                    a.rx_bytes = obs.rx_bytes;
                    a.actual_bps = total_bps;
                    a.expected_bps = config_.min_expected_bps;
                    a.consecutive_windows = state.consecutive_degraded;
                    a.max_gap_ms = obs.max_gap_ms;
                    anomalies.push_back(std::move(a));
                }
            } else if (has_traffic) {
                state.consecutive_degraded = 0;
                state.degraded_reported = false;
            }
        }
    }

    return anomalies;
}

} // namespace weaknet_dbus

#include "bt_hci_connection_tracker.hpp"
#include <algorithm>
#include <cctype>
#include <cstring>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <set>

namespace weaknet {

namespace {

std::string makeSlotKey(const std::string& controller, uint16_t handle) {
    return controller + ":" + std::to_string(handle & 0x0FFF);
}

std::string normalizeMac(const std::string& mac) {
    if (mac.empty()) return "";
    std::string out;
    out.reserve(mac.size());
    for (char c : mac) {
        out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(c))));
    }
    return out;
}

} // namespace

HciConnectionKey BtHciConnectionTracker::onConnectionEstablished(
    const std::string& controller,
    uint16_t handle,
    const std::string& mac,
    const std::string& addr_type) {

    uint16_t valid_handle = handle & 0x0FFF;
    std::string slot_key = makeSlotKey(controller, valid_handle);
    std::string clean_mac = normalizeMac(mac);

    std::lock_guard<std::mutex> lock(mutex_);

    auto it = active_map_.find(slot_key);
    if (it != active_map_.end() && it->second.is_active) {
        // 重复通知幂等处理：若 MAC 一致，直接复用当前代次
        if (!clean_mac.empty() && it->second.device_mac == clean_mac) {
            return it->second.key;
        }
        // 若 MAC 发生冲突或前连接未正常收到 disconnect，强制递增代次
        it->second.is_active = false;
        it->second.disconnected_at = std::chrono::steady_clock::now();
    }

    uint32_t next_gen = ++generation_counter_[slot_key];

    HciConnectionKey key{controller, valid_handle, next_gen};
    HciConnectionRecord record;
    record.key = key;
    record.device_mac = clean_mac;
    record.address_type = addr_type.empty() ? "UNKNOWN" : addr_type;
    record.attribution_scope = clean_mac.empty() ? "controller" : "device";
    record.connected_at = std::chrono::steady_clock::now();
    record.is_active = true;

    active_map_[slot_key] = record;
    return key;
}

bool BtHciConnectionTracker::onConnectionDisconnected(
    const std::string& controller, uint16_t handle) {

    uint16_t valid_handle = handle & 0x0FFF;
    std::string slot_key = makeSlotKey(controller, valid_handle);

    std::lock_guard<std::mutex> lock(mutex_);
    auto it = active_map_.find(slot_key);
    if (it == active_map_.end() || !it->second.is_active) {
        return false;
    }

    it->second.is_active = false;
    it->second.disconnected_at = std::chrono::steady_clock::now();
    return true;
}

std::optional<HciConnectionRecord> BtHciConnectionTracker::getActiveConnection(
    const std::string& controller, uint16_t handle) const {

    uint16_t valid_handle = handle & 0x0FFF;
    std::string slot_key = makeSlotKey(controller, valid_handle);

    std::lock_guard<std::mutex> lock(mutex_);
    auto it = active_map_.find(slot_key);
    if (it != active_map_.end() && it->second.is_active) {
        return it->second;
    }
    return std::nullopt;
}

std::vector<HciConnectionRecord> BtHciConnectionTracker::getActiveConnections(
    const std::string& controller) const {

    std::lock_guard<std::mutex> lock(mutex_);
    std::vector<HciConnectionRecord> res;
    for (const auto& [k, v] : active_map_) {
        if (v.is_active && v.key.controller_id == controller) {
            res.push_back(v);
        }
    }
    return res;
}

void BtHciConnectionTracker::resetController(const std::string& controller) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto now = std::chrono::steady_clock::now();
    for (auto& [k, v] : active_map_) {
        if (v.key.controller_id == controller && v.is_active) {
            v.is_active = false;
            v.disconnected_at = now;
            // 控制器复位时提前递增代次计数，避免硬件重启后立即重分配同句柄造成串号
            generation_counter_[k]++;
        }
    }
}

size_t BtHciConnectionTracker::syncFromKernel(const std::string& controller) {
    // 1. 打开 HCI 控制套接字 (AF_BLUETOOTH, SOCK_RAW, BTPROTO_HCI)
    #ifndef AF_BLUETOOTH
    #define AF_BLUETOOTH 31
    #endif
    #ifndef BTPROTO_HCI
    #define BTPROTO_HCI 1
    #endif
    #ifndef HCIGETCONNLIST
    // _IOR('H', 212, int) = 0x800448d4
    #define HCIGETCONNLIST 0x800448d4
    #endif

    int sock = ::socket(AF_BLUETOOTH, SOCK_RAW | SOCK_CLOEXEC, BTPROTO_HCI);
    if (sock < 0) {
        return activeCount();
    }

    // 解析 controller 编号，如 "hci0" -> 0
    uint16_t dev_id = 0;
    if (controller.rfind("hci", 0) == 0 && controller.size() > 3) {
        try {
            dev_id = static_cast<uint16_t>(std::stoi(controller.substr(3)));
        } catch (...) {
            dev_id = 0;
        }
    }

    // 内存缓冲区：头部 4 字节 (dev_id + conn_num) + 最多 64 条 struct hci_conn_info (每条 16 字节)
    struct RawHciConnInfo {
        uint16_t handle;
        uint8_t bdaddr[6];
        uint8_t type;
        uint8_t out;
        uint16_t state;
        uint32_t link_mode;
    } __attribute__((packed));

    uint8_t buf[4 + 64 * sizeof(RawHciConnInfo)] = {0};
    *reinterpret_cast<uint16_t*>(buf) = dev_id;
    *reinterpret_cast<uint16_t*>(buf + 2) = 64; // 最多获取 64 个连接

    int ret = ::ioctl(sock, HCIGETCONNLIST, buf);
    ::close(sock);

    if (ret < 0) {
        return activeCount();
    }

    uint16_t conn_num = *reinterpret_cast<uint16_t*>(buf + 2);
    if (conn_num > 64) conn_num = 64;

    std::set<uint16_t> live_handles;
    const RawHciConnInfo* conns = reinterpret_cast<const RawHciConnInfo*>(buf + 4);

    for (uint16_t i = 0; i < conn_num; ++i) {
        uint16_t handle = conns[i].handle & 0x0FFF;

        // 过滤未建立链路：内核 conn list 会包含 BT_CONNECT（page 进行中）的
        // 半开连接，其 handle 恒为 0（Connection Complete 之前控制器还没分配）。
        // 板端实测：一次失败的 l2ping page 就会留下 handle=0 的记录，被当作
        // 活跃连接后 STALL 规则会对"从未连上"的设备持续误报（与 bt_events BPF
        // 对 handle=0 的过滤同理——理论边界是句柄 0 合法，但控制器实际分配
        // 几乎总是从非 0 开始，过滤海量失败尝试是净收益）。
        // 注意：跳过的 handle=0 不进 live_handles，若曾有残留记录会被下方清理。
        if (handle == 0) continue;
        live_handles.insert(handle);

        // 内核 bdaddr 反序存储 (b[0] 为低位)
        char mac_buf[18];
        snprintf(mac_buf, sizeof(mac_buf), "%02X:%02X:%02X:%02X:%02X:%02X",
                 conns[i].bdaddr[5], conns[i].bdaddr[4], conns[i].bdaddr[3],
                 conns[i].bdaddr[2], conns[i].bdaddr[1], conns[i].bdaddr[0]);
        std::string mac(mac_buf);

        std::string addr_type = (conns[i].type == 0x80) ? "LE" : "BREDR";

        // 更新/建立真实连接
        onConnectionEstablished(controller, handle, mac, addr_type);
    }

    // 检查并清理已被内核销毁但尚未收到事件的句柄
    std::vector<HciConnectionRecord> current_actives = getActiveConnections(controller);
    for (const auto& rec : current_actives) {
        if (live_handles.find(rec.key.handle) == live_handles.end()) {
            onConnectionDisconnected(controller, rec.key.handle);
        }
    }

    return activeCount();
}

size_t BtHciConnectionTracker::activeCount() const {
    std::lock_guard<std::mutex> lock(mutex_);
    size_t count = 0;
    for (const auto& [k, v] : active_map_) {
        if (v.is_active) count++;
    }
    return count;
}

} // namespace weaknet

/**
 * @file wireless_event_store.cpp
 * @brief 规范化无线设备事件存储实现
 */

#include "wireless_event_store.hpp"

#include <algorithm>

#include "database_manager.hpp"
#include "logger.hpp"
#include "site_incident_correlator.hpp"

namespace weaknet_dbus {

WirelessEventStore::WirelessEventStore(DatabaseManager* db, WirelessEventStoreConfig cfg)
    : db_(db), cfg_(std::move(cfg)) {
    // 环形缓冲按容量预留，避免运行期反复扩容
    (void)0;
}

bool WirelessEventStore::recordEvent(const WirelessDeviceEvent& event) {
    // 待投递给关联器的事件快照。**必须在锁内拷贝**：调用方可能在栈上复用
    // 同一个 event 对象，锁外再引用它就成了悬垂读（这不是假设——单元测试与
    // 消费循环都会循环复用同一个变量）。
    std::optional<WirelessDeviceEvent> to_observe;

    {
        std::lock_guard<std::mutex> lock(mu_);

        // 补齐来源身份：Phase 1 运行模型是"1 Gateway = 1 Site"，
        // 事件若未自带 site_id/gateway_id（如来自测试或未来的其它生产者），
        // 用 store 配置兜底，保证落库行永远可回答"这个事件是哪台探针看到的"。
        WirelessDeviceEvent ev = event;
        if (ev.gateway_id.empty()) ev.gateway_id = cfg_.gateway_id;
        if (ev.site_id.empty()) {
            ev.site_id = cfg_.site_id.empty() ? ev.gateway_id : cfg_.site_id;
        }

        ring_.push_back(ev);
        while (ring_.size() > cfg_.ring_capacity) {
            ring_.pop_front();
        }
        ++total_recorded_;

        // 只有真的落库成功的事件才参与区域关联：关联窗口的证据回链要求
        // site_incident_events 能 JOIN 到 device_events 行，未落库的事件
        // 关联出来的 incident 查不出设备清单。db_ 为空（纯内存模式）时同样跳过。
        bool persist_ok = false;
        if (db_) {
            persist_ok = db_->insertDeviceEvent(
                ev.event_id,
                static_cast<int64_t>(ev.timestamp_ms),
                ev.site_id,
                ev.gateway_id,
                toString(ev.protocol),
                ev.device_address,
                toString(ev.address_type),
                ev.hci_index,
                toString(ev.event_type),
                ev.rssi_at_event_dbm,
                ev.raw_reason_code,
                toString(ev.reason),
                toString(ev.source),
                ev.source_detail,
                ev.suspected_cause,
                ev.details_json);
            if (!persist_ok) {
                ++persist_failures_;
                LOG_WARNING(LogModule::BLUETOOTH,
                            "WirelessEventStore: failed to persist event " << ev.event_id
                            << " (device=" << ev.device_address
                            << ", type=" << toString(ev.event_type) << ")");
            }
        }

        // Phase 3a：把同一条事件投递给区域级关联器，产出/推进 SiteIncident。
        // 关联发生在**落库之后**：即使关联器失败，设备事件这一**事实**已经持久化。
        if (correlator_ && persist_ok) {
            to_observe = std::move(ev);
        }
    }

    // 关联调用刻意放在锁外：correlator 有独立 mutex_，且会去拿
    // DatabaseManager::mutex_。在持有 mu_ 时调用就形成
    // store.mu_ -> correlator.mutex_ -> db.mutex_ 的三段嵌套，
    // 一旦任何一处反向加锁即死锁。
    if (to_observe.has_value()) {
        correlator_->observe(*to_observe);
    }

    return true;
}

void WirelessEventStore::setIncidentCorrelator(SiteIncidentCorrelator* correlator) {
    std::lock_guard<std::mutex> lock(mu_);
    correlator_ = correlator;
}

size_t WirelessEventStore::tickIncidents(uint64_t now_ms) {
    // 关联器指针只在插件 start/stop 时变更，且 stop 会先停消费线程，
    // 因此这里不加锁读取是安全的（与 queryPersisted 同一纪律：不制造
    // store 锁 -> 关联器锁的嵌套）。
    if (!correlator_) return 0;
    return correlator_->tick(now_ms).size();
}

std::string WirelessEventStore::querySiteIncidents(const std::string& state,
                                                   int64_t start_ms,
                                                   int64_t end_ms,
                                                   int limit) const {
    if (!correlator_) return "[]";
    return correlator_->queryPersisted(state, start_ms, end_ms, limit, true);
}

std::vector<WirelessDeviceEvent> WirelessEventStore::recentEvents(
    const std::string& device_address, size_t limit) const {
    std::lock_guard<std::mutex> lock(mu_);

    std::vector<WirelessDeviceEvent> out;
    if (limit == 0) return out;

    // ring_ 是时间正序，这里倒序遍历以获得"最近优先"
    for (auto it = ring_.rbegin(); it != ring_.rend(); ++it) {
        if (!device_address.empty() && it->device_address != device_address) continue;
        out.push_back(*it);
        if (out.size() >= limit) break;
    }
    return out;
}

uint64_t WirelessEventStore::totalRecorded() const {
    std::lock_guard<std::mutex> lock(mu_);
    return total_recorded_;
}

uint64_t WirelessEventStore::persistFailures() const {
    std::lock_guard<std::mutex> lock(mu_);
    return persist_failures_;
}

std::string WirelessEventStore::queryPersisted(const std::string& device_address,
                                               const std::string& event_type,
                                               int64_t start_ms,
                                               int64_t end_ms,
                                               int limit) const {
    if (!db_) return "[]";
    // 刻意不持有本类 mutex_：DB 查询走 DatabaseManager 自己的锁，
    // 避免"store 锁 -> db 锁"的嵌套顺序造成潜在死锁。
    return db_->queryDeviceEvents(device_address, event_type, start_ms, end_ms, limit);
}

bool WirelessEventStore::saveDeviceBaseline(const DeviceLinkProfile& profile) {
    if (!db_) return false;
    return db_->upsertDeviceBaseline(
        profile.key.site_id,
        profile.key.gateway_id,
        profile.key.hci_index,
        toString(profile.key.protocol),
        toString(profile.key.address_type),
        profile.key.device_address,
        profile.baseline_rssi_dbm,
        profile.min_seen_rssi_dbm,
        profile.max_seen_rssi_dbm,
        profile.baseline_sample_count,
        static_cast<int64_t>(profile.first_seen_ms),
        static_cast<int64_t>(profile.last_seen_ms),
        toString(profile.state),
        static_cast<int64_t>(profile.updated_at_ms));
}

std::string WirelessEventStore::queryDeviceBaselines(const std::string& device_address,
                                                    int limit) const {
    if (!db_) return "[]";
    return db_->queryDeviceBaselines(device_address, limit);
}

void WirelessEventStore::clearMemory() {
    std::lock_guard<std::mutex> lock(mu_);
    ring_.clear();
}

}  // namespace weaknet_dbus

/**
 * @file bt_event_normalizer.cpp
 * @brief 蓝牙原始观测归一化器实现
 *
 * 核心不变式（修改本文件前必须读懂）：
 *   - 每个 kprobe 只产生 RawBtObservation，绝不产生 WirelessDeviceEvent
 *   - 合并键含 gateway_id / hci_index / address_type，同 MAC 跨控制器不合并
 *   - 窗口外不合并：两次真实断连必须产生两个 canonical 事件
 *   - 原因定案遵循优先级（mgmt raw > 其余 raw > supplemental hint > Unknown），
 *     但所有观测一律进入 raw_evidence，优先级不覆盖原始事实
 *   - reason 的归一化按**来源域**选择映射：mgmt 来源用 MGMT_DEV_DISCONN_* 枚举，
 *     其余来源用 HCI error code；两域取值空间不同不可互套
 *   - 不产出 suspected_cause（那是诊断器的职责）
 */

#include "bt_event_normalizer.hpp"

#include <algorithm>
#include <iomanip>
#include <random>
#include <sstream>
#include <tuple>

namespace weaknet_dbus {

// ============================================================================
// MergeKey
// ============================================================================

bool BtEventNormalizer::MergeKey::operator<(const MergeKey& other) const {
    // 逐字段字典序比较，等价于对五元组做全序排序。
    // 用 std::tie 而非手写嵌套 if，避免遗漏字段导致"看起来不同的事件被合并"。
    return std::tie(gateway_id, hci_index, address_type, device_address, event_type) <
           std::tie(other.gateway_id, other.hci_index, other.address_type,
                    other.device_address, other.event_type);
}

// ============================================================================
// 构造 / 诊断
// ============================================================================

BtEventNormalizer::BtEventNormalizer(BtNormalizerConfig cfg) : cfg_(std::move(cfg)) {
    // 每实例一个随机短码（8 个 hex 字符）。不同进程/不同重启之间碰撞概率
    // 极低，配合 seq 即可保证 event_id 跨重启唯一（见头文件成员注释）。
    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_int_distribution<uint64_t> dis;
    std::ostringstream nonce;
    nonce << std::hex << std::setfill('0') << std::setw(8)
          << (dis(gen) & 0xFFFFFFFFULL);
    instance_nonce_ = nonce.str();
}

size_t BtEventNormalizer::pendingCount() const {
    std::lock_guard<std::mutex> lock(mu_);
    return pending_.size();
}

uint64_t BtEventNormalizer::normalizedCount() const {
    std::lock_guard<std::mutex> lock(mu_);
    return normalized_total_;
}

void BtEventNormalizer::reset() {
    std::lock_guard<std::mutex> lock(mu_);
    pending_.clear();
    seq_ = 0;
    normalized_total_ = 0;
}

// ============================================================================
// 投递观测
// ============================================================================

BtEventNormalizer::MergeKey BtEventNormalizer::makeKey(const RawBtObservation& obs) {
    MergeKey key;
    key.gateway_id = obs.gateway_id;
    key.hci_index = obs.hci_index;
    key.address_type = obs.address_type;
    key.device_address = obs.device_address;
    key.event_type = obs.event_type;
    return key;
}

void BtEventNormalizer::submit(const RawBtObservation& obs) {
    std::lock_guard<std::mutex> lock(mu_);

    const MergeKey key = makeKey(obs);
    auto it = pending_.find(key);

    // 已存在 pending 且仍在合并窗口内 -> 归入同一 canonical 事件
    if (it != pending_.end() &&
        obs.timestamp_ms <= it->second.last_obs_ms + cfg_.merge_window_ms) {
        applyObservation(it->second, obs);
        return;
    }

    // 窗口外（或首次）-> 定案旧事件，另开新的
    //
    // 注意：这里刻意不把旧事件立即返回给调用方，而是留在 pending_ 里等
    // flushExpired() 统一取走——submit 的语义是"吸收观测"，不是"产出事件"。
    // 但旧事件若非空，必须先落定，否则同键的两条记录会互相覆盖。
    if (it != pending_.end()) {
        // 旧事件已过窗口：标记为可刷出。这里把它移到 completed_ 队列。
        completed_.push_back(finalize(it->second, seq_++));
        pending_.erase(it);
    }

    // 建立新 pending
    PendingEvent pending;
    pending.event.site_id = obs.gateway_id.empty() ? "" : "";  // site 由 Store 层补齐
    pending.event.gateway_id = obs.gateway_id;
    pending.event.hci_index = obs.hci_index;
    pending.event.protocol = WirelessProtocol::Bluetooth;
    pending.event.device_address = obs.device_address;
    pending.event.address_type = obs.address_type;
    pending.event.event_type = obs.event_type;
    pending.event.timestamp_ms = obs.timestamp_ms;
    applyObservation(pending, obs);

    // 容量保护：超过上限时强制定案最老的一条，防止内存无界增长
    if (pending_.size() >= cfg_.max_pending) {
        auto oldest = pending_.begin();
        for (auto i = pending_.begin(); i != pending_.end(); ++i) {
            if (i->second.last_obs_ms < oldest->second.last_obs_ms) oldest = i;
        }
        completed_.push_back(finalize(oldest->second, seq_++));
        pending_.erase(oldest);
    }

    pending_.emplace(makeKey(obs), std::move(pending));
}

// ============================================================================
// 原因定案优先级
// ============================================================================

int BtEventNormalizer::reasonRank(const RawBtObservation& obs) {
    // mgmt 层的原始码（MGMT_DEV_DISCONN_* 域）—— 最权威的事实来源
    if (obs.raw_reason_code.has_value() && obs.source == EvidenceSource::KernelMgmt) {
        return 3;
    }
    // 其余来源携带的原始码（HCI error 域，如 hci_disconnect 的 reason）
    // 原始码是事实，必须排在推断 hint 之上——否则先到的 raw 会被后到的 hint 覆盖
    if (obs.raw_reason_code.has_value()) {
        return 2;
    }
    // supplemental hook 带来归一化原因（如 hci_conn_timeout -> ConnectionTimeout）
    if (obs.reason_hint != DisconnectReason::Unknown) {
        return 1;
    }
    return 0;
}

// ============================================================================
// 观测 -> pending 事件
// ============================================================================

void BtEventNormalizer::applyObservation(PendingEvent& pending, const RawBtObservation& obs) {
    // 事件时间为窗口中**最早**一条观测的时刻：现实故障发生在最早观测到的那一刻，
    // 而不是最后一条证据到达的时刻。
    if (pending.evidence.empty() || obs.timestamp_ms < pending.event.timestamp_ms) {
        pending.event.timestamp_ms = obs.timestamp_ms;
        pending.event.monotonic_ns = obs.monotonic_ns;
    }
    if (obs.timestamp_ms > pending.last_obs_ms) {
        pending.last_obs_ms = obs.timestamp_ms;
    }

    // RSSI：只取第一个有值的观测。断连瞬间的链路质量比最后一条证据更有诊断价值。
    if (!pending.event.rssi_at_event_dbm.has_value() && obs.rssi_dbm.has_value()) {
        pending.event.rssi_at_event_dbm = obs.rssi_dbm;
    }

    // 原因定案：仅当本条观测的优先级严格高于当前定案时才覆盖。
    // 这保证 mgmt 的原始 reason 不会被后到的 supplemental hint 冲掉。
    const int rank = reasonRank(obs);
    if (rank > pending.reason_rank) {
        pending.reason_rank = rank;
        pending.event.source = obs.source;
        pending.event.source_detail = obs.source_detail;
        if (obs.raw_reason_code.has_value()) {
            // 原始 code 无损保存，归一化解释由**按来源域**的映射函数给出：
            //   KernelMgmt -> MGMT_DEV_DISCONN_*（内核 mgmt 枚举，非 HCI error）
            //   其余       -> HCI error code
            // 两个域的取值空间完全不同（如 0x02 在 mgmt 域=本地断开，
            // 在 HCI 域=Unknown Connection Identifier），混用会得出错误原因。
            pending.event.raw_reason_code = *obs.raw_reason_code;
            pending.event.reason =
                (obs.source == EvidenceSource::KernelMgmt)
                    ? disconnectReasonFromMgmtCode(*obs.raw_reason_code)
                    : disconnectReasonFromHciCode(*obs.raw_reason_code);
        } else if (obs.reason_hint != DisconnectReason::Unknown) {
            // 该来源没有原始 code（如 hci_conn_timeout），只用它的归一化结论
            pending.event.reason = obs.reason_hint;
        }
    }

    // 无条件追加原始证据：优先级只影响 canonical 字段，不影响证据留存
    pending.evidence.push_back(obs);
}

// ============================================================================
// 定案
// ============================================================================

WirelessDeviceEvent BtEventNormalizer::finalize(PendingEvent& pending, uint64_t seq) {
    WirelessDeviceEvent ev = pending.event;

    // event_id = <prefix>_<实例随机码>_<seq>：进程内单调、跨进程（服务重启）不碰撞。
    // device_events.event_id 是 UNIQUE 且 INSERT OR IGNORE——跨重启重复即静默丢事件，
    // 所以唯一性必须在生成方保证（早期版本只有 prefix+seq，重启后必撞，已修）。
    std::ostringstream id;
    id << cfg_.event_id_prefix << "_" << instance_nonce_ << "_" << seq;
    ev.event_id = id.str();

    // 拼接 raw_evidence 数组
    std::string details;
    for (const auto& obs : pending.evidence) {
        details = appendRawEvidence(details, obs);
    }
    ev.details_json = details;

    // 采集层不做诊断：suspected_cause 恒为空，
    // 由 Phase 2/3 的 LinkAnomalyDetector / SiteIncidentCorrelator 填充。
    ev.suspected_cause = std::nullopt;

    ++normalized_total_;
    return ev;
}

// ============================================================================
// 刷出
// ============================================================================

std::vector<WirelessDeviceEvent> BtEventNormalizer::flushExpired(uint64_t now_ms) {
    std::lock_guard<std::mutex> lock(mu_);

    std::vector<WirelessDeviceEvent> out = std::move(completed_);
    completed_.clear();

    for (auto it = pending_.begin(); it != pending_.end();) {
        if (now_ms > it->second.last_obs_ms + cfg_.merge_window_ms) {
            out.push_back(finalize(it->second, seq_++));
            it = pending_.erase(it);
        } else {
            ++it;
        }
    }
    return out;
}

std::vector<WirelessDeviceEvent> BtEventNormalizer::flushAll() {
    std::lock_guard<std::mutex> lock(mu_);

    std::vector<WirelessDeviceEvent> out = std::move(completed_);
    completed_.clear();

    for (auto& kv : pending_) {
        out.push_back(finalize(kv.second, seq_++));
    }
    pending_.clear();
    return out;
}

