46	bool BtDataPathAnalyzer::init(const std::string& bpfObjectPath, const std::string& controller) {
47	    std::lock_guard<std::mutex> lock(mutex_);
48	    controller_id_ = controller.empty() ? "hci0" : controller;
49	    bpfObjectPath_ = bpfObjectPath;
50	    lastError_.clear();
51	    state_ = EbpfMonitorState::Initializing;
52	    stateSupport_.setState(EbpfMonitorState::Initializing, false, "loading bt_hci_traffic BPF object");
53	
54	    bpfObj_ = bpf_object__open(bpfObjectPath.c_str());
55	    if (!bpfObj_) {
56	        lastError_ = "bpf_object__open failed for " + bpfObjectPath + ": " + std::string(strerror(errno));
57	        LOG_WARNING(LogModule::BLUETOOTH, "BtDataPathAnalyzer: " << lastError_ << " — fallback mode");
58	        state_ = EbpfMonitorState::Fallback;
59	        stateSupport_.setState(EbpfMonitorState::Fallback, false, lastError_);
60	        return false;
61	    }
62	
63	    if (bpf_object__load(bpfObj_) != 0) {
64	        lastError_ = "bpf_object__load failed: " + std::string(strerror(errno));
65	        LOG_WARNING(LogModule::BLUETOOTH, "BtDataPathAnalyzer: " << lastError_ << " — fallback mode");
66	        bpf_object__close(bpfObj_);
67	        bpfObj_ = nullptr;
68	        state_ = EbpfMonitorState::Fallback;
69	        stateSupport_.setState(EbpfMonitorState::Fallback, false, lastError_);
70	        return false;
71	    }
72	
73	    mapFd_ = bpf_object__find_map_fd_by_name(bpfObj_, "bt_acl_traffic");
74	    globalMapFd_ = bpf_object__find_map_fd_by_name(bpfObj_, "bt_acl_global_stats");
75	
76	    if (mapFd_ < 0) {
77	        lastError_ = "Failed to find 'bt_acl_traffic' map in BPF object";
78	        LOG_WARNING(LogModule::BLUETOOTH, "BtDataPathAnalyzer: " << lastError_);
79	        bpf_object__close(bpfObj_);
80	        bpfObj_ = nullptr;
81	        state_ = EbpfMonitorState::Fallback;
82	        stateSupport_.setState(EbpfMonitorState::Fallback, false, lastError_);
83	        return false;
84	    }
85	
86	    // 挂载 TX 与 RX kprobe 探针
87	    bpf_program* prog_tx = bpf_object__find_program_by_name(bpfObj_, "bt_hci_send_frame");
88	    bpf_program* prog_rx = bpf_object__find_program_by_name(bpfObj_, "bt_hci_recv_frame");
89	
90	    int attached_count = 0;
91	    std::string hooks;
92	
93	    if (prog_tx) {
94	        link_tx_ = bpf_program__attach(prog_tx);
95	        if (!libbpf_get_error(link_tx_)) {
96	            attached_count++;
97	            hooks += "kprobe/hci_send_frame";
98	        } else {
99	            link_tx_ = nullptr;
100	        }
101	    }
102	
103	    if (prog_rx) {
104	        link_rx_ = bpf_program__attach(prog_rx);
105	        if (!libbpf_get_error(link_rx_)) {
106	            attached_count++;
107	            if (!hooks.empty()) hooks += ",";
108	            hooks += "kprobe/hci_recv_frame";
109	        } else {
110	            link_rx_ = nullptr;
111	        }
112	    }
113	
114	    if (attached_count == 0) {
115	        lastError_ = "All kprobe attach attempts failed (hci_send_frame, hci_recv_frame)";
116	        LOG_WARNING(LogModule::BLUETOOTH, "BtDataPathAnalyzer: " << lastError_ << " — fallback mode");
117	        bpf_object__close(bpfObj_);
118	        bpfObj_ = nullptr;
119	        mapFd_ = -1;
120	        globalMapFd_ = -1;
121	        state_ = EbpfMonitorState::Fallback;
122	        stateSupport_.setState(EbpfMonitorState::Fallback, false, lastError_);
123	        return false;
124	    }
125	
126	    attachedHookName_ = hooks;
127	    state_ = EbpfMonitorState::Attached;
128	    stateSupport_.setState(EbpfMonitorState::Attached, true, attachedHookName_);
129	    LOG_INFO(LogModule::BLUETOOTH, "BtDataPathAnalyzer attached successfully: " << attachedHookName_);
130	    return true;
131	}
