173	bool BtDataPathAnalyzer::readRawMapValue(uint16_t handle, RawAclTrafficVal* out) const {
174	    if (!out) return false;
175	    uint32_t raw_h = handle & 0x0FFF;
176	
177	    // 解析控制器序号 (hci0 -> 0)
178	    uint32_t hci_id = 0;
179	    if (controller_id_.rfind("hci", 0) == 0 && controller_id_.size() > 3) {
180	        try {
181	            hci_id = static_cast<uint32_t>(std::stoi(controller_id_.substr(3)));
182	        } catch (...) {
183	            hci_id = 0;
184	        }
185	    }
186	    uint32_t map_key = (hci_id << 16) | raw_h;
187	
188	    if (mapFd_ >= 0) {
189	        int ret = bpf_map_lookup_elem(mapFd_, &map_key, out);
190	        if (ret != 0 && hci_id == 0) {
191	            // 兼容可能单以 handle 为 key 的老版本 Map 布局
192	            ret = bpf_map_lookup_elem(mapFd_, &raw_h, out);
193	        }
194	        return (ret == 0);
195	    }
196	
197	    // 内存测试桩回退 (优先复合 key，后退回 raw handle)
198	    auto it = mock_map_.find(map_key);
199	    if (it != mock_map_.end()) {
200	        *out = it->second;
201	        return true;
202	    }
203	    auto it_raw = mock_map_.find(raw_h);
204	    if (it_raw != mock_map_.end()) {
205	        *out = it_raw->second;
206	        return true;
207	    }
208	    return false;
209	}
