227	size_t BtDataPathAnalyzer::pruneStaleEntries(const std::set<uint16_t>& live_handles) {
228	    std::lock_guard<std::mutex> lock(mutex_);
229	    size_t pruned = 0;
230	
231	    // 内核 Map 条目遍历（key 可能是复合 key，取低 12 位与活跃集比对）
232	    if (mapFd_ >= 0) {
233	        std::vector<uint32_t> dead_keys;
234	        uint32_t key = 0, next_key = 0;
235	        int ret = bpf_map_get_next_key(mapFd_, nullptr, &next_key);
236	        while (ret == 0) {
237	            key = next_key;
238	            uint16_t h = static_cast<uint16_t>(key & 0x0FFF);
239	            if (live_handles.find(h) == live_handles.end()) {
240	                dead_keys.push_back(key);
241	            }
242	            ret = bpf_map_get_next_key(mapFd_, &key, &next_key);
243	        }
244	        for (uint32_t k : dead_keys) {
245	            if (bpf_map_delete_elem(mapFd_, &k) == 0) {
246	                pruned++;
247	                last_samples_.erase(static_cast<uint16_t>(k & 0x0FFF));
248	            }
249	        }
250	    }
251	
252	    // 内存测试桩同步清理
253	    for (auto it = mock_map_.begin(); it != mock_map_.end(); ) {
254	        uint16_t h = static_cast<uint16_t>(it->first & 0x0FFF);
255	        if (live_handles.find(h) == live_handles.end()) {
256	            last_samples_.erase(h);
257	            it = mock_map_.erase(it);
258	            pruned++;
259	        } else {
260	            ++it;
261	        }
262	    }
263	
264	    if (pruned > 0) {
265	        LOG_DEBUG(LogModule::BLUETOOTH, "BtDataPathAnalyzer pruned " << pruned
266	                  << " stale map entries (dead handles)");
267	    }
268	    return pruned;
269	}
