271	std::vector<BtDataPathObservation> BtDataPathAnalyzer::collectObservations(
272	    std::chrono::steady_clock::time_point now_point) {
273	
274	    std::vector<BtDataPathObservation> observations;
275	    std::lock_guard<std::mutex> lock(mutex_);
276	
277	    // 1. 搜集当前存在的所有 Handle
278	    std::vector<uint32_t> handles;
279	
280	    if (mapFd_ >= 0) {
281	        uint32_t key = 0;
282	        uint32_t next_key = 0;
283	        int ret = bpf_map_get_next_key(mapFd_, nullptr, &next_key);
284	        while (ret == 0) {
285	            key = next_key;
286	            handles.push_back(key);
287	            ret = bpf_map_get_next_key(mapFd_, &key, &next_key);
288	        }
289	    } else {
290	        for (const auto& [h, _] : mock_map_) {
291	            handles.push_back(h);
292	        }
293	    }
294	
295	    // 同时补充 tracker 中当前活跃但内核 map 尚未建立条目的连接（保证 0 流量也观测到）
296	    if (tracker_) {
297	        auto active_conns = tracker_->getActiveConnections(controller_id_);
298	        for (const auto& conn : active_conns) {
299	            uint32_t h = conn.key.handle & 0x0FFF;
300	            if (std::find(handles.begin(), handles.end(), h) == handles.end()) {
301	                handles.push_back(h);
302	            }
303	        }
304	    }
305	
306	    // 2. 逐 Handle 提取、核算滑动增量与速率
307	    for (uint32_t raw_h : handles) {
308	        uint16_t h = static_cast<uint16_t>(raw_h & 0x0FFF);
309	        RawAclTrafficVal curr_val{};
310	        readRawMapValue(h, &curr_val);
311	
312	        // 查找 Tracker 身份与代次
313	        uint32_t current_generation = 0;
314	        std::string attribution_scope = "unknown";
315	        std::optional<std::string> device_id = std::nullopt;
316	
317	        if (tracker_) {
318	            auto conn_rec = tracker_->getActiveConnection(controller_id_, h);
319	            if (conn_rec.has_value()) {
320	                current_generation = conn_rec->key.generation;
321	                attribution_scope = conn_rec->attribution_scope;
322	                if (!conn_rec->device_mac.empty()) {
323	                    device_id = conn_rec->device_mac;
324	                }
325	            } else {
326	                // 未知具体连接归属，但属于该 controller
327	                attribution_scope = "controller";
328	            }
329	        }
330	
331	        // 增量计算
332	        uint64_t tx_bytes = 0;
333	        uint64_t rx_bytes = 0;
334	        uint64_t tx_pkts = 0;
335	        uint64_t rx_pkts = 0;
336	        uint32_t window_ms = 0;
337	        uint32_t max_gap_ms = 0;
338	
339	        auto last_it = last_samples_.find(h);
340	        if (last_it != last_samples_.end()) {
341	            // 防复用检查：若代次变化或累计计数回绕（如重启），重置增量基准
342	            if (last_it->second.generation == current_generation &&
343	                curr_val.tx_bytes >= last_it->second.val.tx_bytes &&
344	                curr_val.rx_bytes >= last_it->second.val.rx_bytes) {
345	
346	                tx_bytes = curr_val.tx_bytes - last_it->second.val.tx_bytes;
347	                rx_bytes = curr_val.rx_bytes - last_it->second.val.rx_bytes;
348	                tx_pkts = curr_val.tx_packets - last_it->second.val.tx_packets;
349	                rx_pkts = curr_val.rx_packets - last_it->second.val.rx_packets;
350	
351	                auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
352	                    now_point - last_it->second.time).count();
353	                window_ms = (elapsed > 0) ? static_cast<uint32_t>(elapsed) : 1;
354	            } else {
355	                // 代次跃迁（复用 Handle 或重连）：
356	                // 核心防串号逻辑：旧代次遗留的内核累积计数在此代次被设为 Base 基准，
357	                // 不将历史残留值当作当前新代次的增量，初次跃迁增量归零，彻底杜绝数据串号。
358	                tx_bytes = 0;
359	                rx_bytes = 0;
360	                tx_pkts = 0;
361	                rx_pkts = 0;
362	                window_ms = 1000;
363	            }
364	        } else {
365	            // 首次观测此 Handle：若为首代启动，使用当前值；若当前已为高代次（表明进程重启或晚于建立），
366	            // 设当前内核值为基准，以 0 起步避免把历史值计入本代次首个窗口
367	            if (current_generation <= 1) {
368	                tx_bytes = curr_val.tx_bytes;
369	                rx_bytes = curr_val.rx_bytes;
370	                tx_pkts = curr_val.tx_packets;
371	                rx_pkts = curr_val.rx_packets;
372	            } else {
373	                tx_bytes = 0;
374	                rx_bytes = 0;
375	                tx_pkts = 0;
376	                rx_pkts = 0;
377	            }
378	            window_ms = 1000;
379	        }
380	
381	        // 吞吐率计算（bits/s，ACL payload）
382	        double tx_bps = 0.0;
383	        double rx_bps = 0.0;
384	        if (window_ms > 0) {
385	            tx_bps = (static_cast<double>(tx_bytes) * 8.0 * 1000.0) / window_ms;
386	            rx_bps = (static_cast<double>(rx_bytes) * 8.0 * 1000.0) / window_ms;
387	        }
388	
389	        // 计算最后一次收发时间差（gap）
390	        if (curr_val.last_tx_ktime_ns > 0 && curr_val.last_rx_ktime_ns > 0) {
391	            uint64_t diff_ns = (curr_val.last_tx_ktime_ns > curr_val.last_rx_ktime_ns)
392	                ? (curr_val.last_tx_ktime_ns - curr_val.last_rx_ktime_ns)
393	                : (curr_val.last_rx_ktime_ns - curr_val.last_tx_ktime_ns);
394	            max_gap_ms = static_cast<uint32_t>(diff_ns / 1000000ULL);
395	        }
396	
397	        // 构造纯净 L1 DTO
398	        BtDataPathObservation obs;
399	        obs.observation_type = "BT_HCI_ACL_TRAFFIC";
400	        obs.controller_id = controller_id_;
401	        obs.connection_handle = h;
402	        obs.connection_generation = current_generation;
403	        obs.attribution_scope = attribution_scope;
404	        obs.device_id = device_id;
405	        obs.window_ms = window_ms;
406	        obs.tx_bytes = tx_bytes;
407	        obs.rx_bytes = rx_bytes;
408	        obs.tx_packets = tx_pkts;
409	        obs.rx_packets = rx_pkts;
410	        obs.tx_throughput_bps = tx_bps;
411	        obs.rx_throughput_bps = rx_bps;
412	        obs.max_gap_ms = max_gap_ms;
413	        obs.status = "OBSERVED";
414	        obs.last_tx_ktime_ns = curr_val.last_tx_ktime_ns;
415	        obs.last_rx_ktime_ns = curr_val.last_rx_ktime_ns;
416	
417	        observations.push_back(std::move(obs));
418	
419	        // 更新历史快照
420	        last_samples_[h] = LastSample{curr_val, now_point, current_generation};
421	    }
