1	/**
2	 * @file site_incident_correlator.cpp
3	 * @brief 区域级异常关联器实现
4	 *
5	 * 锁纪律（修改前必须保持）：
6	 *   WirelessEventStore::recordEvent 在**释放自身锁之后**调用 observe()，
7	 *   因此全局的加锁方向恒为
8	 *
9	 *       （无）-> correlator.mutex_ -> DatabaseManager::mutex_
10	 *
11	 *   本文件只按这一方向加锁，绝不反向持有 db 锁再去取 correlator 锁。
12	 *
13	 * 时间纪律：关联窗口与静默期全部以**事件时间**（WirelessDeviceEvent::timestamp_ms）
14	 * 为准。关联器不在内部读墙钟——读时钟会把判定结果绑到调用节奏上，
15	 * 也让单元测试无法确定性地构造时间线。
16	 */
17	
18	#include "site_incident_correlator.hpp"
19	
20	#include <algorithm>
21	#include <cctype>
22	#include <sstream>
23	#include <utility>
24	
25	#include "database_manager.hpp"
26	#include "logger.hpp"
27	
28	namespace weaknet_dbus {
29	
30	namespace {
31	
32	/// incident_id 里内嵌 site_id 时，把非字母数字字符换成 '_'（ID 要可读、可 grep）
33	std::string sanitizeIdPart(const std::string& s) {
34	    std::string out;
35	    out.reserve(s.size());
36	    for (char c : s) {
37	        out.push_back(std::isalnum(static_cast<unsigned char>(c)) ? c : '_');
38	    }
39	    return out.empty() ? std::string("unknown") : out;
40	}
