56	std::vector<SiteIncident> SiteIncidentCorrelator::activeIncidents() const {
57	    std::lock_guard<std::mutex> lock(mutex_);
58	    std::vector<SiteIncident> out;
59	    out.reserve(active_.size());
60	    for (const auto& kv : active_) {
61	        SiteIncident inc = kv.second.incident;
62	        inc.affected_devices = kv.second.deviceCount();
63	        inc.affected_device_ids.clear();
64	        for (const auto& ev : kv.second.event_device) {
65	            inc.affected_device_ids.push_back(ev.second);
66	        }
67	        std::sort(inc.affected_device_ids.begin(), inc.affected_device_ids.end());
68	        inc.affected_device_ids.erase(
69	            std::unique(inc.affected_device_ids.begin(), inc.affected_device_ids.end()),
70	            inc.affected_device_ids.end());
71	        out.push_back(std::move(inc));
72	    }
73	    return out;
74	}
75	
76	size_t SiteIncidentCorrelator::ActiveIncident::deviceCount() const {
77	    // 受影响设备数 = 去重后的 device_key 个数。
78	    // 同一设备的多条事件（如先劣化再断连）只算一台，绝不重复计数。
79	    std::vector<std::string> keys;
80	    keys.reserve(event_device.size());
81	    for (const auto& kv : event_device) keys.push_back(kv.second);
82	    std::sort(keys.begin(), keys.end());
83	    keys.erase(std::unique(keys.begin(), keys.end()), keys.end());
84	    return keys.size();
85	}
