90	
91	std::string SiteIncidentCorrelator::deviceKeyOf(const WirelessDeviceEvent& event) {
92	    // 复用既有复合键的字符串形式（含 protocol 与 address_type）：
93	    // 同一 MAC 的 BR/EDR 与 LE Random 是两条不同身份，绝不能算成一台设备。
94	    WirelessDeviceKey key;
95	    key.site_id = event.site_id;
96	    key.gateway_id = event.gateway_id;
97	    key.hci_index = event.hci_index;
98	    key.protocol = event.protocol;
99	    key.address_type = event.address_type;
100	    key.device_address = event.device_address;
101	    return key.toString();
102	}
103	
104	std::string SiteIncidentCorrelator::makeIncidentId(const std::string& site_id,
105	                                                   const std::string& gateway_id,
106	                                                   uint64_t started_at_ms) const {
107	    // incident_id 是**确定性**的：只由 (site_id, gateway_id, started_at_ms) 决定，
108	    // 刻意**不带**进程实例随机码（对比 device_events.event_id 的做法）。
109	    //
110	    // 原因：重启回放会重新推导出同一份 incident，必须写回同一行（UPSERT）
111	    // 而不是插入新行——否则"重启一次多一起事故"。确定性 ID 让回放天然幂等。
112	    //
113	    // **为什么必须带 gateway_id**：多网关部署下同一个 site 会有多台探针，
114	    // 它们完全可能在相近毫秒各自开一起事故（例如同一次区域干扰被两台网关
115	    // 同时观测到）。若 ID 只含 (site, started_at_ms)，两台网关推导出的
116	    // incident_id 相同，云端 UPSERT 会把两起独立事故合并成一行，证据链互相
117	    // 污染。带上 gateway 后，同一网关切重启依旧幂等，不同网关互不覆盖。
118	    //
119	    // 单网关（1 Gateway = 1 Site，site_id == gateway_id）时行为不变：
120	    // 只是 ID 里多了一段与 site 相同的文本，幂等语义完全保持。
121	    //
122	    // 同一 (site, gateway) 内 started_at_ms 不会重复：新 incident 只能由一条
123	    // 新的合格异常开启（窗口缓冲在产出时清空），其时间戳严格晚于上一起的
124	    // last_event_ms + quiet_window_ms >= 上一轮的 started_at_ms。
125	    std::ostringstream oss;
126	    oss << cfg_.incident_id_prefix << "_" << sanitizeIdPart(site_id)
127	        << "_" << sanitizeIdPart(gateway_id)
128	        << "_" << started_at_ms;
129	    return oss.str();
130	}
131	
132	size_t SiteIncidentCorrelator::activeDeviceCount(uint64_t now_ms) const {
133	    // 动态分母：只统计"活跃设备记忆"里仍然新鲜的设备。
134	    // 绝不使用数据库中的设备总数——一台三个月前离线、再未出现的设备会把比率
135	    // 永久稀释到永不达标（关联器静默失效，且没有任何报错）。
136	    const uint64_t floor_ms =
137	        now_ms > cfg_.active_device_memory_ms ? now_ms - cfg_.active_device_memory_ms : 0;
138	    size_t count = 0;
139	    for (const auto& kv : device_memory_) {
140	        if (kv.second >= floor_ms) ++count;
141	    }
142	    return count;
143	}
144	
145	// ============================================================================
146	// 观察事件
147	// ============================================================================
148	
149	std::optional<SiteIncident> SiteIncidentCorrelator::observe(const WirelessDeviceEvent& event) {
150	    std::lock_guard<std::mutex> lock(mutex_);
151	    if (event.timestamp_ms == 0) return std::nullopt;  // 无时间戳无法参与时空关联
152	    return observeLocked(event, event.timestamp_ms);
153	}
154	
155	std::optional<SiteIncident> SiteIncidentCorrelator::observeLocked(
156	    const WirelessDeviceEvent& event, uint64_t now_ms) {
157	    // 1) 活跃设备记忆：**任何**事件（含非合格、含计划内断开）都说明该设备
158	    //    此刻在现场活跃。分母回答"这片区域此刻有几台设备在被观测"。
159	    device_memory_[deviceKeyOf(event)] = now_ms;
160	
161	    // 2) 先用本事件的时间推进静默期/过期清理（结案早于判定，
162	    //    避免已结案的事故继续吸收证据）。结案结果由 tick() 收集，
163	    //    这里只做状态推进，不把它混进本方法的返回值。
164	    (void)tickLocked(now_ms);
165	
166	    // 3) 合格性判定：非合格异常到此结束（它已贡献了分母，但不构成事故证据）
167	    if (!cfg_.policy.qualify(event)) {
168	        return std::nullopt;
169	    }
170	
171	    const std::string site_key =
172	        event.site_id.empty() ? cfg_.site_id : event.site_id;
173	    auto it = active_.find(site_key);
174	
175	    // 4) 已有活跃 incident：窗口内继续吸收，绝不新开
176	    if (it != active_.end()) {
177	        ActiveIncident& active = it->second;
178	
179	        // 幂等：同一 event_id 只计一次。否则重复投递会把受影响设备数灌水到
180	        // 门槛之上，凭空造出一起"区域事故"。仅刷新活跃时间不改变语义。
181	        if (active.event_device.count(event.event_id) != 0) {
182	            return std::nullopt;
183	        }
184	
185	        if (now_ms <= active.incident.last_event_ms + cfg_.correlation_window_ms) {
186	            const bool was_open = active.incident.state == IncidentState::Open;
187	            mergeInto(active, event);
188	            if (was_open) active.incident.state = IncidentState::Ongoing;
189	            persistLocked(active);
190	            return active.incident;
191	        }
192	
193	        // 超出关联窗口且静默期未满（quiet_window > correlation_window 时才可能）：
194	        // 本事件不是同一事故的延续，先结案再走下面的开新流程。
195	        (void)resolveLocked(active);
196	        active_.erase(it);
197	    }
198	
199	    // 5) 无活跃 incident：累计本次合格异常后重新评估双门槛
200	    SiteIncident opened;
201	    if (!tryOpenLocked(event, now_ms, opened)) {
202	        return std::nullopt;
203	    }
204	    return opened;
205	}
206	
207	// ============================================================================
208	// 静默期推进
209	// ============================================================================
210	
211	std::vector<SiteIncident> SiteIncidentCorrelator::tick(uint64_t now_ms) {
212	    std::lock_guard<std::mutex> lock(mutex_);
213	    return tickLocked(now_ms);
214	}
215	
216	std::vector<SiteIncident> SiteIncidentCorrelator::tickLocked(uint64_t now_ms) {
217	    // 过期清理：关联窗口外的合格异常样本不再参与门槛判定
218	    const uint64_t qualify_floor =
219	        now_ms > cfg_.correlation_window_ms ? now_ms - cfg_.correlation_window_ms : 0;
220	    while (!recent_qualifying_.empty() && recent_qualifying_.front().ts_ms < qualify_floor) {
221	        recent_qualifying_.pop_front();
222	    }
223	    // 活跃设备记忆清理（分母只认新鲜设备）
224	    const uint64_t memory_floor =
225	        now_ms > cfg_.active_device_memory_ms ? now_ms - cfg_.active_device_memory_ms : 0;
226	    for (auto it = device_memory_.begin(); it != device_memory_.end();) {
227	        it = (it->second < memory_floor) ? device_memory_.erase(it) : std::next(it);
228	    }
229	
230	    std::vector<SiteIncident> resolved;
231	    for (auto it = active_.begin(); it != active_.end();) {
232	        // 静默期以事件时间为准：窗口内再无新合格异常 = 这片区域已平静下来。
233	        if (now_ms > it->second.incident.last_event_ms + cfg_.quiet_window_ms) {
234	            resolved.push_back(resolveLocked(it->second));
235	            it = active_.erase(it);
236	        } else {
237	            ++it;
238	        }
239	    }
240	    return resolved;
241	}
242	
243	// ============================================================================
244	// 开 / 并入 / 结案
245	// ============================================================================
246	
247	bool SiteIncidentCorrelator::tryOpenLocked(const WirelessDeviceEvent& event,
248	                                           uint64_t now_ms,
249	                                           SiteIncident& out) {
250	    // 本条合格异常先进入窗口缓冲，再统计窗口内的受影响设备集合。
251	    recent_qualifying_.push_back(
252	        QualifyingSample{now_ms, event.event_id, deviceKeyOf(event)});
253	
254	    std::map<std::string, std::string> event_device;  // event_id -> device_key
255	    uint64_t earliest_ms = now_ms;
256	    uint64_t latest_ms = now_ms;
257	    for (const auto& sample : recent_qualifying_) {
258	        event_device.emplace(sample.event_id, sample.device_key);
259	        earliest_ms = std::min(earliest_ms, sample.ts_ms);
260	        latest_ms = std::max(latest_ms, sample.ts_ms);
261	    }
262	
263	    const size_t denominator = activeDeviceCount(now_ms);
264	    if (denominator == 0) return false;
265	
266	    std::vector<std::string> keys;
267	    keys.reserve(event_device.size());
268	    for (const auto& kv : event_device) keys.push_back(kv.second);
269	    std::sort(keys.begin(), keys.end());
270	    keys.erase(std::unique(keys.begin(), keys.end()), keys.end());
271	
272	    const double ratio =
273	        static_cast<double>(keys.size()) / static_cast<double>(denominator);
274	
275	    // 双门槛：比例 ∧ 绝对数。单设备异常永远开不出事故——这是
276	    // "一台设备坏了"与"这一片无线环境出了问题"的分界线。
277	    if (keys.size() < cfg_.min_affected_devices) return false;
278	    if (ratio < cfg_.min_affected_ratio) return false;
279	
280	    const std::string site_id = event.site_id.empty() ? cfg_.site_id : event.site_id;
281	    // gateway_id 由 WirelessEventStore 在落库前补齐（store_cfg.gateway_id），
282	    // 因此事件到达关联器时必然非空；这里只做空值兜底以防直接构造的测试事件。
283	    const std::string gateway_id = event.gateway_id.empty() ? cfg_.site_id : event.gateway_id;
284	
285	    ActiveIncident active;
286	    SiteIncident& inc = active.incident;
287	    inc.incident_id = makeIncidentId(site_id, gateway_id, earliest_ms);
288	    inc.site_id = site_id;
289	    inc.gateway_id = gateway_id;
290	    // started_at_ms 取窗口内最早（现实事故从最早那条异常就开始），
291	    // last_event_ms 取窗口内最新——事件流是乱序的（normalizer 合并窗口、
292	    // ringbuf 消费批次都会让早时间戳晚到），两条都必须按窗口极值算，
293	    // 不能用"本条事件"的时刻：否则乱序达阈时静默期起算点会提前。
294	    inc.started_at_ms = earliest_ms;
295	    inc.last_event_ms = latest_ms;
296	    inc.resolved_at_ms = std::nullopt;
297	    inc.affected_devices = keys.size();
298	    inc.state = IncidentState::Open;
299	    // 采集与关联层不做诊断：恒为 nullopt，由 Phase 4+ 的诊断器填充。
300	    inc.suspected_cause = std::nullopt;
301	    active.event_device = std::move(event_device);
302	
303	    ++total_incidents_;
304	    persistLocked(active);
305	
306	    // 窗口缓冲已被本次事故消费：后续事故必须重新累积证据，
307	    // 否则同一批旧样本会把下一轮事故立刻"扶着"开出来。
308	    recent_qualifying_.clear();
309	
310	    out = inc;
311	    active_.emplace(site_id, std::move(active));
312	    return true;
313	}
314	
315	void SiteIncidentCorrelator::mergeInto(ActiveIncident& active,
316	                                       const WirelessDeviceEvent& event) {
317	    active.event_device[event.event_id] = deviceKeyOf(event);
318	
319	    // last_event_ms 只右移，绝不因迟到事件回退（回退会让静默期提前结束）
320	    if (event.timestamp_ms > active.incident.last_event_ms) {
321	        active.incident.last_event_ms = event.timestamp_ms;
322	    }
323	    // started_at_ms 取最早：事故从最早那条异常开始，而不是"达标那一刻"
324	    if (event.timestamp_ms < active.incident.started_at_ms) {
325	        active.incident.started_at_ms = event.timestamp_ms;
326	    }
327	    active.incident.affected_devices = active.deviceCount();
328	    active.incident.suspected_cause = std::nullopt;  // 关联层不产出推断
329	}
330	
331	SiteIncident SiteIncidentCorrelator::resolveLocked(ActiveIncident& active) {
332	    // 结案时刻 = 最后一条证据 + 静默窗口：静默期满才敢说"事故结束"。
333	    // 用"当前时刻"会让恢复时长依赖于调用节奏，也让回放无法确定性重演。
334	    active.incident.state = IncidentState::Resolved;
335	    active.incident.resolved_at_ms =
336	        active.incident.last_event_ms + cfg_.quiet_window_ms;
337	    active.incident.affected_devices = active.deviceCount();
338	
339	    persistLocked(active);
340	
341	    // 本起事故的证据窗口已封存；后续事故必须重新累积。
342	    recent_qualifying_.clear();
343	    return active.incident;
344	}
345	
346	void SiteIncidentCorrelator::persistLocked(const ActiveIncident& active) {
347	    if (!db_) return;
348	
349	    const SiteIncident& inc = active.incident;
350	    const bool ok = db_->upsertSiteIncident(
351	        inc.incident_id,
352	        inc.site_id,
353	        inc.gateway_id,
354	        static_cast<int64_t>(inc.started_at_ms),
355	        static_cast<int64_t>(inc.last_event_ms),
356	        inc.resolved_at_ms.has_value()
357	            ? std::optional<int64_t>(static_cast<int64_t>(*inc.resolved_at_ms))
358	            : std::nullopt,
359	        static_cast<int64_t>(active.deviceCount()),
360	        toString(inc.state),
361	        inc.suspected_cause);
362	    if (!ok) {
363	        LOG_WARNING(LogModule::BLUETOOTH,
364	                    "SiteIncidentCorrelator: failed to persist incident "
365	                        << inc.incident_id);
366	    }
367	
368	    // 事件回链：每条 SiteIncident 都必须能追溯到构成它的 DeviceEvent
369	    // （可追溯性是工业诊断的基本要求）。INSERT OR IGNORE 使回放/重试天然幂等。
370	    for (const auto& kv : active.event_device) {
371	        const bool linked = db_->insertSiteIncidentEvent(inc.incident_id, kv.first);
372	        if (!linked) {
373	            LOG_WARNING(LogModule::BLUETOOTH,
374	                        "SiteIncidentCorrelator: failed to link event " << kv.first
375	                            << " to incident " << inc.incident_id);
376	        }
377	    }
378	}
379	
380	// ============================================================================
381	// 重启回放
382	// ============================================================================
383	
384	size_t SiteIncidentCorrelator::recoverFromStore(uint64_t now_ms) {
385	    std::lock_guard<std::mutex> lock(mutex_);
386	    if (!db_) return 0;
387	
388	    // 回放窗口 = 关联窗口 + 静默窗口：只有落在这个区间内的事件才可能属于
389	    // "此刻仍然活跃"的 incident。回放的是**事件**而不是 incident 行——
390	    // 跨重启连续性由重新推导保证，从而不存在"内存态与库中行不一致"。
391	    const uint64_t span = cfg_.correlation_window_ms + cfg_.quiet_window_ms;
392	    const int64_t since_ms = now_ms > span ? static_cast<int64_t>(now_ms - span) : 0;
393	
394	    // 结案下限：该现场最近一次结案之后的事件才属于新证据。没有这道闸门，
395	    // 回放会把已结案的 incident 重新拉回活跃态（RESOLVED 行被 UPSERT 回 OPEN），
396	    // 即"重启复活旧事故"。
397	    const int64_t resolved_floor = db_->queryLatestIncidentResolvedAt(cfg_.site_id);
398	    const int64_t from_ms = std::max(since_ms, resolved_floor);
399	
400	    std::vector<WirelessDeviceEvent> events =
401	        db_->loadDeviceEventsForReplay(from_ms, static_cast<int64_t>(now_ms));
402	
403	    // 先清空内存态再重放：回放是"重新推导"，不是"叠加"。否则残留的活跃
404	    // incident 会让重放出的事件被并入一个本不该继续存在的事故。
405	    active_.clear();
406	    recent_qualifying_.clear();
407	    device_memory_.clear();
408	
409	    for (const auto& ev : events) {
410	        (void)observeLocked(ev, ev.timestamp_ms);
411	    }
412	    // 重放结束后以当前时刻推进一次：真正已经静默下来的事故在此结案，
413	    // 不会因为"回放时最后一条证据还没过期"就被误判为仍然活跃。
414	    (void)tickLocked(now_ms);
415	
416	    LOG_INFO(LogModule::BLUETOOTH,
417	             "SiteIncidentCorrelator: replayed " << events.size()
418	                 << " device events since " << from_ms << "ms; active incidents="
419	                 << active_.size());
420	    return active_.size();
421	}
422	
423	// ============================================================================
424	// 查询
425	// ============================================================================
426	
427	std::string SiteIncidentCorrelator::queryPersisted(const std::string& state,
428	                                                   int64_t start_ms,
429	                                                   int64_t end_ms,
430	                                                   int limit,
431	                                                   bool include_devices) const {
432	    if (!db_) return "[]";
433	    // 刻意不持有本类 mutex_：DB 查询走 DatabaseManager 自己的锁，
434	    // 与 WirelessEventStore::queryPersisted 保持同一纪律（避免嵌套持锁）。
435	    return db_->querySiteIncidents(state, start_ms, end_ms, limit, include_devices);
436	}
