        const std::string uplink_state_path =
            resolveDatabasePath(ctx.cfg.data_dir.get())
                .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
                                std::string("history.db").size()) +
            "wireless-uplink-state";
        if (ctx.db_mgr) {
            // 传 sampler 并在读侧持有共享锁：插件可被运行期 disable/restart，
            // 必须在读锁保护下安全采样，避免访问正被析构的监控器。
            ctx.wireless_uplink = std::make_unique<weaknet::EdgeWirelessUplinkExporter>(
                ctx.cfg, *ctx.db_mgr, uplink_state_path,
                [&ctx](std::vector<weaknet_dbus::ProcessNetInfo>* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.process_net_profiler && ctx.process_net_profiler->isAvailable()) {
                        *out = ctx.process_net_profiler->getTopBandwidth(5);
                    }
                },
                [&ctx](weaknet_dbus::DropStatsSummary* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.skb_drop_monitor && ctx.skb_drop_monitor->isAvailable()) {
                        *out = ctx.skb_drop_monitor->getDropStats();
                    }
                },
                [&ctx](weaknet_dbus::TcpRttSummary* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.tcp_rtt_monitor && ctx.tcp_rtt_monitor->isAvailable()) {
                        *out = ctx.tcp_rtt_monitor->getStats();
                    }
                });
            if (ctx.wireless_uplink->start()) {
                LOG_INFO(LogModule::SYSTEM, "edge wireless uplink started");
            }
        } else {
            LOG_WARNING(LogModule::SYSTEM,
                        "无线事实上行未启动：数据库不可用（无持久化事实可上行）");
        }
    }

    // 主线程进入阻塞式 looper
    auto* lp = Looper::current();
    lp->attach(ctx.connection);
    lp->run(&ctx);
    // Looper::run() 退出后，按顺序收尾：
    // 1) 先置 running=false 让所有监控线程退出循环
    // 2) MonitorManager 逐插件请求停止并 join worker，确保不再访问 ctx
    // 3) 之后仅 join 服务级历史持久化线程，再释放共享资源
    LOG_INFO(LogModule::NETWORK, "server shutting down, stopping monitor threads...");
    ctx.running = false;

    // 先由每个插件请求停止并 join 自己的 worker；MonitorManager 是唯一插件停止入口。
    // stop() 内部设置 per-monitor flag，避免全局 running=false 影响其他插件。
    if (ctx.monitor_manager) {
        ctx.monitor_manager->stopAll();
    }

    // 服务级历史线程与受控主动探测线程由 ServerContext 统一 join；插件线程已由各自 stop() 完成。
    if (ctx.active_probe_thread.joinable())             ctx.active_probe_thread.join();

    // 历史持久化线程：只读 weak_mgr 快照 + 写 DB，不依赖其他线程资源，最后 join 最安全。
    // 此前缺失该 join，导致 ~ServerContext 析构时该线程可能仍持 ctx* 访问 → 悬垂/terminate。
    if (ctx.history_thread.joinable())                  ctx.history_thread.join();

    // 停止端侧 AI 调度器：先于 edge_exporter 停止，避免回调访问已析构的 exporter
    if (ctx.edge_ai_scheduler) {
        ctx.edge_ai_scheduler->stop();
        ctx.edge_ai_scheduler.reset();
    }

    // 停止边缘遥测上报：先于 ~ServerContext，保证不再访问 ctx.cfg。
    if (ctx.edge_exporter) {
        ctx.edge_exporter->stop();
        ctx.edge_exporter.reset();
    }

    // 停止无线事实上行：同样必须早于 ~ServerContext 释放 db_mgr，
    // 否则工作线程可能在数据库析构后读取事实。
    if (ctx.wireless_uplink) {
        ctx.wireless_uplink->stop();
        ctx.wireless_uplink.reset();
    }

    // 停止文件日志（在 glog 关闭之前）
    Logger::stopFileLog();

    // 清理glog。资源（DBus 连接 / service / weak_mgr）由 ~ServerContext 统一释放。
    google::ShutdownGoogleLogging();

    // 清理全局网络通信库（libcurl 全局资源释放）
    weaknet::EdgeTelemetryExporter::cleanupGlobal();

    return 0;
}

}  // namespace weaknet_dbus

