320	bool EdgeTelemetryExporter::start() {
321	    if (running_.load()) return true;
322	    if (!config_.edge.enabled.load()) {
323	        LOG_INFO(weaknet_dbus::LogModule::SYSTEM, "边缘遥测上报未启用（edge.enabled=false）");
324	        return false;
325	    }
326	
327	    std::string error;
328	    if (!configComplete(&error)) {
329	        // 半配置状态必须显式失败：否则会以空身份对外发数据。
330	        LOG_ERROR(weaknet_dbus::LogModule::SYSTEM, "边缘遥测上报配置不完整，已保持关闭: " << error);
331	        return false;
332	    }
333	
334	#ifndef WEAKNET_HAVE_TLS
335	    LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
336	              "边缘遥测上报需要 Ed25519 签名，但本构建未编译 OpenSSL，已保持关闭");
337	    return false;
338	#else
339	    // 启动即验证私钥可用：把"密钥配错"暴露在启动日志里，而不是每轮上报
340	    // 都失败却只留下噪音。
341	    {
342	        std::string key_error;
343	        EVP_PKEY* probe = loadEd25519PrivateKey(config_.edge.private_key_path.get(), &key_error);
344	        if (!probe) {
345	            LOG_ERROR(weaknet_dbus::LogModule::SYSTEM, "边缘遥测上报私钥不可用，已保持关闭: " << key_error);
346	            return false;
347	        }
348	        EVP_PKEY_free(probe);
349	    }
350	
