80	    int fd = ::open(tmp_path.c_str(), O_WRONLY);
81	    if (fd >= 0) {
82	        ::fsync(fd);
83	        ::close(fd);
84	    }
85	
86	    if (std::rename(tmp_path.c_str(), state_path_.c_str()) != 0) {
