93	uint64_t NetworkEpochStore::open() {
94	    uint64_t previous = 0;
95	    const bool have_state = readState(&previous);
96	
97	    // 文件是否存在，决定"读不出值"属于哪种情形：
98	    // 文件在 ⇒ 内容损坏；文件不在 ⇒ 真正的首次运行。
99	    // 两者绝不能混为一谈——把损坏当首次会让代次退回 1，
100	    // 而 epoch=1 的历史键几乎必然已存在，等于重新触发数据丢失。
101	    std::ifstream probe(state_path_);
102	    const bool file_exists = probe.is_open();
103	    probe.close();
104	
105	    uint64_t next = 0;
106	    if (have_state) {
107	        next = previous + 1;
108	    } else if (file_exists) {
109	        next = kRecoveryEpoch;
110	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
111	                    "network epoch state unreadable, restarting from " << kRecoveryEpoch
112	                                                                      << ": " << state_path_);
113	    } else {
114	        // 首次运行：与既有部署的 (epoch=1, seq=N) 历史保持一致，
115	        // 不制造一次性的键空间跳变。
116	        next = 1;
117	    }
118	
119	    if (!writeState(next)) {
120	        persisted_ = false;
121	        // 写盘失败 ⇒ 本次用掉的代次无法被记住，下次重启就会重算出同一个值，
122	        // 两个 run 共用 (device, epoch, seq) 键空间，云端幂等去重会静默丢弃遥测。
123	        // 因此无论初值是 1 还是历史值 +1，都升到恢复位跳出冲突域；
124	        // 但仍继续上报——停止上报的代价比一次代次跳变大得多。
125	        if (next < kRecoveryEpoch) {
126	            next = kRecoveryEpoch;
127	        }
128	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
129	                    "network epoch state could not be persisted: " << state_path_);
130	    } else {
131	        persisted_ = true;
132	    }
133	
134	    current_ = next;
135	    LOG_INFO(weaknet_dbus::LogModule::SYSTEM, "network epoch for this run: " << current_);
136	    return current_;
