275	WirelessUplinkPayload EdgeWirelessUplinkExporter::selectSince(const WirelessUplinkPayload& all,
276	                                                              uint64_t watermark_ms) {
277	    WirelessUplinkPayload out = all;
278	    out.events.clear();
279	    for (const auto& ev : all.events) {
280	        if (ev.timestamp_ms > watermark_ms) out.events.push_back(ev);
281	    }
282	    return out;
283	}
