305	bool EdgeWirelessUplinkExporter::configComplete(std::string* error) const {
306	    if (!config_.edge.enabled.load()) {
307	        *error = "edge.enabled=false";
308	        return false;
309	    }
310	    if (config_.edge.url.get().empty()) {
311	        *error = "edge.url 未配置";
312	        return false;
313	    }
314	    if (config_.edge.device_id.get().empty()) {
315	        *error = "edge.device_id 未配置";
316	        return false;
317	    }
318	    if (config_.edge.tenant.get().empty() || config_.edge.token.get().empty() ||
319	        config_.edge.key_id.get().empty() || config_.edge.private_key_path.get().empty()) {
