326	bool EdgeWirelessUplinkExporter::start() {
327	    if (running_.load()) return true;
328	
329	    std::string error;
330	    if (!configComplete(&error)) {
331	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
332	                    "无线事实上行未启用: " << error);
333	        return false;
334	    }
335	#ifndef WEAKNET_HAVE_TLS
336	    LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
337	              "无线事实上行需要 Ed25519 签名，但本构建未编译 OpenSSL，已保持关闭");
338	    return false;
339	#else
340	#ifndef WEAKNET_HAVE_CURL
341	    LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
342	              "无线事实上行需要 libcurl，但本构建未链接，已保持关闭");
343	    return false;
344	#else
345	    watermark_ms_.store(loadWatermark());
346	    stop_requested_.store(false);
347	    running_.store(true);
348	    thread_ = std::thread(&EdgeWirelessUplinkExporter::run, this);
349	    LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
350	             "无线事实上行已启动: watermark_ms=" << watermark_ms_.load()
351	             << " state=" << state_path_);
352	    return true;
353	#endif
354	#endif
