357	void EdgeWirelessUplinkExporter::stop() {
358	    if (!running_.load() && !thread_.joinable()) return;
359	    stop_requested_.store(true);
360	    if (thread_.joinable()) thread_.join();
361	    running_.store(false);
362	    LOG_INFO(weaknet_dbus::LogModule::SYSTEM, "无线事实上行已停止");
