372	// ============================================================================
373	// 游标
374	// ============================================================================
375	
376	uint64_t EdgeWirelessUplinkExporter::loadWatermark() const {
377	    std::ifstream in(state_path_);
378	    if (!in) return 0;
379	    std::ostringstream oss;
380	    oss << in.rdbuf();
381	    const std::string text = oss.str();
382	
383	    const std::string ev = readUintField(text, "events_ms");
384	    if (ev.empty()) return 0;
385	    try {
386	        return static_cast<uint64_t>(std::stoull(ev));
387	    } catch (...) {
388	        // 损坏即从 0 重扫：重发由服务端幂等吸收，跳发才会真的丢事实。
389	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
390	                    "无线上行游标损坏，从 0 重新扫描: " << state_path_);
391	        return 0;
392	    }
393	}
394	
395	void EdgeWirelessUplinkExporter::storeWatermark(uint64_t value) {
396	    std::ofstream out(state_path_, std::ios::trunc);
397	    if (!out) {
398	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
399	                    "无线上行游标写入失败（下一轮将重发）: " << state_path_);
400	        return;
401	    }
402	    out << "events_ms=" << value << "\n";
403	}
404	
405	// ============================================================================
406	// 采集
407	// ============================================================================
408	
409	bool EdgeWirelessUplinkExporter::collect(WirelessUplinkPayload* out, std::string* error) {
410	    const uint64_t watermark = watermark_ms_.load();
411	    out->device_id = config_.edge.device_id.get();
412	    out->watermark_ms = watermark;
413	
414	    const int64_t since = static_cast<int64_t>(watermark);
415	    const int64_t now_ms = static_cast<int64_t>(
416	        std::chrono::duration_cast<std::chrono::milliseconds>(
417	            std::chrono::system_clock::now().time_since_epoch())
418	            .count());
419	
420	    // 事件：只取晚于游标的（严格大于，避免重发已确认项）
421	    const auto events = db_.loadDeviceEventsForReplay(since + 1, now_ms);
422	    if (events.size() > EDGE_WIRELESS_MAX_EVENTS_PER_BATCH) {
423	        out->events.assign(events.begin(),
424	                           events.begin() + EDGE_WIRELESS_MAX_EVENTS_PER_BATCH);
425	    } else {
426	        out->events = events;
427	    }
428	
429	    // 事故：按最近演化时间取（LAST_EVENT 会前进，同一事故被反复 UPSERT）
430	    auto incidents = db_.loadSiteIncidentsSince(since, EDGE_WIRELESS_MAX_INCIDENTS_PER_BATCH);
431	    out->incident_evidence.reserve(incidents.size());
432	    for (const auto& inc : incidents) {
433	        out->incident_evidence.push_back(db_.loadIncidentEvidenceEventIds(inc.incident_id));
434	    }
435	    out->incidents = std::move(incidents);
436	
437	    // 基线：按画像更新时间推进（与事件游标共用同一水位的近似上界即可：
438	    // 基线是派生事实，重发代价低，宁可多发不可漏发）
439	    auto baselines = db_.loadDeviceBaselinesSince(since, EDGE_WIRELESS_MAX_BASELINES_PER_BATCH);
440	    out->baselines = std::move(baselines);
441	
442	    // 深度内核快照：进程画像 Top N 与协议栈丢包归因。
443	    // sampler 为空或未抓取到有效数据时诚实跳过该维度，绝不伪造空观测。
444	    if (profiler_sampler_) {
445	        profiler_sampler_(&out->top_processes);
446	    }
447	    if (drop_sampler_) {
448	        weaknet_dbus::DropStatsSummary drop_stats;
449	        drop_sampler_(&drop_stats);
450	        if (drop_stats.totalDrops > 0 || !drop_stats.topReasons.empty()) {
451	            if (drop_stats.topReasons.size() > 5) {
452	                drop_stats.topReasons.resize(5);
453	            }
454	            out->drop_stats = std::move(drop_stats);
455	        }
456	    }
457	    if (tcp_rtt_sampler_) {
458	        weaknet_dbus::TcpRttSummary rtt_stats;
459	        tcp_rtt_sampler_(&rtt_stats);
460	        if (rtt_stats.totalSamples > 0 || !rtt_stats.topConns.empty()) {
461	            if (rtt_stats.topConns.size() > 10) {
462	                rtt_stats.topConns.resize(10);
463	            }
464	            out->tcp_rtt_stats = std::move(rtt_stats);
465	        }
466	    }
467	
468	    // 环境窗口的时间轴：**只由稀疏事实（事件/事故）决定**，不用墙钟，
469	    // 也不用基线画像时间。
470	    //
471	    // 用墙钟会让每一轮产生新的 to_ms → 云端 window_id 每轮都变 → 每 10 秒新建
472	    // 一行（实测 10 分钟涨到 606 行）。而基线画像 `updated_at_ms` 每轮都会刷新
473	    // （设备一直被重新观测），把它算进来同样会让窗口每轮漂移——实测只降到
474	    // 3 行/分钟。
475	    //
476	    // 事件与事故才是真正的稀疏事实：没有它们时窗口恒为 (0, 0)，云端 UPSERT
477	    // 到同一行；有新事件时才产生新窗口。这既让行数与真实事实量成正比，
478	    // 也让回放一批旧事件时窗口回到对应时间段，不会把历史事实伪造成"当前窗口"。
479	    uint64_t newest_fact_ms = 0;
480	    for (const auto& ev : out->events) newest_fact_ms = std::max(newest_fact_ms, ev.timestamp_ms);
481	    for (const auto& inc : out->incidents) newest_fact_ms = std::max(newest_fact_ms, inc.last_event_ms);
482	    out->env_from_ms = 0;
483	    out->env_to_ms = newest_fact_ms;
484	
485	    if (out->events.empty() && out->incidents.empty() && out->baselines.empty()) {
486	        if (error) *error = "no new facts";
487	        return false;
488	    }
489	    return true;
490	}
491	
492	// ============================================================================
493	// 签名 / 发送
494	// ============================================================================
495	
496	std::string EdgeWirelessUplinkExporter::signBody(const std::string& body,
497	                                                 std::string* error) const {
498	#ifdef WEAKNET_HAVE_TLS
499	    FILE* fp = std::fopen(config_.edge.private_key_path.get().c_str(), "rb");
500	    if (!fp) {
501	        *error = "无法打开私钥: " + config_.edge.private_key_path.get();
502	        return {};
503	    }
504	    EVP_PKEY* key = PEM_read_PrivateKey(fp, nullptr, nullptr, nullptr);
505	    std::fclose(fp);
506	    if (!key) {
507	        *error = "PEM 解析失败";
508	        return {};
509	    }
510	    if (EVP_PKEY_base_id(key) != EVP_PKEY_ED25519) {
511	        EVP_PKEY_free(key);
512	        *error = "私钥不是 Ed25519";
513	        return {};
514	    }
515	
516	    std::string signature_hex;
517	    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
518	    do {
519	        if (!ctx) {
520	            *error = "EVP_MD_CTX_new 失败";
521	            break;
522	        }
523	        if (EVP_DigestSignInit(ctx, nullptr, nullptr, nullptr, key) != 1) {
524	            *error = "EVP_DigestSignInit 失败";
525	            break;
526	        }
527	        size_t sig_len = 0;
528	        if (EVP_DigestSign(ctx, nullptr, &sig_len,
529	                           reinterpret_cast<const unsigned char*>(body.data()),
530	                           body.size()) != 1) {
531	            *error = "签名长度探测失败";
532	            break;
533	        }
534	        std::vector<unsigned char> sig(sig_len);
535	        if (EVP_DigestSign(ctx, sig.data(), &sig_len,
536	                           reinterpret_cast<const unsigned char*>(body.data()),
537	                           body.size()) != 1) {
538	            *error = "签名失败";
539	            break;
540	        }
541	        static const char* kHex = "0123456789abcdef";
542	        signature_hex.reserve(sig_len * 2);
543	        for (size_t i = 0; i < sig_len; ++i) {
544	            signature_hex.push_back(kHex[(sig[i] >> 4) & 0x0F]);
545	            signature_hex.push_back(kHex[sig[i] & 0x0F]);
546	        }
547	    } while (false);
548	
549	    if (ctx) EVP_MD_CTX_free(ctx);
550	    EVP_PKEY_free(key);
551	    return signature_hex;
552	#else
553	    (void)body;
554	    *error = "本构建未编译 OpenSSL，无法签名";
555	    return {};
556	#endif
557	}
558	
559	std::string EdgeWirelessUplinkExporter::uplinkUrl() const {
560	    std::string url = config_.edge.url.get();
561	    const std::string suffix = "/telemetry";
562	    if (url.size() >= suffix.size() &&
563	        url.compare(url.size() - suffix.size(), suffix.size(), suffix) == 0) {
564	        url.replace(url.size() - suffix.size(), suffix.size(), "/wireless-events");
565	    } else {
566	        // 形态不符约定时显式失败，不把事实发到未知端点
567	        url.clear();
568	    }
569	    return url;
570	}
571	
572	bool EdgeWirelessUplinkExporter::postSigned(const std::string& url, const std::string& body,
573	                                            const std::string& signature,
574	                                            std::string* response,
575	                                            std::string* error) const {
576	#ifdef WEAKNET_HAVE_CURL
577	    CURL* curl = curl_easy_init();
578	    if (!curl) {
579	        *error = "curl_easy_init 失败";
580	        return false;
581	    }
582	    struct curl_slist* headers = nullptr;
583	    headers = curl_slist_append(headers, "Content-Type: application/json");
584	    const std::string key_header = "X-Edge-Key-Id: " + config_.edge.key_id.get();
585	    const std::string token_header = "X-Edge-Token: " + config_.edge.token.get();
586	    const std::string tenant_header = "X-Edge-Tenant: " + config_.edge.tenant.get();
587	    const std::string sig_header = "X-Edge-Signature: " + signature;
588	    headers = curl_slist_append(headers, key_header.c_str());
589	    headers = curl_slist_append(headers, token_header.c_str());
590	    headers = curl_slist_append(headers, tenant_header.c_str());
591	    headers = curl_slist_append(headers, sig_header.c_str());
592	
593	    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
594	    curl_easy_setopt(curl, CURLOPT_POST, 1L);
595	    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body.data());
596	    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, static_cast<long>(body.size()));
597	    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
598	    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
599	    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
600	    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS,
601	                     static_cast<long>(config_.edge.timeout_ms.load()));
602	    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT_MS,
603	                     static_cast<long>(config_.edge.timeout_ms.load()));
604	
605	    const CURLcode code = curl_easy_perform(curl);
606	    long http_status = 0;
607	    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_status);
608	    curl_slist_free_all(headers);
609	    curl_easy_cleanup(curl);
610	
611	    if (code != CURLE_OK || http_status < 200 || http_status >= 300) {
612	        *error = std::string("上行失败: ") + curl_easy_strerror(code) +
613	                 " http=" + std::to_string(http_status);
614	        return false;
615	    }
616	    return true;
617	#else
618	    (void)url; (void)body; (void)signature; (void)response;
619	    *error = "本构建未链接 libcurl，无法发送";
620	    return false;
621	#endif
622	}
623	
624	// ============================================================================
625	// 主循环
626	// ============================================================================
627	
628	bool EdgeWirelessUplinkExporter::runOnce(std::string* error) {
629	    WirelessUplinkPayload payload;
630	    if (!collect(&payload, error)) {
631	        return false;
632	    }
633	
634	    std::string body_error;
635	    const std::string body = buildBody(payload, &body_error);
636	    if (body.empty()) {
637	        *error = "序列化失败: " + body_error;
638	        return false;
639	    }
640	
641	    std::string sign_error;
642	    const std::string signature = signBody(body, &sign_error);
643	    if (signature.empty()) {
644	        *error = "签名失败: " + sign_error;
645	        return false;
646	    }
647	
648	    const std::string url = uplinkUrl();
649	    if (url.empty()) {
650	        *error = "wireless-events URL 无法由 edge.url 派生";
651	        return false;
652	    }
653	
654	    std::string response;
655	    if (!postSigned(url, body, signature, &response, error)) {
656	        std::lock_guard<std::mutex> lock(stats_mutex_);
657	        stats_.send_failures++;
658	        return false;
659	    }
660	
661	    // 只有确认送达才推进游标：取本批各行事实时间的最大值。
662	    uint64_t advanced = watermark_ms_.load();
663	    for (const auto& ev : payload.events) {
664	        advanced = std::max(advanced, ev.timestamp_ms);
665	    }
666	    for (const auto& inc : payload.incidents) {
667	        advanced = std::max(advanced, inc.last_event_ms);
668	    }
669	    for (const auto& b : payload.baselines) {
670	        advanced = std::max(advanced, b.updated_at_ms);
671	    }
672	    watermark_ms_.store(advanced);
673	    storeWatermark(advanced);
674	
675	    {
676	        std::lock_guard<std::mutex> lock(stats_mutex_);
677	        stats_.rounds++;
678	        stats_.batches_sent++;
679	        stats_.events_sent += payload.events.size();
680	        stats_.incidents_sent += payload.incidents.size();
681	        stats_.baselines_sent += payload.baselines.size();
682	    }
683	    LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
684	             "无线事实上行成功: events=" << payload.events.size()
685	             << " incidents=" << payload.incidents.size()
686	             << " baselines=" << payload.baselines.size()
687	             << " watermark_ms=" << advanced);
688	    return true;
689	}
690	
691	void EdgeWirelessUplinkExporter::run() {
692	    while (!stop_requested_.load()) {
693	        // 与遥测同款退避：网络长期不通时不要变成紧循环。
694	        uint32_t interval = config_.edge.interval_ms.load();
695	        if (interval < kUplinkIntervalMsMin) interval = kUplinkIntervalMsMin;
696	        if (interval > kUplinkIntervalMsMax) interval = kUplinkIntervalMsMax;
697	
698	        std::string error;
699	        const bool ok = runOnce(&error);
700	        if (!ok) {
701	            // "no new facts" 是正常空转，不记错误日志
702	            if (error != "no new facts") {
703	                LOG_WARNING(weaknet_dbus::LogModule::SYSTEM, "无线事实上行未送达: " << error);
704	                interval = std::min(std::max(interval, 1000u), 10000u);
705	            } else {
706	                interval = std::max(interval, 1000u);
707	            }
708	        } else {
709	            // 成功但可能仍有积压（超过单批上限）：立刻再跑一轮
710	            WirelessUplinkPayload probe;
711	            std::string probe_error;
712	            if (collect(&probe, &probe_error) && !probe.events.empty()) {
713	                continue;
714	            }
715	        }
716	
717	        const auto deadline =
718	            std::chrono::steady_clock::now() + std::chrono::milliseconds(interval);
719	        while (!stop_requested_.load() && std::chrono::steady_clock::now() < deadline) {
720	            std::this_thread::sleep_for(std::chrono::milliseconds(100));
721	        }
722	    }
723	}
724	
725	}  // namespace weaknet
