5	
6	namespace weaknet {
7	
8	/**
9	 * @brief 综合网络体验策略决策引擎 (HR-4)
10	 *
11	 * 核心三维度：IP Reachability, Reliability, Responsiveness
12	 * Advisory 维度：RF Health（不直接降低 Overall Experience；NOT_APPLICABLE 时完全忽略）
13	 *
14	 * 决策顺序（负面证据优先，coverage gate 仅保护 GOOD）：
15	 *   1. Reachability BAD        → BAD
16	 *   2. Reliability BAD         → BAD
17	 *   3. Responsiveness BAD      → DEGRADED
18	 *   4. 任一核心 SLE DEGRADED   → DEGRADED（负面证据可在 PARTIAL coverage 下成立）
19	 *   5. Minimum Core Coverage 不满足 → UNKNOWN
20	 *      （= Reachability known AND (Reliability known OR Responsiveness known)）
21	 *   6. 否则                    → GOOD
22	 *
23	 * NOT_APPLICABLE 的 SLE 不参与 vote、coverage 惩罚、warning 与 primary_issue。
24	 * Warnings 的唯一事实源即本函数产出的 NetworkExperience，下游（DbusService 等）
25	 * 不得再做二次业务判断。
26	 */
27	class OverallPolicy {
28	public:
29	    // 兼容 Phase 1 的重载 (无 dns 参数)
30	    static NetworkExperience decide(const std::string& iface,
31	                                   const SleResult& reach,
32	                                   const SleResult& resp,
33	                                   const SleResult& rel,
34	                                   const SleResult& rf,
35	                                   bool band_conflict = false) {
36	        return decide(iface, reach, resp, rel, rf, SleResult{}, AssessmentProfile::INTERNET_ACCESS, band_conflict);
37	    }
38	
39	    // Phase 2A 完整签名
40	    static NetworkExperience decide(const std::string& iface,
41	                                   const SleResult& reach,
42	                                   const SleResult& resp,
43	                                   const SleResult& rel,
44	                                   const SleResult& rf,
45	                                   const SleResult& dns,
46	                                   AssessmentProfile profile = AssessmentProfile::INTERNET_ACCESS,
47	                                   bool band_conflict = false) {
48	        return decide(iface, reach, resp, rel, rf, dns, SleResult{}, profile, band_conflict);
49	    }
50	
51	    // Stage 2：在 INTERNET_ACCESS 下把 TCP Connect 纳入 required service 链
52	    static NetworkExperience decide(const std::string& iface,
53	                                   const SleResult& reach,
54	                                   const SleResult& resp,
55	                                   const SleResult& rel,
56	                                   const SleResult& rf,
57	                                   const SleResult& dns,
58	                                   const SleResult& tcp_connect,
59	                                   AssessmentProfile profile,
60	                                   bool band_conflict = false) {
61	        return decide(iface, reach, resp, rel, rf, dns, tcp_connect, SleResult{}, SleResult{},
62	                      profile, band_conflict);
63	    }
64	
65	    // Stage 2 完整签名：DNS → TCP → HTTP → Captive Portal
66	    static NetworkExperience decide(const std::string& iface,
67	                                   const SleResult& reach,
68	                                   const SleResult& resp,
69	                                   const SleResult& rel,
70	                                   const SleResult& rf,
71	                                   const SleResult& dns,
72	                                   const SleResult& tcp_connect,
73	                                   const SleResult& http_access,
74	                                   const SleResult& captive_portal,
75	                                   AssessmentProfile profile,
76	                                   bool band_conflict = false) {
77	        return decide(iface, reach, resp, rel, rf, dns, tcp_connect, http_access,
78	                      captive_portal, SleResult{}, SleResult{}, SleResult{}, SleResult{},
79	                      profile, band_conflict);
80	    }
81	
82	    // Stage 2 + Active Probe：受控能力证据（唯一有资格判定 Internet 的
83	    // 服务层来源）与被动 observed experience 分开传入。
84	    static NetworkExperience decide(const std::string& iface,
85	                                   const SleResult& reach,
86	                                   const SleResult& resp,
87	                                   const SleResult& rel,
88	                                   const SleResult& rf,
89	                                   const SleResult& dns,
90	                                   const SleResult& tcp_connect,
91	                                   const SleResult& http_access,
92	                                   const SleResult& captive_portal,
93	                                   const SleResult& active_dns,
94	                                   const SleResult& active_tcp,
95	                                   const SleResult& active_https,
96	                                   const SleResult& active_portal,
97	                                   AssessmentProfile profile,
98	                                   bool band_conflict = false) {
99	        return decide(iface, reach, resp, rel, rf, dns, tcp_connect, SleResult{},
100	                      http_access, captive_portal, active_dns, active_tcp,
101	                      active_https, active_portal, profile, band_conflict);
102	    }
103	
104	    // 含被动 TCP RTT（trace_tcp_probe srtt）的完整签名
105	    static NetworkExperience decide(const std::string& iface,
106	                                   const SleResult& reach,
107	                                   const SleResult& resp,
108	                                   const SleResult& rel,
109	                                   const SleResult& rf,
110	                                   const SleResult& dns,
111	                                   const SleResult& tcp_connect,
112	                                   const SleResult& tcp_rtt,
113	                                   const SleResult& http_access,
114	                                   const SleResult& captive_portal,
115	                                   const SleResult& active_dns,
116	                                   const SleResult& active_tcp,
117	                                   const SleResult& active_https,
118	                                   const SleResult& active_portal,
119	                                   AssessmentProfile profile,
120	                                   bool band_conflict = false) {
121	        NetworkExperience exp;
122	        exp.iface = iface;
123	        exp.assessment_profile = profile;
124	        exp.ip_reachability = reach;
125	        exp.responsiveness = resp;
126	        exp.reliability = rel;
127	        exp.rf_health = rf;
128	        exp.dns_service = dns;
129	        exp.tcp_connect = tcp_connect;
130	        exp.tcp_rtt = tcp_rtt;
131	        exp.http_access = http_access;
132	        exp.captive_portal = captive_portal;
133	        exp.active_dns = active_dns;
134	        exp.active_tcp = active_tcp;
135	        exp.active_https = active_https;
136	        exp.active_portal = active_portal;
137	
138	        const bool reach_app = (reach.applicability == Applicability::APPLICABLE);
139	        const bool resp_app = (resp.applicability == Applicability::APPLICABLE);
140	        const bool rel_app = (rel.applicability == Applicability::APPLICABLE);
141	        const bool dns_app = (dns.applicability == Applicability::APPLICABLE &&
142	                              profile == AssessmentProfile::INTERNET_ACCESS &&
143	                              (dns.state != HealthState::UNKNOWN || dns.coverage != Coverage::NONE));
144	        const bool tcp_app = (tcp_connect.applicability == Applicability::APPLICABLE &&
145	                              profile == AssessmentProfile::INTERNET_ACCESS &&
146	                              (tcp_connect.state != HealthState::UNKNOWN || tcp_connect.coverage != Coverage::NONE));
147	        const bool http_app = (http_access.applicability == Applicability::APPLICABLE &&
148	                               profile == AssessmentProfile::INTERNET_ACCESS &&
149	                               (http_access.state != HealthState::UNKNOWN || http_access.coverage != Coverage::NONE));
150	
151	        // 计算整体 coverage：在适用的核心 SLE 上求值
152	        size_t core_applicable = 0, core_full = 0, core_none = 0;
153	        const SleResult* cores[6] = {&reach, &resp, &rel, &dns, &tcp_connect, &http_access};
154	        const bool core_apps[6] = {reach_app, resp_app, rel_app, dns_app, tcp_app, http_app};
155	        for (size_t i = 0; i < 6; ++i) {
156	            if (!core_apps[i]) continue;
157	            core_applicable++;
158	            if (cores[i]->coverage == Coverage::FULL_FOR_PROFILE) core_full++;
159	            if (cores[i]->coverage == Coverage::NONE) core_none++;
160	        }
161	        if (core_applicable == 0 || core_none == core_applicable) {
162	            exp.overall_coverage = Coverage::NONE;
163	        } else if (core_full == core_applicable) {
164	            exp.overall_coverage = Coverage::FULL_FOR_PROFILE;
165	        } else {
166	            exp.overall_coverage = Coverage::PARTIAL;
167	        }
168	
169	        // Advisory 告警生成
170	        if (rf.applicability == Applicability::APPLICABLE &&
171	            (rf.state == HealthState::DEGRADED || rf.state == HealthState::BAD)) {
172	            exp.warnings.push_back("RF Health is suboptimal (weak signal)");
173	        }
174	        if (band_conflict) {
175	            exp.warnings.push_back("Potential 2.4GHz Wi-Fi and Bluetooth coexistence conflict detected");
176	        }
177	        if (profile == AssessmentProfile::NETWORK_ONLY && dns.applicability == Applicability::APPLICABLE &&
178	            (dns.state == HealthState::DEGRADED || dns.state == HealthState::BAD)) {
179	            exp.warnings.push_back("DNS service issue detected (Advisory under NETWORK_ONLY profile)");
180	        }
181	
182	        // 1. Critical BAD (Reachability 或 Reliability 故障，一票否决)
183	        // SR-5 & 交接文档第 11 节优先级：
184	        // Reachability BAD + DNS BAD -> Overall BAD, Primary=IP_PATH_FAILURE, DNS=symptom
185	        if (reach_app && reach.state == HealthState::BAD) {
186	            exp.overall = HealthState::BAD;
187	            exp.primary_issue = "IP path is unreachable";
188	            if (dns_app && dns.state == HealthState::BAD) {
189	                exp.warnings.push_back("DNS failure suspected to be caused by IP path failure");
190	            }
191	            exp.display_score = 15;
192	            return exp;
193	        }
194	        if (rel_app && rel.state == HealthState::BAD) {
195	            exp.overall = HealthState::BAD;
196	            exp.primary_issue = "Severe packet loss or retransmission";
197	            exp.display_score = 30;
198	            return exp;
199	        }
200	
201	        // DNS BAD：仅当证据属 "host-level resolver capability" 故障时才否决
202	        // INTERNET_ACCESS。本机解析不了名字，上网体验确实受损。
203	        // 若只是单域名 SERVFAIL/REFUSED（capability_level_negative=false），
204	        // 那可能是域名或策略侧问题，无权把 "某域名解析失败" 升级为
205	        // "Internet 不可用" —— 降为警告与证据，不改变 Overall。
206	        if (dns_app && dns.state == HealthState::BAD) {
207	            if (dns.capability_level_negative) {
208	                exp.overall = HealthState::BAD;
209	                exp.primary_issue = "DNS service resolution failure";
210	                exp.display_score = 25;
211	                return exp;
212	            }
213	            exp.warnings.push_back(
214	                "DNS resolution failures observed (per-domain, not resolver capability)");
215	        }
216	
217	        // Active TCP capability：受控目标（由我们选定、应稳定可达）全部失败。
218	        // 这测的是 host-level Internet 能力，不是任意业务端点，
219	        // 因此**有资格**判定 INTERNET_ACCESS。
220	        const bool active_tcp_app = (active_tcp.applicability == Applicability::APPLICABLE &&
221	                                     profile == AssessmentProfile::INTERNET_ACCESS &&
222	                                     active_tcp.capability_level_negative);
223	        if (active_tcp_app && active_tcp.state == HealthState::BAD) {
224	            exp.overall = HealthState::BAD;
225	            exp.primary_issue = "Internet transport capability failed (all controlled targets)";
226	            exp.display_score = 18;
227	            return exp;
228	        }
229	
230	        // Active DNS capability：所有受控目标名称解析失败
231	        const bool active_dns_app = (active_dns.applicability == Applicability::APPLICABLE &&
232	                                     profile == AssessmentProfile::INTERNET_ACCESS &&
233	                                     active_dns.capability_level_negative);
234	        if (active_dns_app && active_dns.state == HealthState::BAD) {
235	            exp.overall = HealthState::BAD;
236	            exp.primary_issue = "Internet name resolution capability failed (all controlled targets)";
237	            exp.display_score = 20;
238	            return exp;
239	        }
240	
241	        // Active Captive Portal：受控 oracle 在 ≥2 个独立故障域上给出一致信号。
242	        //
243	        // 排在 Active HTTPS 之前，因为门户拦截本身会导致 TLS 证书校验失败
244	        // （被中间人替换的证书）。若先判 HTTPS 能力失败，门户场景就会被
245	        // 误报成"加密通道不可用"，根因定位错误。
246	        //
247	        // 无受控 oracle（scope == NO_CAPABILITY）时无权决策，
248	        // 只能由证据链展示 UNKNOWN。
249	        const bool active_portal_app =
250	            (active_portal.applicability == Applicability::APPLICABLE &&
251	             profile == AssessmentProfile::INTERNET_ACCESS &&
252	             active_portal.scope != EvidenceScope::NO_CAPABILITY &&
253	             active_portal.capability_level_negative);
254	        if (active_portal_app && active_portal.state == HealthState::BAD) {
255	            exp.overall = HealthState::BAD;
256	            exp.primary_issue = "Captive portal interception detected (controlled oracle)";
257	            exp.display_score = 20;
258	            return exp;
259	        }
260	
261	        // Active HTTPS capability：受控目标全部无法完成 TLS + HTTP。
262	        //
263	        // 注意这里判的是"全部失败"，单个受控目标返回 404/500 不构成失败 ——
264	        // 收到任意合法 HTTP 状态码即证明 HTTPS transport 存在，
265	        // endpoint 自身的业务状态不是 Internet 的判决依据。
266	        const bool active_https_app =
267	            (active_https.applicability == Applicability::APPLICABLE &&
268	             profile == AssessmentProfile::INTERNET_ACCESS &&
269	             active_https.capability_level_negative);
270	        if (active_https_app && active_https.state == HealthState::BAD) {
271	            exp.overall = HealthState::BAD;
272	            exp.primary_issue =
273	                (active_https.reason == "active_https_cert_verification_failed")
274	                    ? "HTTPS certificate verification failed on all controlled targets"
275	                    : "Internet HTTPS capability failed (all controlled targets)";
276	            exp.display_score = 20;
277	            return exp;
278	        }
279	
280	        // Portal 观测到信号但未达 quorum（单端点异常）：仅提示，不改变状态
281	        if (active_portal.reason == "portal_suspected_single_endpoint") {
282	            exp.warnings.push_back(
283	                "A controlled portal-check endpoint behaved unexpectedly, but the "
284	                "signal did not reach quorum across independent failure domains; "
285	                "not treated as a captive portal");
286	        }
287	
288	        // Passive TCP 建连失败：**non-blocking observed service**。
289	        //
290	        // 被动 TCP 观测的是"本机连向任意目的地的结果"，而目的地由用户业务决定，
291	        // 可能本来就该失败（已下线服务器、被防火墙拦截的端口、不存在的服务）。
292	        // 因此它无权单独把 INTERNET_ACCESS 判为 BAD/DEGRADED —— 那等于用
293	        // 未知目的地的失败冒充 Internet ground truth。
294	        // 自身 SLE 可继续为 BAD 并展示证据，但 Overall 不受其影响。
295	        // 只有受控主动探测（ACTIVE_PROBE）才具备判定 Internet 可用性的资格。
296	        if (tcp_app && tcp_connect.state == HealthState::BAD) {
297	            exp.warnings.push_back(
298	                "Observed TCP connect failures on application endpoints (not an Internet availability verdict)");
299	        }
300	        const bool tcp_rtt_app = (tcp_rtt.applicability == Applicability::APPLICABLE &&
301	                                  profile == AssessmentProfile::INTERNET_ACCESS &&
302	                                  (tcp_rtt.state != HealthState::UNKNOWN || tcp_rtt.coverage != Coverage::NONE));
303	        if (tcp_rtt_app && tcp_rtt.state == HealthState::BAD) {
304	            exp.warnings.push_back(
305	                "Observed high passive TCP srtt on application flows (advisory, endpoint-dependent)");
306	        }
307	
308	        // Captive Portal：仅当存在受控探测证据时才可确诊。
309	        // scope == NO_CAPABILITY 表示当前没有可靠的 portal 判定能力
310	        // （capture 不提取 Location，也没有主动 probe），此时无权做任何决策。
311	        const bool portal_has_capability =
312	            (captive_portal.scope != EvidenceScope::NO_CAPABILITY) &&
313	            (captive_portal.source != EvidenceSource::UNSPECIFIED);
314	        if (portal_has_capability && captive_portal.state == HealthState::BAD) {
315	            exp.overall = HealthState::BAD;
316	            exp.primary_issue = "Captive portal interception detected";
317	            exp.display_score = 20;
318	            return exp;
319	        }
320	
321	        // Passive cleartext HTTP 失败：同样 non-blocking。
322	        // 当前 scope 仅覆盖明文 HTTP（TLS 后无法识别），且目的地由用户业务决定，
323	        // 不足以判定 Internet 可用性。
324	        if (http_app && http_access.state == HealthState::BAD) {
325	            exp.warnings.push_back(
326	                "Observed cleartext HTTP failures (scope: cleartext only, not an Internet availability verdict)");
327	        }
328	
329	        // 2. Major BAD (Responsiveness 严重劣化 → DEGRADED)
330	        if (resp_app && resp.state == HealthState::BAD) {
331	            exp.overall = HealthState::DEGRADED;
332	            exp.primary_issue = "High latency or excessive jitter";
333	            exp.display_score = 55;
334	            return exp;
335	        }
336	
337	        // 3. 任一核心 SLE DEGRADED（负面证据优先）
338	        bool reach_degraded = (reach_app && reach.state == HealthState::DEGRADED);
339	        bool rel_degraded = (rel_app && rel.state == HealthState::DEGRADED);
340	        bool resp_degraded = (resp_app && resp.state == HealthState::DEGRADED);
341	        // 被动 Service SLE（TCP / Cleartext HTTP）即便 DEGRADED 也不改变 Overall：
342	        // 若允许它们把 Overall 压到 DEGRADED，本质上仍是用未知目的地的失败
343	        // 评价 Internet，只是从 BAD 改成 DEGRADED，语义漏洞并未消失。
344	        bool dns_degraded = (dns_app && dns.state == HealthState::DEGRADED);
345	        const bool tcp_degraded = (tcp_app && tcp_connect.state == HealthState::DEGRADED);
346	        const bool http_degraded = (http_app && http_access.state == HealthState::DEGRADED);
347	        if (tcp_degraded) {
348	            exp.warnings.push_back(
349	                "Observed TCP connect degradation on application endpoints (non-blocking)");
350	        }
351	        if (tcp_rtt_app && tcp_rtt.state == HealthState::DEGRADED) {
352	            exp.warnings.push_back(
353	                "Observed elevated passive TCP srtt on application flows (non-blocking)");
354	        }
355	        if (http_degraded) {
356	            exp.warnings.push_back(
357	                "Observed cleartext HTTP degradation (non-blocking, cleartext only)");
358	        }
359	        if (reach_degraded || rel_degraded || resp_degraded || dns_degraded) {
360	            exp.overall = HealthState::DEGRADED;
361	            if (reach_degraded) exp.primary_issue = "Intermittent probe failure";
362	            else if (rel_degraded) exp.primary_issue = "Elevated network packet loss";
363	            else if (dns_degraded) exp.primary_issue = "Elevated DNS resolution failure or latency";
364	            else exp.primary_issue = "Latency fluctuation detected";
365	            exp.display_score = 65;
366	            return exp;
367	        }
368	
369	        // 4. Coverage Gate Minimum Core Coverage：无负面证据但核心 telemetry 不足时输出 UNKNOWN
370	        bool reach_known = (reach_app && reach.state != HealthState::UNKNOWN);
371	        bool rel_known = (rel_app && rel.state != HealthState::UNKNOWN);
372	        bool resp_known = (resp_app && resp.state != HealthState::UNKNOWN);
373	        if (!reach_known || (!rel_known && !resp_known)) {
374	            exp.overall = HealthState::UNKNOWN;
375	            exp.primary_issue = "Insufficient telemetry for network assessment";
376	            exp.display_score = 50;
377	            return exp;
378	        }
379	
380	        // 5. Overall GOOD
381	        exp.overall = HealthState::GOOD;
382	        bool rf_clean = (rf.applicability == Applicability::NOT_APPLICABLE) ||
383	                        (rf.state == HealthState::GOOD);
384	        exp.display_score = rf_clean ? 95 : 85;
385	        return exp;
386	    }
387	};
388	
389	} // namespace weaknet
