9	
10	struct ResponsivenessConfig {
11	    double rtt_good_ms{60.0};
12	    double rtt_bad_ms{150.0};
13	    double jitter_good_ms{15.0};
14	    double jitter_bad_ms{40.0};
15	    double bad_rtt_ratio_threshold{0.30};
16	    size_t min_valid_samples{4};
17	};
18	
19	class ResponsivenessEvaluator {
20	public:
21	    using Config = ResponsivenessConfig;
22	
23	    static SleResult evaluate(const std::vector<MetricSample>& rtt_samples,
24	                             const std::vector<MetricSample>& jitter_samples,
25	                             const Config& cfg = Config()) {
26	        SleResult res;
27	        std::vector<double> valid_rtts;
28	        valid_rtts.reserve(rtt_samples.size());
29	
30	        size_t bad_rtt_count = 0;
31	        for (const auto& s : rtt_samples) {
32	            if (s.state == MetricState::VALID && s.value >= 0.0) {
33	                valid_rtts.push_back(s.value);
34	                if (s.value > cfg.rtt_bad_ms) {
35	                    bad_rtt_count++;
36	                }
37	            }
38	        }
39	
40	        if (valid_rtts.size() < cfg.min_valid_samples) {
41	            res.state = HealthState::UNKNOWN;
42	            res.coverage = Coverage::PARTIAL;
43	            res.reason = "insufficient_rtt_samples";
44	            return res;
45	        }
46	
47	        std::sort(valid_rtts.begin(), valid_rtts.end());
48	        double median_rtt = valid_rtts[valid_rtts.size() / 2];
49	        double bad_ratio = static_cast<double>(bad_rtt_count) / static_cast<double>(valid_rtts.size());
50	
51	        res.evidence.push_back({"median_rtt_ms", median_rtt, "Median RTT in window"});
52	        res.evidence.push_back({"bad_rtt_ratio", bad_ratio * 100.0, "Ratio of RTT samples > " + std::to_string(static_cast<int>(cfg.rtt_bad_ms)) + "ms"});
53	
54	        std::vector<double> valid_jitters;
55	        for (const auto& s : jitter_samples) {
56	            if (s.state == MetricState::VALID && s.value >= 0.0) {
57	                valid_jitters.push_back(s.value);
58	            }
59	        }
60	        double median_jitter = 0.0;
61	        bool has_jitter = false;
62	        if (!valid_jitters.empty()) {
63	            std::sort(valid_jitters.begin(), valid_jitters.end());
64	            median_jitter = valid_jitters[valid_jitters.size() / 2];
65	            has_jitter = true;
66	            res.evidence.push_back({"median_jitter_ms", median_jitter, "Median jitter in window"});
67	        }
68	
69	        res.coverage = has_jitter ? Coverage::FULL_FOR_PROFILE : Coverage::PARTIAL;
70	
71	        bool rtt_bad = (median_rtt > cfg.rtt_bad_ms || bad_ratio >= cfg.bad_rtt_ratio_threshold);
72	        bool jitter_bad = (has_jitter && median_jitter > cfg.jitter_bad_ms);
73	
74	        bool rtt_good = (median_rtt <= cfg.rtt_good_ms && bad_ratio < 0.10);
75	        bool jitter_good = (!has_jitter || median_jitter <= cfg.jitter_good_ms);
76	
77	        if (rtt_bad || jitter_bad) {
78	            res.state = HealthState::BAD;
79	            res.reason = rtt_bad ? "rtt_severely_high_or_volatile" : "jitter_excessive";
80	        } else if (rtt_good && jitter_good) {
81	            res.state = HealthState::GOOD;
82	            res.reason = "rtt_and_jitter_stable_and_low";
83	        } else {
84	            res.state = HealthState::DEGRADED;
85	            res.reason = "latency_or_jitter_suboptimal";
86	        }
87	
88	        return res;
89	    }
90	};
91	
92	} // namespace weaknet
