41	 * @brief DNS 服务健康 SLE 评估器 (无状态纯函数，SR-2, SR-9, SR-10, SR-14)
42	 *
43	 * 核心逻辑：
44	 * 1. Missingness 三态判定 (SR-13 物理依据):
45	 *    - query_started == 0 && inflight == 0 -> UNKNOWN(no_dns_observations) [绝不伪造 GOOD]
46	 *    - inflight > 0 && evaluable_terminals == 0 -> UNKNOWN(awaiting_inflight)
47	 *    - terminals > 0 但不足门禁 -> UNKNOWN(insufficient_terminal_observations)
48	 * 2. SR-9 突发连续严重失败单杀判定 (修正 #1):
49	 *    - 同一 binding_epoch
50	 *    - >= 3 个独立事务 TIMEOUT_EXPIRED
51	 *    - 全部在 critical_window (15s) 内
52	 *    - 首尾两个 critical timeout 之间无任何 known_success terminal
53	 * 3. 失败率与中位数时延评估:
54	 *    - evaluable_terminals = known_success (NOERROR+NXDOMAIN) + known_failure (SERVFAIL+REFUSED+TIMEOUT)
55	 *    - failure_ratio = known_failure / evaluable_terminals
56	 *    - OTHER 和 TRUNCATED 不稀释 failure_ratio (SR-1, SR-14)
57	 *    - 计算有效时延的中位数 (p50)
58	 * 4. Tracking Quality 降级门禁 (SR-8):
59	 *    - classification_coverage 过低 -> UNKNOWN (insufficient_classified_outcomes)
60	 *
61	 * capability_level_negative（是否具备否决 Internet Access 的资格）：
62	 *   只有"本机名字解析能力失效"的证据才置位 —— 即
63	 *     - SR-9 连续超时（解析器完全不响应），或
64	 *     - 失败以 TIMEOUT 为主 **且** 超时涉及多个不同 QNAME
65	 *       （单个域名的权威链路异常不算本机能力故障），或
66	 *     - 解析普遍极慢
67	 *   单域名/单次 SERVFAIL、REFUSED 不置位：那可能是域名自身或策略侧问题，
68	 *   无权把"某个域名解析失败"升级为"Internet 不可用"。
69	 */
70	class DnsServiceEvaluator {
71	public:
72	    using Config = DnsEvaluatorConfig;
73	
74	    static SleResult evaluate(const DnsMetricWindow& window,
75	                             const std::vector<DnsTransactionRecord>& recent_terminals,
76	                             const Config& cfg = Config(),
77	                             bool* out_is_critical_bypass = nullptr) {
78	        SleResult res;
79	        res.applicability = Applicability::APPLICABLE;
80	        // DNS 证据来自真实 DNS 事务（被动观测），scope 是本机解析能力。
81	        res.source = EvidenceSource::PASSIVE_REAL_TRAFFIC;
82	        res.scope = EvidenceScope::HOST_RESOLVER_CAPABILITY;
83	        if (out_is_critical_bypass) *out_is_critical_bypass = false;
84	
85	        // 1. Missingness 三态检查
86	        if (window.queries_started == 0 && window.current_inflight == 0) {
87	            res.state = HealthState::UNKNOWN;
88	            res.coverage = Coverage::NONE;
89	            res.reason = "no_dns_observations";
90	            return res;
91	        }
92	
93	        uint64_t evaluable = window.evaluableTerminals();
94	
95	        if (window.current_inflight > 0 && evaluable == 0) {
96	            res.state = HealthState::UNKNOWN;
97	            res.coverage = Coverage::PARTIAL;
98	            res.reason = "awaiting_inflight";
99	            return res;
100	        }
101	
102	        // 2. SR-9 突发严重失败 Bypass 判定 (修正 #1: 连续 3 次超时且无成功穿插)
103	        if (checkCriticalTimeoutBypass(recent_terminals, window.binding_epoch, cfg.critical_timeout_count, cfg.critical_window, window.evaluation_cutoff)) {
104	            res.state = HealthState::BAD;
105	            res.coverage = Coverage::FULL_FOR_PROFILE;
106	            // 连续 3 个独立事务无任何响应且无成功穿插 → 解析器能力级故障
107	            res.capability_level_negative = true;
108	            res.reason = "critical_burst_timeouts";
109	            res.evidence.push_back({"burst_timeouts", static_cast<double>(cfg.critical_timeout_count), "Burst consecutive timeouts detected without success"});
110	            if (out_is_critical_bypass) *out_is_critical_bypass = true;
111	            return res;
112	        }
113	
114	        // 3. 终态门禁检查
115	        if (evaluable < cfg.min_terminals_for_evaluation) {
116	            res.state = HealthState::UNKNOWN;
117	            res.coverage = Coverage::PARTIAL;
118	            res.reason = "insufficient_terminal_observations";
119	            return res;
120	        }
121	
122	        // 4. Tracking Quality 覆盖度检查 (SR-8)
123	        double coverage_ratio = window.classificationCoverage();
124	        if (coverage_ratio < cfg.min_classification_coverage) {
125	            res.state = HealthState::UNKNOWN;
126	            res.coverage = Coverage::PARTIAL;
127	            res.reason = "insufficient_classified_outcomes";
128	            res.evidence.push_back({"classification_coverage", coverage_ratio, "Ratio of classified outcomes is below threshold"});
129	            return res;
130	        }
131	
132	        // 4b. Observer 质量评估。注意：这里**不立即返回**。
133	        //     直接负面证据（SERVFAIL/REFUSED 等真实捕获的错误响应）即使观测覆盖不完美也成立，
134	        //     只有"缺席推导"的故障（TIMEOUT）才会被观测丢失污染。
135	        //     因此观测不可靠时：有直接坏证据 -> 继续裁决但降 coverage；
136	        //                       无直接坏证据 -> UNKNOWN，绝不把观测缺陷伪装成 DNS 故障。
137	        std::string observer_reason = checkObserverQuality(window, cfg);
138	        const bool observer_unreliable = !observer_reason.empty();
139	        const bool has_direct_negative = window.directNegativeEvidence() > 0;
140	        if (observer_unreliable) {
141	            res.evidence.push_back({"capture_emit_failure_ratio", window.captureEmitFailureRatio(),
142	                                    "BPF capture emit failure ratio"});
143	            res.evidence.push_back({"perf_delivery_loss_ratio", window.perfDeliveryLossRatio(),
144	                                    "Perf buffer delivery loss ratio"});
145	            res.evidence.push_back({"ambiguity_ratio", window.ambiguityRatio(),
146	                                    "Transaction matching ambiguity ratio"});
147	            res.evidence.push_back({"insert_failure_ratio", window.insertFailureRatio(),
148	                                    "Tracker capacity overflow ratio"});
149	        }
150	        if (observer_unreliable && !has_direct_negative) {
151	            res.state = HealthState::UNKNOWN;
152	            res.coverage = Coverage::PARTIAL;
153	            res.reason = observer_reason;
154	            return res;
155	        }
156	
157	        // coverage：观测不可靠但有直接坏证据时降级为 PARTIAL，故障结论仍成立
158	        res.coverage = observer_unreliable ? Coverage::PARTIAL : Coverage::FULL_FOR_PROFILE;
159	        if (observer_unreliable) {
160	            res.evidence.push_back({"observer_warning", 1.0,
161	                                    "Direct negative evidence is trustworthy, but observer quality is degraded"});
162	        }
163	
164	        // 5. 失败率与时延中位数计算
165	        double fail_ratio = window.failureRatio();
166	        res.evidence.push_back({"failure_ratio", fail_ratio, "Ratio of failed terminals over evaluable terminals"});
167	
168	        double median_latency = 0.0;
169	        if (!window.latencies_ms.empty()) {
170	            std::vector<double> sorted_lat = window.latencies_ms;
171	            std::sort(sorted_lat.begin(), sorted_lat.end());
172	            size_t mid = sorted_lat.size() / 2;
173	            if (sorted_lat.size() % 2 == 0) {
174	                median_latency = (sorted_lat[mid - 1] + sorted_lat[mid]) / 2.0;
175	            } else {
176	                median_latency = sorted_lat[mid];
177	            }
178	            res.evidence.push_back({"median_latency_ms", median_latency, "Median transaction latency"});
179	        }
180	
181	        // 6. 状态阶梯裁决
182	        // 失败率按**类型**区分是否具备 host-level 否决权。
183	        //
184	        // 关键区分：解析器"答不答"与"答什么"是两件事。
185	        //   TIMEOUT  —— 解析器完全没响应 => 本机解析能力失效（capability 级）
186	        //   SERVFAIL —— 解析器答了，但上游/权威侧解析失败。可能是该域名自身
187	        //               或权威侧问题，不能自动等同于本机能力故障
188	        //   REFUSED  —— 明确的策略拒绝，几乎总是域名/策略侧问题
189	        //
190	        // 因此不能用聚合 failure_ratio 触发否决权：小样本下单个域名的
191	        // SERVFAIL 就可能超过 20% 阈值，从而把一个域名的问题升级成
192	        // "Internet 不可用"。否决权只由 timeout 占比决定。
193	        const double timeout_ratio = evaluable > 0
194	            ? static_cast<double>(window.timeouts) / static_cast<double>(evaluable)
195	            : 0.0;
196	
197	        if (fail_ratio >= cfg.error_ratio_bad) {
198	            res.state = HealthState::BAD;
199	            res.reason = "high_failure_rate";
200	            // 授予否决权需同时满足两个条件：
201	            //   1. 失败以"无响应"（TIMEOUT）为主 —— 解析器答不出来
202	            //   2. 超时涉及**多个不同 QNAME** —— 排除单域名权威链路异常
203	            // 任一不满足则只作 warning/evidence，不 veto Internet Access。
204	            const bool timeout_dominant = (timeout_ratio >= cfg.error_ratio_bad);
205	            const bool multi_qname = (window.timeout_distinct_qnames >= cfg.capability_min_distinct_qnames);
206	            res.capability_level_negative = timeout_dominant && multi_qname;
207	
208	            res.evidence.push_back({"timeout_ratio", timeout_ratio * 100.0,
209	                                    "Timeout share of evaluable terminals %"});
210	            res.evidence.push_back({"timeout_distinct_qnames",
211	                                    static_cast<double>(window.timeout_distinct_qnames),
212	                                    "Distinct QNAMEs among timeouts"});
213	            if (timeout_dominant && !multi_qname) {
214	                res.evidence.push_back({"capability_veto_withheld", 1.0,
215	                    "Timeouts concentrated on a single QNAME; not a resolver-capability verdict"});
216	            }
217	            return res;
218	        }
219	        if (median_latency >= cfg.median_latency_bad_ms) {
220	            res.state = HealthState::BAD;
221	            // 解析普遍变慢同样是本机解析能力的退化
222	            res.capability_level_negative = true;
223	            res.reason = "excessive_dns_latency";
224	            return res;
225	        }
226	
227	        if (fail_ratio >= cfg.error_ratio_degraded) {
228	            res.state = HealthState::DEGRADED;
229	            res.reason = "elevated_failure_rate";
230	            return res;
231	        }
232	        if (median_latency >= cfg.median_latency_degraded_ms) {
233	            res.state = HealthState::DEGRADED;
234	            res.reason = "elevated_dns_latency";
235	            return res;
236	        }
237	
238	        res.state = HealthState::GOOD;
239	        res.reason = "dns_service_healthy";
240	        return res;
241	    }
242	
243	private:
244	    /**
245	     * @brief 观测质量检查。返回空字符串表示观测可信；否则返回机器可读的降级原因。
246	     *
247	     * 两级传输分别计量（BPF capture 与 perf buffer），不合并成单一数字——
248	     * 两者是否描述同一轮拥塞尚未验证，合并会掩盖真实边界。
249	     * 样本不足时不做判定，避免小样本误判。
250	     */
251	    static std::string checkObserverQuality(const DnsMetricWindow& window, const Config& cfg) {
252	        if (window.capture_attempts < cfg.observer_min_capture_attempts &&
253	            window.delivered_events == 0) {
254	            return {}; // 样本不足，不判定观测质量
255	        }
256	        if (window.captureEmitFailureRatio() > cfg.max_capture_emit_failure_ratio) {
257	            return "observer_unreliable_capture_emit_failure";
258	        }
259	        if (window.perfDeliveryLossRatio() > cfg.max_perf_delivery_loss_ratio) {
260	            return "observer_unreliable_event_loss";
261	        }
262	        if (window.ambiguityRatio() > cfg.max_ambiguity_ratio) {
263	            return "observer_unreliable_ambiguity";
264	        }
265	        if (window.insertFailureRatio() > cfg.max_insert_failure_ratio) {
266	            return "tracker_capacity_overflow";
267	        }
268	        return {};
269	    }
270	
271	    static bool checkCriticalTimeoutBypass(const std::vector<DnsTransactionRecord>& terminals,
272	                                           uint64_t target_epoch,
273	                                           size_t burst_count,
274	                                           std::chrono::milliseconds window_dur,
275	                                           std::chrono::steady_clock::time_point cutoff) {
276	        if (terminals.size() < burst_count) return false;
277	
278	        // 从最新的记录往回看
279	        size_t consecutive_timeouts = 0;
280	        std::chrono::steady_clock::time_point newest_timeout;

