        << "\"description\":\"" << weaknet_utils::escapeJsonString(description) << "\","
        << "\"detected_at_ms\":" << detected_at_ms << ","
        << "\"evidence\":{"
        << "\"tx_bytes\":" << tx_bytes << ","
        << "\"rx_bytes\":" << rx_bytes << ","
        << "\"actual_bps\":" << actual_bps << ","
        << "\"expected_bps\":" << expected_bps << ","
